// Auto-generated grammar notes for all books
// Do not edit manually - regenerate with scripts/generate-book-data
//
// Shape: bookGrammar[bookId][difficulty] = GrammarNote[][]
//   - Outer array: one entry per book "part" (chapter-like split).
//   - Single-part books are still wrapped as [notes] for uniformity.

export interface GrammarNote {
  pattern: string;
  meaning: string;
  example: string;
  jlpt: string;
  tip: string;
}

/** Per-part notes for (book, difficulty). Returns [] if missing. */
export function getGrammarForPart(bookId: string, difficulty: string, partIdx: number): GrammarNote[] {
  const parts = bookGrammar[bookId]?.[difficulty];
  if (!parts || !Array.isArray(parts)) return [];
  // Support both shapes: GrammarNote[] (legacy flat) and GrammarNote[][] (parts).
  if (parts.length === 0) return [];
  if (!Array.isArray((parts as unknown[])[0])) return [];
  return ((parts as unknown) as GrammarNote[][])[partIdx] ?? [];
}

/** Flattened notes for (book, difficulty) — concatenates all parts. */
export function getGrammarFlat(bookId: string, difficulty: string): GrammarNote[] {
  const parts = bookGrammar[bookId]?.[difficulty];
  if (!parts || !Array.isArray(parts)) return [];
  if (parts.length === 0) return [];
  if (!Array.isArray((parts as unknown[])[0])) return parts as unknown as GrammarNote[];
  return (parts as unknown as GrammarNote[][]).flat();
}

export const bookGrammar: Record<string, Record<string, GrammarNote[][]>> = {"a-aki":{"simplified":[[{"example":"たくさん書いてありました","tip":"誰がしたかではなく、ある人の行動の結果に焦点を当てる他動詞と一緒に使われます。","meaning":"意識的な行動の結果として残っている状態を表します。","pattern":"～てある / ～てあります","jlpt":"N5"},{"pattern":"～と (conditional)","tip":"自然の法則、機械（ボタンを押す）、または定められた一連の出来事にこれを使用してください。","meaning":"Aが起きると、Bが自然に、または必然的に続きます。","example":"秋になると","jlpt":"N5"},{"pattern":"～そうです (hearsay)","meaning":"情報が別の情報源から聞かれたり読まれたりしたことを示します（伝聞）。","tip":"「～そうです」 (looks like) とは異なり、伝聞の「～そうです」は常に辞書形（普通形）が続きます。","example":"透けて見えるそうです","jlpt":"N4"},{"tip":"「～に思う」を使うと、感情的な反応や主観的な視点を示唆することがよくあります。","meaning":"本能的にある考えや感情を抱くこと。","example":"可哀想に思いました","pattern":"～に思う / ～とおもう","jlpt":"N4"},{"jlpt":"N3","meaning":"ある状態や状況が続いている間。","tip":"今しないと機会がなくなることをしばしば示唆します（例：夏のうちに）。","example":"夏のうちはにできています","pattern":"～うちに"},{"jlpt":"N4","pattern":"～よう (Volitional form)","example":"夏休みに海へ行こう","tip":"グループ2の動詞（る動詞）では、「る」を「よう」に置き換えます。グループ1の動詞（う動詞）では、「う」の音を「お」に変えて「う」を追加します。","meaning":"「～しよう」という形は、意思や勧誘を表すのに使われます。"},{"example":"話しているのを見ると","tip":"見る、聞く、待つなどの直接的な知覚を伴う動詞が続く場合は、「こと」ではなく「の」を使用します。","meaning":"動詞を名詞化して、行動を名詞や目的語に変えます。","pattern":"～の (Nominalizer)","jlpt":"N4"},{"jlpt":"N3","pattern":"～ようです","example":"書いたようです","tip":"証拠に基づいた論理的な推測を示唆しており、「～のようだ」や「～のように見える」と似ています。","meaning":"話し手が観察したことに基づく推測や外見を表します。"}]],"intermediate":[[{"example":"詩材の準備をしておくのである。","pattern":"～ておく","tip":"準備の側面に焦点を当てています。後での準備のために今何かをするという意味です。","meaning":"前もって、または将来の使用のために何かをすること。","jlpt":"N4"},{"tip":"動詞の場合、語尾の「う」の音を「え」に変えて「ば」を追加します。論理的な結果を表すことがよくあります。","meaning":"接続詞の「もし～ならば」または「～の時」。","jlpt":"N4","example":"「秋について」という注文が来れば","pattern":"～ば"},{"meaning":"～のようだ / ～と聞いた（証拠に基づいた推測を示す）。","tip":"推測の根拠はあるが、100%確信があるわけではない場合に使用します。","jlpt":"N4","pattern":"～らしい","example":"精神だけがふらふら飛んでいる様子を指して言っているらしい。"},{"tip":"例を挙げることで、状態や感情の程度を説明するために使用されます。","meaning":"～の程度まで / ～ほど（非常に）。","jlpt":"N3","example":"私は胸が焼け焦げるほどに、そのみじめな女を恋した。","pattern":"～ほど"},{"pattern":"～と (conditional)","example":"耳を澄まして注意していると","jlpt":"N4","meaning":"～の時/もし～ならば（自然な、または必然的な結果が続く）。","tip":"この文脈では、行動を起こしたときに自然に起こる何かの発見を示します。"},{"meaning":"～にもかかわらず / ～なのに（しばしば文末で後悔や不満を示す）。","tip":"文の最後に来る場合、「そうであってほしい」または「状況にもかかわらず」といった意味合いをしばしば含みます。","jlpt":"N3","pattern":"～のに","example":"もう秋が夏と一緒に忍び込んで来ているのに。"},{"pattern":"～ともなれば","example":"本職の詩人ともなれば、いつどんな注文があるかわからない。","jlpt":"N1","meaning":"～ということになると / ～が～になると（特別な地位や階級を強調する）。","tip":"これは、期待が自然に変わる高位の地位や重要な状況に使用されます。"}]],"original":[[{"meaning":"将来の使用のために何かを事前にする、または何かを特定の状態のままにしておく (to do something in advance for future use or to leave something in a certain state)。","tip":"会話では、これはしばしば短縮されます: ～ておく は ～とく (becomes ～toku) となります。","jlpt":"N4","pattern":"～ておく (～て置く)","example":"準備をして置くのである。"},{"meaning":"観察または情報に基づいた推測を示す表現で、「～のようだ (it seems like)」または「～らしい (apparently)」。","jlpt":"N4","tip":"「よだ (yoda)」とは異なり、「～らしい (rashii)」は、結論に客観的な根拠や噂がある場合に使用されます。","pattern":"～らしい","example":"精神だけがふらふら飛んでいる様子を指して言っている言葉らしい。"},{"pattern":"～ぬ (～ず)","example":"それを見破ることが出来ぬ。","meaning":"動詞の文語的または形式的な否定形で、～ない と同等です。","tip":"文学やことわざでよく見られます。「する (suru)」は「せぬ (senu)」に、「くる (kuru)」は「こぬ (konu)」になります。","jlpt":"N3"},{"meaning":"特定の高いレベルや特別な地位に達すると、物事が自然に変化したり深刻になったりすることを強調します。","tip":"役割、職業、または特別な状況に使用され、より高い期待基準を示します。","jlpt":"N1","pattern":"～ともなれば / ～ともなると","example":"本職の詩人ともなれば、いつどんな注文があるか..."},{"pattern":"～ほど (～ほどに)","example":"胸が焼き焦げるほどにそのみじめな女を恋した。","meaning":"行為または状態の程度または範囲を示します。「～の程度まで (to the extent that...)」。","jlpt":"N3","tip":"これを感情や出来事の極端な限界と比較することで、描写に劇的さや強調を加えることができます。"},{"meaning":"何かが特定の方法であるはずだ、またはあったはずだという期待や信念を示し、それがそうでない場合に後悔や驚きを伴うことが多いです。","jlpt":"N3","tip":"「～のに (noni)」が続く場合、現実が期待と反対であることを強く示唆します。","pattern":"～はず (～筈)","example":"弱者の友であった筈なのに。"},{"meaning":"理由や原因を表現する形式的または文語的な方法で、「～なので (because)」または「～が原因で (due to)」。","tip":"これは非常に堅苦しく形式的です。現代の会話では、「～ので (node)」または「～から (kara)」を使用します。一部の表現では、「ゆえ (yue)」に短縮されます。","jlpt":"N2","pattern":"～がゆえに (～が故に)","example":"並ハズレテ、タクマシキガ故ニ、死ナズ在リヌル。决シテ、ハカナキ態ニハ非ズ。と書かれてある。"}]]},"kumo-no-ito":{"simplified":[[{"example":"いいにおいがしていました。","meaning":"過去の継続的な状態または行動を説明するために使用されます。","jlpt":"N5","tip":"「何かをしている (doing something)」または「ある状態である (being in a state)」の過去形だと考えてください。","pattern":"～ていました"},{"example":"悪いことをたくさんしました。","jlpt":"N5","meaning":"動詞や形容詞を名詞化して、「こと (thing(s))」、「行為 (action)」、または「事実 (fact)」を意味します。","tip":"単純な行動を「話題 (topic)」または話すことができる「事柄 (thing)」に変えたい場合に使用します。","pattern":"～こと"},{"jlpt":"N5","meaning":"何かをした経験があることを表現するために使用されます。","tip":"このフレーズの前には常に過去形 (た-form) を使用してください。これは一般的な人生経験についてのものであり、今日したことについてではありません。","pattern":"～たことがあります","example":"いいことをしたことがあります。"},{"jlpt":"N4","meaning":"何かを定義したり命名したりするために使用されます（「Aと呼ばれるB」）。","pattern":"～という","tip":"人、本、または場所を名前で紹介するために不可欠です。例えば、「犍陀多という男 (The guy named Kandata.)」のように言います。","example":"犍陀多という男"},{"tip":"これは意志形（～よう form）を使用します。行動を試みたが実際に完了しなかったことを示唆することがよくあります。","pattern":"～ようとする","meaning":"何かをしようとする、または何かをしようとしているところである。","jlpt":"N4","example":"踏もうとしましたが"},{"meaning":"論理に基づいた強い期待や信念を表します。「～のはずだ (should be)」または「～に違いありません (it must be)」。","jlpt":"N3","pattern":"～はずだ","tip":"証拠や物事の性質に基づいて、何かが99%確かである場合に使用します。","example":"生きたいと思っているはずだ"},{"example":"地獄から助けようと思いました。","jlpt":"N4","meaning":"話し手の意図や何かをする決意を表すために使用されます。","pattern":"～よう（意向形）と思う","tip":"計画していることや考えていることについて話すには、意志形 + と思う を使用します。"}],[{"example":"地獄の暗い中にいました。","jlpt":"N5","meaning":"存在の状態（生物の主語の場合）","tip":"人や動物には「いる」、無生物には「ある」を使用します。","pattern":"～にいる (いました)"},{"example":"下りてきていました。","meaning":"過去における継続的な行動（進行形） (Ongoing action in the past (progressive))","jlpt":"N5","tip":"これは「〜ている」 (is doing) の過去形版だと考えてください。","pattern":"～ていた (ていました)"},{"tip":"動詞の場合、語尾の「う」の音を「え」に変えて「ば」を付けます。結果に必要な条件に焦点を当てています。","pattern":"～ば","example":"登れば極楽へ行けるかもしれない！","meaning":"条件形「もし」(Provisional form)","jlpt":"N4"},{"example":"極楽へ行けるかもしれない！","jlpt":"N4","meaning":"可能性を示す、または「かもしれない」 (Indicates possibility or \"might/maybe\")","tip":"50%以下の確信度の場合に使います。動詞や形容詞の普通形に続きます。","pattern":"～かもしれない"},{"example":"疲れたので、少し休みました。","meaning":"理由を述べる（〜ので／〜だから） (Giving a reason (since/because))","jlpt":"N4","tip":"「ので」は「から」よりも客観的で丁寧な響きがあります。状況を説明したり、言い訳をしたりする際によく使われます。","pattern":"～ので"},{"example":"もう少しで出られるかもしれない","meaning":"可能形（〜できる） (Potential form (can do/be able to do))","jlpt":"N4","pattern":"～られる (Potential) vocalic/Ichidan","tip":"一段動詞（例: 出る）の場合、「る」を「られる」に置き換えます。くだけた会話では、「ら」がしばしば省略されます（例: 出れる）。"}],[{"meaning":"説明的な調子を加えることで、状況を説明したり理由を与えたりします。","jlpt":"N4","pattern":"～のだ / ～のです / ～んです","tip":"何かが起こった「理由」を説明したり、背景にある気づきを提供したりするときに使います。","example":"登っていたのです"},{"example":"ついてきていました","pattern":"～てくる / ～てきました","tip":"語り手の視点に向かってくる動きを想像してみてください。","jlpt":"N4","meaning":"話し手に向かってくる行動、または過去から現在にかけての継続的な動きを示します。"},{"jlpt":"N4","meaning":"行動Aが起こったときに、行動B（しばしば予期せぬ）が発見されることを示します。","pattern":"～（辞書形）＋と","tip":"この「と」は事実の引き金のようなものです。「Xが起こると、Yが自然に続くか、Yが見られる」。","example":"気がつくと"},{"jlpt":"N4","meaning":"行動の完了を表し、しばしば後悔や意図しない結果を伴います。","tip":"この文脈では、取り返しのつかない否定的な結果（糸が切れること）への恐れを強調しています。","pattern":"～てしまう / ～ちゃう","example":"糸が切れてしまう！"},{"jlpt":"N4","meaning":"状態の変化または特定の状態になることを示します。","pattern":"い形容詞（～く）＋なる / な形容詞（～に）＋なる","tip":"形容詞の語尾の「い」を削除し、「なる」の前に「く」を追加して、感情や状態の変化を示します。","example":"怖くなりました"},{"tip":"「俺」（男性の荒っぽい一人称代名詞）と組み合わせることで、所有に対する強く、自己中心的な主張を示します。","pattern":"Noun + のもの","jlpt":"N5","meaning":"所有を示す（私のもの）。「もの」は物理的な物や客体を指します。","example":"俺のものだ！"}],[{"example":"銀色の糸だけが、まだ上から下がっていました。","pattern":"～ている / ～ていた","tip":"進行中の行動（〜している）や、行動の結果の状態（ぶら下がっている／咲いている）に使用します。","meaning":"行動または状態の継続性を示します。","jlpt":"N5"},{"tip":"「しか」とは異なり、「だけ」は肯定的な動詞と一緒に使用され、何かが排他的な焦点であることを強調します。","pattern":"～だけ","example":"自分だけ助かろうとしました。","meaning":"のみ；ただ（制限を示す）。","jlpt":"N5"},{"meaning":"〜そう（な） (looks like; appears to be (based on visual impression)).","jlpt":"N4","example":"とても悲しそうなかおをしました。","pattern":"～そう（な）","tip":"形容詞に接続する場合、語尾の「い」または「な」を削除します。他の人の感情や外見に対するあなたの観察を表現します。"},{"jlpt":"N4","meaning":"〜しようとする (to try to; to attempt to do something).","example":"自分だけ助かろうとしました。","tip":"これは試み、あるい人が行動を始めようとしている瞬間を表します。しばしば、試みが失敗したときに使われます。","pattern":"Volitional Form + とした (とする)"},{"meaning":"行動の完了を示し、しばしば後悔や偶発的な結果を伴います。","jlpt":"N4","example":"それが糸を切ってしまったのです。","tip":"この物語では、糸が切れてしまったことの不運で元に戻せない性質を強調しています。","pattern":"～てしまう / ～てしまった"},{"example":"それが糸を切ってしまったのです。","tip":"状況の「なぜ」または「どのように」を聞き手に説明したいときにこれを使用します。","pattern":"～のだ / ～のです / ～んです","meaning":"説明、強調、または理由を提供するのに使用されます。","jlpt":"N4"}]],"intermediate":[[{"tip":"「～ています」 (is doing) の過去形と考えてください。物語の場面設定に使われます。","meaning":"過去における進行中の行動または状態を示します。(過去連続)","example":"歩いていました","jlpt":"N5","pattern":"～ていました"},{"meaning":"何かをしようとすること、または何かをしようとしていること。","jlpt":"N4","example":"踏み潰そうとしましたが","pattern":"Volitional form + と（する/した）","tip":"動詞の意向形に「と する」を付けます。多くの場合、その試みが成功しなかったことを暗示します。"},{"example":"生きたいと思っているはずだ","jlpt":"N4","meaning":"何かが真実であるという強い信念または期待を表現します。(確かに…)","pattern":"～はずだ","tip":"何かが起こる、またはそうであると信じる論理的な理由があるときにこれを使用します。"},{"tip":"注意してください！現代日本語では、「～てあげる」の方が安全です。非常にくだけた、または攻撃的な響きにしたい場合を除き、人に対しては使用を避けてください。","pattern":"～てやる","meaning":"自分より低い地位の人（または動物/植物）のために何かをすること。少し無礼または優越的に聞こえることがあります。","example":"蜘蛛を助けてやったのです","jlpt":"N4"},{"tip":"多くの場合、「言えない」と組み合わされて、「絶妙な」または「言葉では表現できない」という意味になります。","meaning":"言葉では言い表せない。何/どのように（通常は強調のために）言えない。","example":"何とも言えないよい香り","jlpt":"N3","pattern":"何とも～ない"},{"tip":"これは、話者（または主語）の心の中で進行している計画や思考プロセスを表現するために使用されます。","jlpt":"N3","example":"地獄から救い出してやろうと考えました","meaning":"何かをすることを考える。何かをするつもりである。","pattern":"Volitional form + と考える/と思う"},{"tip":"「目」（め）と「掛ける」（かける）に由来します。特定の目標に向かって強い意図を持って動くことを意味します。","meaning":"狙って、～の方へ、～の方向に。","jlpt":"N1","example":"地獄の底めがけて","pattern":"～をめがけて"}],[{"pattern":"～と一緒に","jlpt":"N5","tip":"「一緒」（いっしょ）は「together」を意味します。「に」は一緒にいるという行動の目的地を示します。","example":"罪人たちと一緒に","meaning":"～と一緒に（人またはグループと）。"},{"tip":"これは、完了するまでに時間がかかる行動に使用し、瞬間的な行動には使用しません。","example":"よじ登り始めました","meaning":"何かをし始める（動詞の語幹に付く）。","pattern":"Stem + 始める","jlpt":"N4"},{"example":"光りながら","tip":"主な行動は「ながら」の後に来ます。例えば、「歩きながら食べる」では、「歩く」が副次的な行動です。","meaning":"～しながら（2つの行動が同時に起こる）。","pattern":"Stem + ながら","jlpt":"N4"},{"meaning":"～かもしれない。おそらく。(可能性を示す)","tip":"これは名詞、形容詞、または動詞の普通形の後ろに使うことができます。くだけた会話では、「かも」と短縮されることが多いです。","example":"行けるかもしれない","jlpt":"N4","pattern":"～かもしれない"},{"pattern":"～ば","jlpt":"N3","tip":"動詞の場合、語尾の「う」の音を「え」の音に変えて「ば」を付けます。これはしばしば一般的な真理や論理的な結果に使用されます。","example":"登り続ければ","meaning":"仮定形の「もし～なら」"},{"meaning":"～てくる。徐々に～し始める（現在に向かってくる行動や変化を示す）。","tip":"この文脈では、話し手に向かってくる物理的な動き、またはある時点に到達する心理的な変化を示します。","example":"かなり高くまで登ってきたこと","jlpt":"N3","pattern":"Verb (Te-form) + くる"},{"pattern":"～ではないか / ではありませんか","jlpt":"N2","example":"降りてきているではありませんか","tip":"In literature, this rhetorical question is used to emphasize a sudden realization or an unexpected sight.","meaning":"～ではないか / ではありませんか: Isn't it...?; Behold! (Expressing surprise or highlighting a discovery)"}],[{"tip":"In this context, it describes the physical motion of moving further away from the starting point up the thread.","pattern":"～ていく (te-iku)","meaning":"～ていく (ていく): to go away from the speaker / to continue doing into the future","example":"糸を登っていくのを見て","jlpt":"N5"},{"pattern":"～かもしれない (kamoshirenai)","tip":"Often used to express worries or uncertainties. It follows the Dictionary form (普通形) of verbs and adjectives.","jlpt":"N4","meaning":"～かもしれない (かもしれない): might; perhaps; indicates a possibility of something happening","example":"細い糸が切れてしまうかもしれない"},{"pattern":"～のに (noni)","tip":"It connects two contrasting ideas. In this story, it emphasizes the frustration of the effort going to waste.","jlpt":"N4","example":"せっかくここまで登ってきたのに","meaning":"～のに (のに): even though; despite (expresses regret, complaint, or surprise)"},{"tip":"Used here for a sequential action where the second action (shouting) follows naturally or immediately after the first (thinking).","pattern":"V-dict + と (to)","example":"そう思うと、犍陀多は大声で叫びました。","meaning":"動詞普通形 + と (と): when; if; indicates that an action results in a certain outcome or discovery","jlpt":"N4"},{"pattern":"～ではないか / ～ではありませんか (dewa nai ka)","tip":"In literature, this is often used to highlight a surprising discovery or to draw the reader's attention to a fact.","jlpt":"N3","example":"ついているではありませんか。","meaning":"～ではないか / ～ではありませんか (ではないか): isn't it? (rhetorical question used for emphasis or discovery)"},{"pattern":"V-Plain past + 瞬間 (shunkan)","tip":"Literally translates to 'the moment that [verb] happened.' It is stronger and more specific than just saying 'when'.","jlpt":"N3","example":"その言葉が口から出た瞬間でした。","meaning":"動詞た形 + 瞬間 (瞬間): the moment that...; as soon as..."},{"jlpt":"N2","example":"何かを言う間もなく","meaning":"動詞辞書形 + 間もなく (間もなく): without even time to...; before one can even...","pattern":"V-dict + 間もなく (ma mo naku)","tip":"A formal way to say that something happened so quickly there wasn't even time for the preceding action."}],[{"meaning":"〜ている (ている): Expresses a state or ongoing action (Present Progressive/State)","tip":"For verbs of motion or change (like 'dropping'), it often describes the resulting state.","example":"垂れているだけでした","pattern":"〜ている","jlpt":"N5"},{"pattern":"（意向形）＋とする","example":"自分だけが助かろうとした","jlpt":"N4","tip":"Use this when someone is making an effort to achieve something in that moment.","meaning":"意向形 + とする (とする): Volitional form (意向形) (+ とした) means trying to do or about to do something."},{"jlpt":"N4","example":"地獄に落ちたとき","pattern":"～とき","tip":"Nouns before とき (とき) need の, and 形容動詞 (な-adjective) need な. Verbs can be dictionary or past tense.","meaning":"～とき (とき): When...; at the time that..."},{"pattern":"～のように","example":"足元でいつものように","jlpt":"N3","tip":"Use this to describe actions or states that mimic or resemble a certain pattern or Noun.","meaning":"～のように (のように): Just like...; in the same way as..."},{"meaning":"ご覧になる (ご覧になる): Honorific form (尊敬語) of 見る (to see).","tip":"This is many levels more polite than 見る (miru). You use it for people of higher status, like the Buddha.","jlpt":"N3","pattern":"ご覧になる","example":"その一部始終をご覧になっていました"},{"meaning":"～ていく / ～てくる (ていく / てくる): Indicates an action or state that continues from the present into the future, or moves away from the speaker.","jlpt":"N3","example":"広がっていくのでした","pattern":"～ていく / ～てくる","tip":"In this context, it shows the scent spreading outward away from the center of the lotus."},{"tip":"The combination suggests a regrettable outcome that the speaker is inferring from the situation.","jlpt":"N3","pattern":"～てしまう + ～でしょう","example":"その糸を切ってしまったのでしょう","meaning":"～てしまう + ～でしょう (てしまう + でしょう): To do something completely (often with regret) + probably/must be."}]],"original":[[{"jlpt":"N5","example":"小さな蜘蛛が一匹、路ばたを這って行くのが見えました。","tip":"このテキストのような古い文学では、現代の「いる」というひらがなではなく、「居る」と漢字で書かれることがよくあります。","pattern":"～ている (～て居る)","meaning":"動詞の「〜ている」形は、ある行動が現在進行中であること、または継続的な状態を表します。"},{"meaning":"何かをしようとすること、またはまさに何かをしようとしていることを示します。","jlpt":"N4","pattern":"～（よ）うとする","tip":"動詞の意向形に「とする」を付けて使用します。多くの場合、完全に実現しなかった試みを意味します。","example":"踏み殺そうと致しましたが..."},{"jlpt":"N3","pattern":"～に違いない","tip":"名詞や動詞に直接続きます。何らかの証拠に基づいて話者の確信を表します。","example":"命のあるものに違いない。","meaning":"強い確信を表すために使用されます。「〜に違いない」は「must be」または「without a doubt」の意味です。"},{"jlpt":"N4","tip":"この表現は、目上の人や対等な人に対して使うと、ぞんざいな印象や見下したような印象を与えることがあるので注意が必要です。丁寧な会話では「〜てあげる」を使用してください。","pattern":"～てやる","example":"助けてやったからでございます。","meaning":"目下の者（または動物や植物）のために何かをすることを意味します。"},{"meaning":"主語の行動に対して深い敬意を示すために使用される尊敬語の構造です。","jlpt":"N3","example":"御歩きになっていらっしゃいました。","tip":"これは、通常の動詞を尊敬語にする標準的な方法です。このテキストでは、著者は「お」を「御」と表記しています。","pattern":"お＋Stem＋になる"},{"meaning":"誰かが考えていることや、しようとしていることを示します。","jlpt":"N3","example":"この男を地獄から救い出してやろうと御考えになりました。","tip":"動詞の意向形に「と」が続くことで、思考や決定の内容を示します。","pattern":"～（よ）うと思う / 考える"},{"meaning":"もし可能であれば；もしそれができるなら、という条件を示します。","jlpt":"N3","tip":"「名詞／動詞＋なら」は、提案をしたり、以前に述べられた条件について話したりするのに使われます。","pattern":"Ｖ（辞書形）＋なら","example":"できるなら、この男を地獄から救い出してやろう..."}],[{"meaning":"交互に起こる actions や、多くの中の代表的な actions を列挙します。","jlpt":"N5","tip":"最後の「する」動詞が、文全体の時制を決定します。","example":"浮いたり沈んだりしていた","pattern":"～たり ～たりする"},{"tip":"しばしば、「〜ばかりすること」のように、やや否定的または批判的なニュアンスを伴います。","example":"もがいてばかり居りました","pattern":"～てばかりいる","meaning":"Xばかりする；行動が継続的または反復的であることを示します。","jlpt":"N4"},{"jlpt":"N2","meaning":"〜に相違ない／〜に相違ございませんは、「〜に違いない」の丁寧な表現です。疑いなく；確かに。","tip":"文学作品や公式な報告書で、強い確信を表明するためによく用いられます。","pattern":"～に相違ない / ～に相違ございません","example":"地獄からぬけ出せるのに相違ございません"},{"tip":"しばしば「いくら」（どんなに〜ても）と一緒に使われ、無駄な努力を強調します。","example":"いくら焦って見た所で","pattern":"～たところで","meaning":"たとえ〜ても；どんなに〜しようとも、望ましい結果にはつながらないことを意味します。","jlpt":"N2"},{"jlpt":"N2","meaning":"努力が報われたことを示し、努力する価値があったことを表します。","pattern":"～た甲斐がある / ～た甲斐があって","example":"一生懸命にのぼった甲斐があって","tip":"大変な努力が報われる結果につながったときに、これを使用します。"},{"meaning":"この上なく；言葉では言い表せないほど...（しばしば感情を強調する）。","jlpt":"N2","tip":"この構造は、品質や感情が極限レベルにあることを表現するために使用されます。","example":"その心細さと云ったらございません","pattern":"～といったら（あ）ない / ～といったらございません"},{"jlpt":"N3","meaning":"〜さえ／〜さえ〜ないは、「〜までも」といった驚くべき極端さを強調します。","pattern":"～さえ / ～さえ～ない","example":"泣声を出す力さえなくなっている","tip":"否定文では、最も基本的なことさえ不可能であることを強調します。"}],[{"jlpt":"N4","example":"落ちてしまいました","pattern":"～てしまう","tip":"口語では、「〜ちゃう」や「〜じゃう」に短縮されることがあります。ここでは、地獄に落ちるという行為の決定的な結末を強調しています。","meaning":"何かを完全にやり終えること（しばしば後悔や不本意な気持ちを伴う）"},{"jlpt":"N4","example":"細く光りながら","tip":"The focus is usually on the second action; the thread is hanging while it is glowing.","pattern":"～ながら","meaning":"～ながら (while doing) (simultaneous actions)"},{"example":"莫迦のように大きな口を開いたまま","tip":"Used when a state that should normally change persists. He kept his mouth open in shock.","pattern":"～たまま","jlpt":"N3","meaning":"～たまま (leaving something in a certain state; unchanged state)"},{"example":"落ちてしまうのに違いありません","pattern":"～に違いありません","tip":"A formal version of ～に違いない, expressing strong certainty based on logic.","jlpt":"N3","meaning":"～に違いありません (there is no doubt that...; must be...)"},{"pattern":"～さえ","tip":"It highlights that even the minimum possible requirement (just one person) is enough to break the thread.","example":"自分一人でさえ断れそうな","jlpt":"N3","meaning":"～さえ (even; a particle emphasizing an extreme case)"},{"meaning":"～なければならない / なれば (if one does not do...) (negative conditional)","example":"今の中にどうかしなければ","pattern":"～なければならない / なれば","tip":"Usually part of 'must', but ～なければ on its own implies 'if I don't [do something, something bad will happen].'","jlpt":"N3"},{"tip":"The humble form (～致しましたら) of ～としたら. It sets up a hypothetical scenario.","pattern":"～と致しましたら (～としたら)","example":"断れたと致しましたら","jlpt":"N2","meaning":"～と致しましたら (～としたら) (assuming that...; even if we suppose...)"},{"example":"堪える事が出来ましょう","tip":"In literary styles, ～ましょう can express a rhetorical 'How could it be possible?' (～でしょう か).","pattern":"～ましょう (Rhetorical)","jlpt":"N2","meaning":"～ましょう (rhetorical) (volitional form of ～でしょう used as a rhetorical wonder/probability)"}],[{"meaning":"～ていらっしゃる (honorific form of ～ている) (to be doing)","tip":"This is used to describe the continuous action of a respected person, like Buddha in this text.","example":"見ていらっしゃいましたが","pattern":"～ていらっしゃる","jlpt":"N4"},{"meaning":"～てしまう (expresses completion of an action or a regrettable result.)","example":"沈んでしまいますと","pattern":"～てしまう","jlpt":"N4","tip":"In this context, it emphasizes the finality and misfortune of Kandata sinking back into Hell."},{"pattern":"V-stem + 始める","example":"御歩きになり始めました","jlpt":"N4","tip":"Attach this to the stem of a verb to indicate the start of an action or habit.","meaning":"V-stem + 始める (to begin or start doing something.)"},{"meaning":"V-stem + ながら (while doing; two actions occurring simultaneously by the same person.)","jlpt":"N4","example":"悲しそうな御顔をなさりながら","pattern":"V-stem + ながら","tip":"The action after ながら is usually the main focus of the sentence."},{"pattern":"Volitional Form + とし（てい）る","example":"地獄からぬけ出そうとする","jlpt":"N3","tip":"It often indicates an attempt to do something or a state where something is just about to happen.","meaning":"Volitional Form + とし（てい）る (to try to, or be about to do something.)"},{"tip":"～ございましょう is the very formal version of ～でしょう, used in storytelling or polite speech.","jlpt":"N3","example":"落ちてしまったのが･･･浅間しく思召されたのでございましょう。","pattern":"～ので（ござい）ましょう","meaning":"～ので（ござい）ましょう (explaining a reason, or guessing based on evidence) (formal)."},{"tip":"This is a standard way to show respect to the subject (the one performing the action).","jlpt":"N3","example":"御歩きになり始めました","pattern":"お / 御 + V-stem + になる","meaning":"お / 御 + V-stem + になる (very polite/honorific expression of an action.)"}]]},"rashomon":{"simplified":[[{"pattern":"～ていました","jlpt":"N5","tip":"Think of this as the past version of ～ている. It describes what was happening at a specific point in time.","example":"雨がやむのを待っていました。","meaning":"Indicates an ongoing action in the past (past continuous)."},{"tip":"Use this when you need to follow a verb with a particle like を or は. It acts like 'the act of' or 'the fact that'.","jlpt":"N4","pattern":"～の（を・は・が）","meaning":"Changes a verb or phrase into a Noun so it can be used as an object.","example":"雨がやむのを待っていました。"},{"tip":"Unlike と which lists everything, や implies there are other things in the list that aren't mentioned.","pattern":"～や～など","jlpt":"N4","meaning":"Used to give examples among many possibilities, meaning 'such as' or 'and etc.'","example":"地震や火事などの災害"},{"meaning":"Indicates a change in state or becoming a certain way.","example":"貧しくなっていました。","tip":"For い-adjectives, change the final い to く before adding なる. For nouns and な-adjectives, use に.","jlpt":"N4","pattern":"（い形容詞）～くなる / （な形容詞）～になる"},{"example":"住むようになりました。","meaning":"Indicates a change in a situation or habit over time (to reach the point where...).","pattern":"～ようになる","jlpt":"N4","tip":"This often describes a gradual change from one state (not doing) to another (doing)."},{"tip":"Use this pattern when 'B' always or naturally follows 'A', like 'if you press this button, the light turns on'.","jlpt":"N4","pattern":"～と","example":"夕方になると","meaning":"Indicates a natural consequence or a repeatable cause-and-effect relationship (if/when)."},{"example":"みんな怖がって","meaning":"Used to describe someone else's outward signs of emotion or feeling.","tip":"In Japanese, you usually only use feeling words like 怖い (scary) for yourself. Use ～がる to describe how others are acting/feeling.","jlpt":"N3","pattern":"～がる"}],[{"meaning":"Don't have to; no need to do (something)","example":"「もう来なくていい」","tip":"This is the negative form of ～てもいい. It is used to give permission or express that an action is unnecessary.","jlpt":"N4","pattern":"～なくていい"},{"example":"死んでしまう","meaning":"To do something completely or an accidental, regrettable action","jlpt":"N4","pattern":"～てしまう","tip":"In casual speech, this often contracts to ～ちゃう, but in written text, it highlights the finality or unwanted nature of the situation."},{"jlpt":"N4","pattern":"～ばいい","tip":"When combined with a question word like どうやって, it expresses the speaker's uncertainty about the best course of action.","example":"生きていけばいいか","meaning":"If... then it's good (Used for seeking advice or wondering what to do)"},{"meaning":"While doing; performing two actions simultaneously","example":"考えながら","tip":"The action after ながら is the main focus. Attach it to the stem (ます-form) of the verb.","pattern":"～ながら","jlpt":"N4"},{"tip":"Use this when a physical or environmental change (like weather or feelings) starts to happen or move toward you.","jlpt":"N4","pattern":"～てくる","meaning":"To indicate a change that has begun and is continuing toward the present","example":"寒くなってきたので"},{"pattern":"～（意向形）と思う","jlpt":"N4","tip":"The volitional form (意向形) followed by と思う expresses a internal decision or plan that the speaker has made.","meaning":"To think of doing; to intend to do (something)","example":"寝ようと思いました"},{"tip":"Use this when you have a logical reason to believe something is true. Here, the man expects only the dead to be there because of the location.","pattern":"～はずです","jlpt":"N4","example":"死んだ人しかいないはずです","meaning":"Expectation; it should be; it is supposed to be"}],[{"jlpt":"N5","tip":"Used when something is physically inside a space or object. Always follows a Noun + の.","meaning":"Indicates location or existence (in, inside)","example":"部屋の中に火の光が見えました。","pattern":"～の中に"},{"meaning":"Present continuous form (is doing) or resultative state (is done)","tip":"While often translated as '-ing', it can also describe a state that began in the past and continues to the present.","jlpt":"N4","pattern":"～ている","example":"こんな夜に火を使っているのは不思議です。"},{"jlpt":"N4","meaning":"Nominalizer (turns a verb into a Noun)","tip":"Use this to make a whole sentence or verb phrase the subject of the sentence, often followed by an adjective.","example":"火を使っているのは不思議です。","pattern":"～のは"},{"example":"一番上まで登ると、部屋の中に火の光が見えました。","pattern":"～と、～","jlpt":"N4","tip":"When used with a past tense verb in the second Clause, it usually describes something the speaker discovered after doing an action.","meaning":"Natural consequence or unexpected discovery (when / if)"},{"jlpt":"N3","meaning":"Each / at a time (indicates a steady distribution)","tip":"Attach this to numbers or counters to show that an action is performed in specific increments.","example":"髪の毛を一本ずつ抜いていました。","pattern":"～ずつ"}],[{"pattern":"～て (接続)","jlpt":"N5","meaning":"The 'Te-form' used to connect two or more actions in chronological order.","example":"男はそれを見て、とても怒りました。","tip":"Think of this as saying 'and' between verbs. The tense of the entire sentence is determined by the final verb."},{"pattern":"動詞た形 + 名詞","jlpt":"N5","example":"死んだ人","tip":"In Japanese, you can put a verb directly before a Noun to describe it, like 'the person who died'.","meaning":"Using the past tense (Plain past) of a verb to modify a Noun, creating a relative Clause."},{"jlpt":"N5","pattern":"～ている","meaning":"Expresses an action currently in progress.","example":"何をしている！","tip":"This is the equivalent of '-ing' in English. In casual speech, the 'i' is often dropped."},{"jlpt":"N4","pattern":"～なさい","example":"言いなさい！","tip":"Attach this to the Stem (masu-form minus 'masu'). It is more authoritative than 'te-kudasai' but softer than the bare imperative.","meaning":"A polite but firm command usually used by superiors or parents."},{"meaning":"An expression of surprise, disbelief, or disdain towards an action or state.","tip":"This particle highlights something the speaker finds shocking or unexpected. It often implies a negative feeling like 'to think that...' or 'things like...'.","example":"髪を抜くなんて","pattern":"～なんて","jlpt":"N3"},{"pattern":"なんて～（だ）","jlpt":"N3","meaning":"An exclamation used to emphasize the degree of an adjective, often translated as 'What a...' or 'How...!'","tip":"This is often paired with 'da' or 'darou' at the end of the sentence to show the speaker's strong emotion.","example":"なんて悪い人だ！"}],[{"meaning":"Used to indicate the content of a thought, statement, or action (quotation).","example":"蛇の肉を魚の肉だとうそをついて売っていました。","pattern":"～と","jlpt":"N5","tip":"Think of this as quotation marks. It is used here to show what the lie actually was."},{"tip":"Use the Dictionary form of a verb before this. It indicates a strong intention that you have already decided on.","pattern":"～つもりだ","jlpt":"N4","example":"この髪を抜いて、かつらを作るつもりでした。","meaning":"Expresses intent, plan, or purpose."},{"tip":"Attach this to the stem of a verb. The main focus is always on the second action.","pattern":"～ながら","jlpt":"N4","example":"おばあさんは震えながら言いました。","meaning":"Indicates two actions happening simultaneously by the same person."},{"meaning":"Expresses a possibility or a softened opinion (maybe/it might be).","example":"悪いことかもしれませんが、……","jlpt":"N4","pattern":"～かもしれない","tip":"In polite speech, use the form ending in ＋ません. It expresses uncertainty."},{"jlpt":"N4","pattern":"～てもいい","tip":"This follows the て-form of a verb. In this text, the speaker is using it to justify a moral choice to himself.","meaning":"Asks for or gives permission to do an action.","example":"悪いことをしてもいいのだな。"},{"tip":"Here, it emphasizes the finality and negative outcome of death if the character does not act.","jlpt":"N4","pattern":"～てしまう","example":"そうしないと死んでしまうからです。","meaning":"Indicates that an action will be completed, or expresses regret/unintentionality."},{"tip":"When following a verb, use the Dictionary form. It shows a clear objective or reason for an action.","pattern":"～ために","jlpt":"N3","example":"生きるために、蛇の肉を……","meaning":"Indicates a purpose, goal, or for the sake of something/someone."}],[{"jlpt":"N5","tip":"In this context (門の下を), it describes moving through or looking across an area.","meaning":"Indicates the object of an action or a path through/along a space.","example":"門の下を","pattern":"～を"},{"example":"死んでしまう","pattern":"～てしまう","jlpt":"N4","tip":"Use this when something happens that you didn't want to happen, or to emphasize it is finished.","meaning":"Expresses completion of an action, often with a sense of regret, accident, or finality."},{"pattern":"～な（禁止）","example":"怒るなよ","meaning":"A strong negative imperative used to forbid someone from doing something.","tip":"The particle な added directly to the Dictionary form makes a command 'Don't do it!'. Adding よ softens the tone slightly.","jlpt":"N4"},{"pattern":"～ないと","example":"そうしないと","tip":"Often translated as 'if I don't...' or 'unless...'. It marks an inevitable consequence.","meaning":"Indicates that if a certain condition is not met, a negative result will follow.","jlpt":"N4"},{"jlpt":"N4","tip":"For 五段 verbs like 脱ぐ, change the final vowel to the 'a' sound and add せる. In this story, it implies a forced action.","meaning":"The causative form, used to indicate making or letting someone do an action.","example":"服を脱がせて","pattern":"～せる / ～させる"},{"example":"急いで降りていきました","pattern":"～ていく","jlpt":"N4","meaning":"Indicates an action that moves away from the speaker's current location or perspective.","tip":"Use this when an action involves moving 'away' or continuing into the future."},{"tip":"This structure turns the entire preceding Clause into the 'reason' for the previous statement.","meaning":"Added at the end of a sentence to provide an explanation or reason for something.","jlpt":"N4","pattern":"～からだ / ～からです","example":"死んでしまうからだ"},{"meaning":"Used to embed a question (who, what, where, etc.) within a sentence.","tip":"The particle か marks the end of the embedded question. It is often followed by verbs like 知る (to know) or 分かる (to understand).","jlpt":"N3","pattern":"（疑問詞）～か","example":"どこへ行ったのか"}]],"intermediate":[[{"jlpt":"N4","tip":"Use this pattern instead of こと when describing immediate sensory perceptions like seeing, hearing, or waiting for an action to occur.","example":"雨がやむのを待っていた。","pattern":"動詞の辞書形 ＋ の","meaning":"The nominalizing particle used to turn a verb into a Noun, often representing an action or event happening before your eyes."},{"tip":"For the verb いる (to exist), the stem is just い. This expresses that the person hasn't seen anyone yet but judged from the situation that they \"look like\" they would be there.","jlpt":"N4","example":"雨宿りをする人がいそうだが、誰もいない。","meaning":"Indicates that something looks like or appears to be a certain way based on visual evidence.","pattern":"動詞の連用形 ＋ そうだ ＞ いそうだ"},{"meaning":"Used to indicate the extent or degree of a situation, often translated as 'to the extent that'.","pattern":"名詞・動詞 ＋ ほど","example":"薪として売っていたほどだという。","tip":"Think of this as 'so much so that...'. In this text, it emphasizes how desperate the situation was by showing just how far people went (breaking statues).","jlpt":"N3"},{"example":"なぜかというと、この数年...からだ。","meaning":"A structure used to introduce a reason. 'The reason why is because...'","pattern":"なぜかというと ～ からだ","tip":"This is a formal and clear way to explain cause and effect. Always look for the からだ at the end of the sentence to complete the logic.","jlpt":"N3"},{"tip":"While this often means 'is doing' (progressive), for change-of-state verbs like つく (to attach), it describes the current state (it is currently attached).","jlpt":"N4","meaning":"Describes a continuing state that resulted from a past action.","pattern":"動詞のて形 ＋ いる","example":"カラスのフンが白くついているのが見える。"},{"tip":"Since you cannot truly know another person's internal feelings, you use 'garu' to describe the 'appearing state' of their emotions.","jlpt":"N3","meaning":"Suffix added to an adjective to indicate that someone else is showing outward signs of feeling that emotion.","pattern":"い形容詞（いを除く） ＋ がる","example":"夕方になると気味悪がって誰も近づかなくなった。"},{"jlpt":"N3","tip":"When you add か to the end of せい, it implies that you are not 100% sure if that is the reason, but you suspect it is.","pattern":"名詞・動詞・形容詞 ＋ せいか","meaning":"Used to indicate a cause that leads to a negative or undesirable result. 'Perhaps because of...'","example":"しかし今日は時間が遅いせいか、一羽も見えない。"}],[{"jlpt":"N4","tip":"Use this when you have a logical reason for your conclusion. It implies \"it ought to be.\"","example":"死体しかないはずだ。","pattern":"～はずだ","meaning":"An expectation or strong belief that something should be the case."},{"tip":"It emphasizes that whatever follows is the absolute only thing. Remember to always pair it with a negative verb form.","jlpt":"N5","meaning":"Nothing but; only (used with a negative verb).","example":"死体しかないはずだ。","pattern":"～しか～ない"},{"pattern":"～ことにする","example":"はしごを登ることにした。","meaning":"To decide on something; to make a choice.","tip":"Use this version when the decision is made by the person themselves, rather than an outside force.","jlpt":"N4"},{"pattern":"（意向形）＋と思う","example":"夜を明かそうと思った。","meaning":"Thinking of doing or intending to do an action.","tip":"This uses the volitional form (e.g. 食べよう, 行こう) to express an internal plan or intention.","jlpt":"N4"},{"tip":"Pair this with \"how,\" \"what,\" or \"where\" to ask for instructions or a path forward.","jlpt":"N4","example":"どうやって生きていけばいいのか分からず","pattern":"～ばいい","meaning":"Should; it would be good if... (standard way to ask for advice)."},{"example":"クビにされた。","pattern":"～れる / ～られる","meaning":"Passive voice; indicates an action done to the subject.","jlpt":"N4","tip":"In this text, it shows the man was the victim of being fired (クビ) by his master."},{"example":"分からず、途方に暮れていた。","pattern":"～ず（に）","meaning":"Without doing; the literary equivalent of 「～ないで」.","tip":"This is common in written stories. Simply replace the 「ない」 of a negative verb with 「ず」. For 「する」, it becomes 「せず」.","jlpt":"N3"}],[{"tip":"Use these for things you can see/hear without trying, unlike 見る or 聞く which imply intention.","jlpt":"N4","example":"誰かが火をともしているのが見えた。","meaning":"Indicates that a sensory perception (seeing/hearing) is happening spontaneously or naturally.","pattern":"～が見える / ～が聞こえる"},{"meaning":"Doing an action without doing something else (similar to ～ないで).","example":"足音を立てずに一番上まで登り...","pattern":"～ずに","jlpt":"N3","tip":"This is a formal way to say 'without doing'. Remember that する becomes せずに."},{"jlpt":"N4","tip":"Use の instead of こと when the main verb involves direct perception like 'see', 'hear', or 'wait'.","pattern":"動詞（辞書形）＋の","example":"死体の中に、一人の人間がうずくまっているのを見たからだ。","meaning":"Turns a verb phrase into a Noun so it can be the object of a sentence."},{"pattern":"～からだ","example":"一人の人間がうずくまっているのを見たからだ。","meaning":"Used at the end of a sentence to state a reason or explanation.","jlpt":"N4","tip":"This is a direct way to provide a reason for a previously mentioned situation. In casual speech, it often becomes ～から。"},{"tip":"Attach this to the ます-stem of a verb. It focuses on the start of a continuous process.","jlpt":"N4","meaning":"Indicates the beginning of an action.","example":"髪の毛を一本ずつ抜き始めたのだ。","pattern":"～始める"},{"tip":"This gives the sentence an explanatory tone, often used when revealing the background or reason for something.","jlpt":"N3","meaning":"Used for emphasis or to provide an explanation/clarification of a situation.","example":"髪の毛を一本ずつ抜き始めたのだ。","pattern":"～のだ / ～んだ"},{"meaning":"Indicates performing an action deeply, thoroughly, or into something.","example":"若い女の死体の顔をのぞき込んでいた。","pattern":"～込む","jlpt":"N3","tip":"Common with verbs of movement (like 飛び込む) or observation (like のぞき込む) to show depth or intensity."}],[{"example":"刀を突きつけた。","meaning":"Object marker particle indicating the target of a verb's action.","jlpt":"N5","pattern":"～を","tip":"Always follows the Noun that is being acted upon. In this text, it connects the sword (刀) to the action of thrusting (突きつけた)."},{"meaning":"To attempt to do something or be about to do something.","example":"逃げようとしたが","pattern":"～ようとする","jlpt":"N4","tip":"Uses the volitional form of the verb. It implies an attempt that might be interrupted or may not succeed."},{"example":"震えながら","meaning":"While doing something; indicates two actions happening simultaneously by the same person.","tip":"Attach this to the stem of the verb (the part before ます). The main action comes after the ながら Clause.","pattern":"～ながら","jlpt":"N4"},{"tip":"When modifying a Noun (like 憎しみ), use に対する. When modifying a verb, use に対し or に対して.","jlpt":"N3","pattern":"～に対する","meaning":"Towards; regarding; in contrast to. Expresses an attitude or action directed at someone or something.","example":"老婆に対する激しい憎しみ"},{"example":"怒りだと言ってもいい。","meaning":"It is okay to say...; one might even say...","pattern":"～と言ってもいい","jlpt":"N3","tip":"Used to provide a strong classification or to suggest that a certain description is acceptable or accurate."},{"tip":"もし reinforces the \"if\" condition, while だろう at the end shows that the result is an assumption or prediction.","jlpt":"N3","pattern":"もし～たら、～だろう","meaning":"If (conditional) ... then probably (conjecture). Usually used for hypothetical or uncertain situations.","example":"もしこの時、誰かが「飢え死にするか、泥棒になるか」と聞いたら、男は迷わず飢え死にを選んだだろう。"},{"pattern":"～ず（に）","jlpt":"N3","tip":"This is a formal/literary version of ～ないで. To form it, change the ～ない ending to ～ず. For する, use せず.","example":"迷わず飢え死にを選んだ","meaning":"Without doing; used to describe an action performed without a specific preceding action."}],[{"pattern":"～かもしれない","tip":"It is used for subjective guesses. In casual speech, the final だ or です is omitted, leaving just しれない.","jlpt":"N4","meaning":"Maybe; might; perhaps (expresses a possibility)","example":"悪いことかもしれない"},{"meaning":"Nothing but; only; just (indicates a large amount or frequency of something)","example":"悪いことをしてきた人間ばかりだ","tip":"When used after the て-form of a verb, it means someone is 'doing nothing but' that specific action.","pattern":"～ばかり","jlpt":"N3"},{"tip":"When the verb before it is in the Dictionary form, it indicates a conscious purpose or goal.","pattern":"～ために","jlpt":"N4","meaning":"For the purpose of; in order to","example":"生きるために"},{"pattern":"～なければ","tip":"This is the 'if' condition for negative verbs. Replace the い in ない with ければ.","jlpt":"N4","meaning":"If not; unless (negative conditional)","example":"そうしなければ飢え死にしていたからだ"},{"example":"大目に見てくれるだろう","meaning":"Probably; I think (expresses a conjecture or polite push for agreement)","jlpt":"N4","tip":"This is the Dictionary form of でしょう. Use it when you are fairly sure about something but not 100% certain.","pattern":"～だろう"},{"meaning":"To do something completely away / finish doing (verb suffix)","example":"完全に消え去っていた","tip":"When 去る is attached to the stem of a verb, it emphasizes the action of moving away or something disappearing completely.","pattern":"～去る（～さる）","jlpt":"N3"}],[{"pattern":"～な / ～だな","meaning":"Confirmation or agreement particle used at the end of a sentence.","example":"本当にそうだな。","jlpt":"N5","tip":"It functions similarly to ね but is more casual and often sounds more masculine or assertive."},{"example":"恨むなよ。","pattern":"動詞辞書形 ＋ な","meaning":"Negative imperative (prohibition) meaning \"don't do...\".","jlpt":"N4","tip":"Adding よ after な softens the command slightly, but it still sounds very strong and blunt."},{"meaning":"Expresses a conditional \"if... not\", used to show a necessary consequence.","pattern":"～なければ","example":"そうしなければ飢え死にする体なのだ。","tip":"This is the conditional form of the negative ない. In speech, this is often shortened to なきゃ.","jlpt":"N4"},{"tip":"When following a Noun or Na-adjective, you must add な before のだ. It adds a tone of conviction or explanation.","jlpt":"N4","meaning":"The explanatory particle used to provide a reason, explanation, or emphasize a fact.","pattern":"～のだ / ～んだ","example":"飢え死にする体なのだ。"},{"tip":"This often describes a scene where someone is just starting an action or a physical effort that might not succeed.","jlpt":"N3","example":"すがりつこうとする老婆","meaning":"Indicates an attempt or intention to perform an action. Expresses \"trying to...\" or \"about to...\".","pattern":"動詞意向形 ＋ とする"},{"tip":"When a question word like どこ (where) or 何 (what) is used, the sentence ends in か even if it is in the middle of a larger sentence.","jlpt":"N4","meaning":"Turns a question into a Noun Clause so it can function as the subject or object of a sentence.","pattern":"疑問詞 ＋ ～か","example":"男がどこへ行ったのかは、誰も知らない。"}]],"original":[[{"tip":"Use this whenever you want to say things like 'I like doing X' or 'I saw X happening'.","pattern":"～の（名詞化）","jlpt":"N5","meaning":"The 'no' particle turns a verb/Clause into a Noun (nominalization) so it can be used with particles like 'wo'.","example":"雨のふるのを眺めていた。"},{"example":"地震とか辻風とか火事とか・・・","meaning":"Used to list multiple examples non-exhaustively (like 'A, B, and so on').","jlpt":"N4","pattern":"～とか～とか","tip":"Unlike 'to' which is an exhaustive list, 'toka' implies there are other things not mentioned."},{"meaning":"Expresses what should be natural, expected, or typical in a given situation.","example":"二三人はありそうなものである。","tip":"This adds a nuance of 'it is only natural that' or 'one would expect that' based on social norms or logic.","jlpt":"N3","pattern":"～そうなものだ"},{"example":"朱雀大路にある以上は","meaning":"Now that/Since; expresses a strong cause or condition where a certain result is natural or required.","jlpt":"N2","pattern":"～以上（は）","tip":"This pattern is often used when a decision has been made or a fact is established, leading to a natural consequence."},{"meaning":"Indicates that an action or state has started but is not yet finished (half-way through).","example":"崩れかかった、そうしてその崩れ目に・・・","jlpt":"N2","pattern":"～かかかる / ～かかった","tip":"Use this for processes that take time to complete, like a building falling apart or a person starting to say something."},{"example":"誰でも気味を悪るがって","meaning":"Appearing to feel a certain emotion or sensation (used for third-person subjects).","pattern":"～がる / ～がって","jlpt":"N3","tip":"Japanese speakers rarely use direct feeling words (like 'scared' or 'cold') for others; they use 'garu' to describe the outward appearance of that feeling."},{"example":"死人の肉を、啄みに来るのである。","meaning":"Indicates the purpose of going or coming to a place.","jlpt":"N5","pattern":"（動詞ます形）＋に（行く・来る）","tip":"Drop the 'masu' from a verb and add 'ni' plus a movement verb to express 'going to do' something."}],[{"pattern":"～ても / ～でも","jlpt":"N4","meaning":"Even if; even though (indicates a hypothetical or factual concession)","tip":"Observe how it attaches to the て-form of verbs or adjectives to show that the result is unaffected by the condition.","example":"雨がやんでも"},{"pattern":"～はずだ / ～はずである","example":"帰る可き筈である","jlpt":"N4","meaning":"Expected to; supposed to (expresses a strong expectation based on logic or common sense)","tip":"Use this when you have a logical reason to believe something is true. Note that the text uses the old-style べき (represented as 可き)."},{"pattern":"次第に","jlpt":"N4","tip":"This is a more formal version of だんだん and is common in literature and news.","meaning":"Gradually; little by little (indicates a progressive change)","example":"夕闇は次第に空を低くして"},{"example":"余波にほかならない","meaning":"Nothing but; none other than (used to identify something strongly)","tip":"This adds a strong emphatic tone to a statement, often used in written conclusions.","jlpt":"N2","pattern":"～にほかならない"},{"pattern":"～あげくに / ～あげくの","example":"同じ道を低徊した揚句に","jlpt":"N2","tip":"Think of this as 'after all that trouble, the result was...' – it often emphasizes the mental or physical struggle preceding the outcome.","meaning":"After; in the end (usually implies a long process with a negative or exhaustive result)"},{"pattern":"～よりほかに（仕方がない）","jlpt":"N3","meaning":"Have no choice but to; no other way except for...","tip":"This expresses a situation where options have run out. Only the action before より remains possible.","example":"盗人になるよりほかに仕方がない"}],[{"pattern":"～てしまう / ～てしまった","jlpt":"N4","meaning":"Expresses completion of an action or a sense of regret/finality.","tip":"In this context, it emphasizes that the crickets are completely gone, leaving the scene lonely.","example":"どこかへ行ってしまった。"},{"pattern":"～ながら","example":"頸をちぢめながら","jlpt":"N4","meaning":"Indicates two actions happening simultaneously by the same person.","tip":"The Stem always precedes this. It focuses on the second action as the main one."},{"pattern":"～ほど / ～ほどの","example":"火桶が欲しいほどの寒さである。","jlpt":"N3","tip":"Use this when you want to say something is 'to the extent that...' or 'so much so that...'.","meaning":"Indicates the degree or extent of something by providing an example."},{"pattern":"～られそう / ～れそう","jlpt":"N4","meaning":"Potential form (can sleep) combined with the appearance of possibility (seems like).","tip":"It combines the potential form potential form (られる) with the 'looks like' guess (そう).","example":"一晩楽にねられそうな所"},{"example":"鞘走らないように気をつけながら","tip":"This is used when setting a goal for an action or maintaining a specific habit/caution.","meaning":"To take care to do (or not do) something, or to ensure a certain state.","jlpt":"N3","pattern":"～ように（気をつける）"},{"pattern":"～ばかり","meaning":"Indicates that there is nothing but a certain thing, or that something happens exclusively.","tip":"Here it shows the protagonist's assumption that the tower contained 'only' or 'nothing but' corpses.","jlpt":"N4","example":"死人ばかりだと高を括っていた。"},{"example":"火をそこここと動かしているらしい。","jlpt":"N4","tip":"It is often used when you see or hear something that leads you to a logical conclusion.","meaning":"Expresses a conjecture based on objective evidence or information gathered.","pattern":"～らしい"},{"pattern":"～つめる（上りつめる）","example":"一番上の段まで這うようにして上りつめた。","jlpt":"N2","tip":"When attached to movement verbs, it implies a difficult or exhaustive effort to reach the final point.","meaning":"Indicates doing something to the very end or reaching a limit."}],[{"example":"死骸の中に蹲っている人間を見た。","tip":"When used with action verbs, it shows 'is doing'. With change-of-state verbs like 蹲る, it shows a completed action whose result remains.","meaning":"Expresses an ongoing action or a current state.","jlpt":"N5","pattern":"～ている"},{"jlpt":"N4","pattern":"～はじめる","meaning":"Added to the stem of a verb to indicate the start of an action.","example":"その長い髪の毛を一本ずつ抜きはじめた。","tip":"Attach this to the ます-stem of any verb to say you 'started' doing that action."},{"meaning":"Used to describe something by comparing it to something else (metaphor or likeness).","tip":"Think of this as 'like' or 'as if'. It usually follows a Dictionary form verb or a Noun plus の.","example":"猿の子の虱をとるように","pattern":"～ように","jlpt":"N4"},{"pattern":"～に従って","jlpt":"N2","example":"髪の毛が、一本ずつ抜けるのに従って","tip":"This indicates a simultaneous change. As one thing progresses, another thing changes along with it.","meaning":"As X happens, Y happens in accordance or proportion to it."},{"jlpt":"N2","pattern":"～は云うまでもない","tip":"This is a formal way to state that something is so self-evident or certain that it doesn't need to be mentioned.","example":"老婆が驚いたのは云うまでもない。","meaning":"It goes without saying that... / It is obvious that..."},{"meaning":"Expression meaning 'must not' or 'should not'. A stiff, literary prohibition.","example":"それだけで既に許すべからざる悪であった。","tip":"This is the attributive form of ～べからず. It is very formal and usually found in literature or old legal texts to describe things that are 'unforgivable' or 'forbidden'.","jlpt":"N1","pattern":"～べからざる"},{"jlpt":"N1","pattern":"～ぬ","example":"云わぬと、これだぞよ。","tip":"While common in certain dialects/proverbs, in literature it provides a classical or archaic tone. In this text, 云わぬ means 云わない.","meaning":"The classical negative form equivalent to ～ない."}],[{"jlpt":"N4","example":"死人の髪の毛を抜くと云う事は","tip":"Use this to turn a sentence or a verb phrase into a Noun Clause to discuss it as a topic.","meaning":"The thing called; the act of (used to define or emphasize a Noun or concept)","pattern":"～という事"},{"tip":"Attach さえ to the Noun or the stem of the verb, and put the following verb in its conditional (ば) form.","pattern":"～さえ～ばいい","meaning":"If only; as long as (indicates the minimum requirement for something to happen)","jlpt":"N3","example":"何をして居たのだか、それを己に話しさえすればいいのだ。"},{"meaning":"Like; similar to (describes something by comparing it to another Noun)","pattern":"～のような / ～のように","tip":"Use ような before nouns and ように before verbs or adjectives to create vivid metaphors.","example":"鴉の啼くような声","jlpt":"N3"},{"tip":"であろう is the formal, literary version of だろう, commonly seen in novels and historical texts.","meaning":"Probably; I wonder (expresses conjecture or a polite opinion)","pattern":"～であろう / ～だろう","jlpt":"N3","example":"その気色が、先方へも通じたのであろう。"},{"jlpt":"N2","example":"死骸の頭から奪った長い抜け毛を持ったなり","tip":"It indicates that a person does something and stays in that state, often implying unexpected continuity. It is similar to っぱなし but more formal.","pattern":"～なり / ～たなり","meaning":"Remaining in a certain state; just as it is (without changing)"},{"meaning":"If one does not; unless (classical/literary negative conditional)","pattern":"～ねば (ならぬ / ならぬ)","tip":"This is an old form of ～なければ. In modern Japanese, it survives mostly in the set phrase ～ねばならない (must).","example":"せねば、饑死をするのじゃて","jlpt":"N1"},{"meaning":"Would have been (counter-factual conditional or past conjecture)","pattern":"～たことであろう / ～たであろ","tip":"This sophisticated ending describes a situation that did not happen but could have, or makes a strong guess about the past.","example":"今でも売りに往んでいた事であろ。","jlpt":"N1"}],[{"jlpt":"N4","tip":"The main action comes after the ～ながら Clause. The verb before it must be in the stem form (ます-form minus ます).","meaning":"While doing; simultaneous actions","example":"太刀の柄を左の手でおさえながら","pattern":"～ながら"},{"pattern":"～ほど / ～ほど～ない","example":"考える事さえ出来ないほど","tip":"Used to describe the degree of a state by providing a dramatic example. When used with a verb, it is directly attached to the Dictionary form.","meaning":"To the extent that; so much so that","jlpt":"N3"},{"example":"迷わなかったばかりではない。","pattern":"～ばかりか / ～ばかりでなく","jlpt":"N3","meaning":"Not only... but also...","tip":"It emphasizes that something is not limited to one thing but extends to others. In the text, it is used with the negative form to show how decisive the character became."},{"example":"己が引剥をしようと恨むまいな。","pattern":"～まい / ～まいか","jlpt":"N2","meaning":"Will probably not; intend not to (Negative Volitional)","tip":"This is a literary or formal way to express a negative intention (I will not) or a negative guess (probably not). It is common in classic literature like this story."},{"meaning":"Only; nothing but; simply","tip":"When used at the end of a sentence after a Noun or verb, it emphasizes that a certain state is all that exists, often implying a sense of emptiness or limitation.","jlpt":"N2","pattern":"～ばかりである / ～のみである","example":"黒洞々たる夜があるばかりである。"},{"meaning":"To try to; to be about to do something","tip":"Uses the volitional form of the verb. It describes an attempt to do something or a state just before an action occurs.","jlpt":"N3","pattern":"～ようとする / ～おうとする","example":"反対な方向に動こうとする勇気である。"},{"jlpt":"N1","tip":"In this older literary context, 体 means \"appearance\" or \"situation.\" It functions like わけだ or のだ to explain a reason or state of being.","meaning":"The situation is...; the context is... (Noun usage)","example":"飢死をする体なのだ。","pattern":"～体 (てい) だ"}]]},"hashire-merosu":{"simplified":[[{"jlpt":"N5","tip":"くだけた会話では、「い」が省略されることがよくあります（例：「非んでる」ではなく「非んでる」）。","pattern":"～ている","meaning":"継続的な行動や現在の状態を示します。","example":"羊と遊んで生活しています。"},{"meaning":"～なければならない、～する必要がある。","example":"あの悪い王様を倒さなければならない","jlpt":"N4","pattern":"～なければならない","tip":"これは非常にフォーマルです。日常会話では、「なきゃ」や「なくちゃ」がよく使われます。"},{"tip":"最初の行動の後に2番目の行動がほとんど自動的に起こるときにこれを使います。","pattern":"～と (conditional)","jlpt":"N4","example":"町を歩いていると、メロスは「変だな」と思いました。","meaning":"～と (条件) (～すると、～すれば、～なると、必然的または自然な結果につながる)。"},{"meaning":"～ために (～のために、～の目的で)。","example":"食べ物を買うために、町に来たのです。","jlpt":"N4","tip":"動詞と一緒に使う場合、動詞は辞書形である必要があります。名詞には「名詞＋の」を使います。","pattern":"～ために"},{"pattern":"～つもりだ","tip":"これは、強い意図や、心の中で既に決定されている計画を表します。","jlpt":"N4","example":"メロスは彼に会いに行くつもりでした。","meaning":"～つもりだ (～するつもりだ、～する意図がある)。"},{"pattern":"～という","tip":"これは、自己紹介や、まだ誰も知らない場所を紹介するのに最適です。","jlpt":"N4","example":"セリヌンティウスという大切な友だち","meaning":"～という (～という、～と名付けられた) (名前や肩書きを紹介するのに使われます)。"},{"tip":"英語の「more」とは異なり、「もっと」は「～よりも」を必要とせず、程度が大きくなることを強調するだけです。","pattern":"もっと","jlpt":"N3","example":"前はもっとにぎやかでしたよ。","meaning":"もっと (比較してより多くの)。"}],[{"meaning":"何かをしたい (動詞の語幹 + たい)","example":"妹の結婚式をしたいのです。","pattern":"～たい","jlpt":"N5","tip":"話者自身の願望に使う。動詞の語幹に付けて使う。"},{"tip":"次の行動に関係なく、予期せず状態が続く場合によく使われる。","pattern":"～まま","jlpt":"N4","example":"怒ったまま王様のお城に入りました。","meaning":"何かをある状態のままにしておくこと。"},{"tip":"動詞と一緒に使う場合、動詞は辞書形 (基本形) でなければならない。","jlpt":"N4","pattern":"～ため（に）","example":"町を、あなたから助けるためだ","meaning":"目的のために"},{"tip":"肯定的な意図には辞書形を、否定的な意図には「ない」形を使う。","jlpt":"N4","pattern":"～つもり","example":"何をするつもりだったか？","meaning":"何かをするつもりであること、計画していること"},{"meaning":"受身形 (～される)","example":"すぐに兵士に捕まりました。","pattern":"～られる / ～れる","jlpt":"N4","tip":"この文では、「捕まる」と「連れて行かれる」は受身形である。"},{"example":"もし私が信じられないなら","meaning":"もし～なら (条件)","tip":"言及されたばかりの文脈や仮定の状況に基づいて、提案や反応を示すのに使われる。","jlpt":"N4","pattern":"～なら"},{"meaning":"意向形 (～しよう / ～するつもりだ) + 恩恵を与える (社会的地位の低い者や動物に)","example":"あの友だちを殺してやろう。","pattern":"～てやろう","jlpt":"N4","tip":"「やる」は「あげる」の謙譲語/ぞんざいな言い方である。ここでは王の残酷な意図を示している。"}],[{"example":"雨がたくさん降りましたが","jlpt":"N5","pattern":"～が","meaning":"しかし (二つの文をつなぐ)","tip":"肯定的な状況と否定的な状況をつなぐ、または単にコントラストを表現する。"},{"meaning":"～しよう (意向形)","pattern":"～（よ）う","tip":"誰かに行動を提案したり、自分の意図を表現したりするのに使う。","example":"結婚式をしよう","jlpt":"N4"},{"example":"お城に呼ばれました / 縄で縛られました","jlpt":"N4","pattern":"～られる / ～れる","meaning":"受身形 (～される)","tip":"主語が行動の受け手である場合に使用する。物語でよく使われる。"},{"jlpt":"N4","example":"ずっとここにいたい","tip":"動詞の「ます」を取って「たい」を付け加えることで願望を表現する。自分の願望にのみ使用する。","pattern":"V-stem + たい","meaning":"何かをしたい"},{"example":"顔を赤くしました","jlpt":"N4","meaning":"何かを（形容詞の）状態にする / 状態が変わる","pattern":"Adj + する / なる","tip":"い形容詞の場合は「い」を「く」に替える。な形容詞の場合は「に」を加える。「する」は意図的な行動を意味する。"},{"pattern":"～なければなりません","meaning":"～しなければならない","tip":"これは文字通り「しなかったら、だめだ」という意味である。義務を表現する丁寧な方法である。","example":"行かなければなりません","jlpt":"N4"}],[{"jlpt":"N4","example":"走り出しました","meaning":"突然行動を開始する","pattern":"～出す (V-stem + 出す)","tip":"雨が降り始める、誰かが突然笑い出すなど、突然または外向きに始まる行動に使う。"},{"example":"泣きながら神様にお願いしました","jlpt":"N4","pattern":"～ながら (V-stem + ながら)","meaning":"二つの行動を同時に行う","tip":"主要な行動は常に二番目に来る。この場合、「祈る」が泣きながら行う主要な行動である。"},{"jlpt":"N3","example":"雨のせいで川の水がいっぱいになっていました","meaning":"～のせいで (Noun + のせいで / Verb + せいで) because of; due to (usually for a negative result)","pattern":"～のせいで (Noun + のせいで / Verb + せいで)","tip":"Think of this as \"blaming\" something. Use 「おかげで」 if the result is positive."},{"example":"私には命しかありません","jlpt":"N4","pattern":"～しか～ない (Noun + しか + Negative Verb)","meaning":"～しか～ない (Noun + しか + Negative Verb) only; nothing but (used with negative verbs)","tip":"It emphasizes that there is nothing else. It always pairs with a negative verb, even though the English translation sounds positive."},{"meaning":"～くなる / ～になる (Adj/Noun + なる) to become; to reach a new state or change","pattern":"～くなる / ～になる (Adj/Noun + なる)","tip":"Pair with 「ない」 form (moving -> not moving) to show a change in ability or condition.","jlpt":"N4","example":"足が動かなくなりました"},{"tip":"Use this for 'natural consequences' or to describe the next thing you noticed after an action.","meaning":"～と (Verb Dictionary form + と) when (X happens, Y follows immediately or naturally)","pattern":"～と (Verb Dictionary form + と)","jlpt":"N4","example":"川を渡ると、今度は山賊が来ました"},{"meaning":"～なければならない (Verb-ない form + ければならない) must; have to (obligation)","pattern":"～なければならない (V-nai form + ければならない)","tip":"In casual speech, this is often shortened to 「なきゃ」 or 「なくちゃ」.","jlpt":"N4","example":"走らなければならない"}],[{"example":"風のように","meaning":"Noun + のように like; similar to (describing an action/state)","pattern":"Noun + のように","tip":"Use 「のように」 for actions (verbs) and 「のような」 for things (nouns). Think of it as 'in the manner of'.","jlpt":"N4"},{"jlpt":"N5","tip":"This is the standard way to speak politely about completed actions in the past.","pattern":"Verb (Masu-stem) + ました","meaning":"Verb (Masu-stem) + ました Polite past tense suffix for verbs.","example":"走りました"},{"jlpt":"N4","tip":"Use the Dictionary form for 'about to happen,' the ～ている form for 'in the middle of,' and the ～た form for 'just finished'.","pattern":"Verb (Dictionary form) + ところだ/です","meaning":"Verb (Dictionary form) + ところだ/です About to do; on the verge of (happening).","example":"沈むところでした"},{"pattern":"Verb (Nai-stem) + れる / られる","tip":"In passive sentences, the person who was affected by the action is the subject. For Ichidan verbs, add 「られる」; for Godan, change the last vowel to 'あ' and add 「れる」.","jlpt":"N4","example":"殺されるところでした","meaning":"Verb (Nai-stem) + れる / られる Passive voice (to be done/to be acted upon)."},{"meaning":"Verb (て-form) The て-form used to connect sentences or indicate a sequence of events.","example":"十字架にかけられて","jlpt":"N5","pattern":"Verb (Te-form)","tip":"In this context, it shows that one action (being put on the cross) happened before the next (being killed)."}],[{"example":"人を信じることは嘘ではない。","meaning":"Verb-辞書形 + こと Nominalizing a verb to make it a subject or object (The act of...)","tip":"Use 「こと」 to transform an action into a Noun so you can say something 'is' good, hard, or important.","pattern":"V-辞書形 + こと","jlpt":"N5"},{"jlpt":"N5","pattern":"～ている / ～ていない","meaning":"～ている / ～ていない State of being / Continuous action (negative past)","tip":"For clothing, 「ている」 describes the state of wearing it, not the act of putting it on.","example":"服を着ていませんでした。"},{"tip":"Use this when someone intentionally changes one thing into another.","meaning":"Noun + にする Make/Change something into a certain state or category","pattern":"Noun + にする","jlpt":"N4","example":"私をあなたたちの友だちにしてくれないか。"},{"example":"あなたを抱きしめることができません。","jlpt":"N4","pattern":"V-辞書形 + ことができる","meaning":"Verb-辞書形 + ことができる Potential (can/cannot do)","tip":"This is a more formal way to express potential compared to the potential verb form (e.g., 抱きしめる (to hug) vs 抱きしめられる (can hug))."},{"example":"あなたにたたかれないと、...","jlpt":"N4","pattern":"V-ない形 + と","meaning":"Verb-ない形 + と Conditional 'if' / 'unless' (If A doesn't happen, B (result) follows naturally)","tip":"The 'Verb-ない + と' pattern often expresses that the second action is impossible without the first."},{"example":"あきらめようとしました。","pattern":"V-意向形 (Volitional) + と（する）","jlpt":"N3","tip":"誰かが何をしようとしていたのか、あるいはまさに何かを始めようとしていたのかを説明するのに使います。","meaning":"何かをしようと試みること / 今にも何かを始めようとすること"},{"meaning":"（状態の）変化になる","tip":"これは変化を表します。「恥ずかしくなる」は、メロスが最初恥ずかしくなかったが、その後恥ずかしくなったことを示唆しています。","jlpt":"N3","pattern":"い-Adj（～く） + なる / な-Adj + になる","example":"メロスはとても恥ずかしくなって、..."}]],"intermediate":[[{"pattern":"～うちに","meaning":"〜している間に （行動が進行中である期間）","tip":"「状態が変わらない間に」と考えてください。このテキストでは、彼の歩いている期間を指します。","example":"歩いているうちに","jlpt":"N3"},{"jlpt":"N4","example":"友人を訪ねるつもりだ","tip":"個人的な意図に使われます。公式の予定には、「予定」を使います。","pattern":"～つもりだ","meaning":"〜するつもりだ；〜する計画だ"},{"jlpt":"N4","example":"迎えることになっていた","tip":"これは個人的な気まぐれではなく、外部の力によって決定されたり、社会的な取り決めとして使われます。","meaning":"〜することになっている；〜するのが規則や慣習である","pattern":"～ことになっている"},{"tip":"これは強い確信を表します。ここでは、メロスは現実が彼の論理的な期待と一致しないため混乱しています。","meaning":"〜のはずだ；（証拠や論理に基づいて）〜だと予想する","pattern":"～はずだ","jlpt":"N4","example":"にぎやかだったはずだが"},{"jlpt":"N4","example":"倒さなければならない","tip":"否定形（〜ない）の「い」を削除し、「〜ければならない」を追加することで形成されます。公式な文章や強い口調でよく使われます。","pattern":"～なければならない","meaning":"〜しなければならない；〜せねばならない（文字通り：「〜しないならば、良くない」）"},{"example":"生かしておくわけにはいかない","jlpt":"N2","meaning":"〜するわけにはいかない；〜してはならない（社会的・道徳的な理由により）","pattern":"～わけにはいかない","tip":"これは身体的な能力ではなく、それが間違っているか無責任であるために何かをすることができないことについてです。"}],[{"jlpt":"N4","tip":"「そのまま」または「〜の状態にしておく」と考えてください。多くの場合、過去形（〜た）の後に続きます。","pattern":"～まま","meaning":"別の行動が起こっている間に、状態が変わらないことを示します。","example":"荷物を背負ったまま"},{"jlpt":"N4","pattern":"～はずがない","tip":"これは単なる「いいえ」よりもはるかに強いです。論理に基づいた話者の完全な不信感を表現します。","meaning":"何かが不可能である、または起こらないという強い確信を表現します。","example":"帰ってくるはずがない"},{"example":"結婚式を挙げさせ","meaning":"誰かに何かをさせたり、許したりすることを示す使役形です。","tip":"この文脈（妹の結婚式）では、「強制する」というよりは「手配する」または「便宜を図る」という意味合いを持ちます。","pattern":"～させる (使役形)","jlpt":"N4"},{"meaning":"条件を表現します。アドバイスを与えたり、提案をしたり、前提を述べたりするのに使われます。","example":"情けをかけたいと思うなら","jlpt":"N3","tip":"「たら」や「と」とは異なり、「なら」は前の話者によって提供された文脈や現在の状況に焦点を当てます。","pattern":"～なら"},{"example":"身代わりを呼ぶがいい","meaning":"強い提案や命令を与える際に使われ、しばしばそれが唯一の、または最善の論理的な選択であることを暗示します。","pattern":"～がいい / ～がいいだろう","tip":"王様から発せられた場合、これは命令、あるいは権威的な雰囲気で与えられた許可のように聞こえます。","jlpt":"N2"},{"pattern":"～ていればいい / ～ていればよい","tip":"多くの場合、皮肉や対象の行動に対する無関心を暗示します。","jlpt":"N2","example":"うぬぼれていればいい","meaning":"話し手が相手の行動や状態を気にしないことを表現します。「勝手に〜すればよい」"},{"jlpt":"N2","tip":"これは、復讐心や優越感のニュアンスを伴って、誰かに何かを経験させたいという強い意図を表現します。","pattern":"～（さ）せてやる","meaning":"使役（誰かに気づかせる）と目下の人への「与える」という行動（やる）の組み合わせです。","example":"思い知らせてやりたい"}],[{"tip":"動詞の「ます」を落として「なさい」を付けます。しっかりとした表現ですが、丁寧さを含みます。","example":"知らせてきなさい","meaning":"命令形 (imperative form) より柔らかい命令のパターンで、親や先生がよく使います。","jlpt":"N5","pattern":"～なさい"},{"meaning":"動作や現象が突然始まることを示します。","example":"雨が降り出し","tip":"動詞の語幹 (Stem) + 出す を使います。雨や風のような自然現象によく使われます。","pattern":"～出す / ～出し","jlpt":"N4"},{"pattern":"～ずに","jlpt":"N3","meaning":"「～しない で (without doing)」の丁寧な言い方で、「～しないで」と同じです。","example":"一睡もせずに","tip":"動詞の「ない」を「ずに」に置き換えます。「する (to do)」は「せずに」になります。"},{"jlpt":"N3","pattern":"～かのような / ～かのように","meaning":"何かが他のものであるかのように見える、または振る舞う様子を説明するのに使われます。","tip":"比喩 (metaphor) や、必ずしも真実ではないことへの強い類似性を表現します。","example":"一瞬もしていないかのような"},{"pattern":"Volitional + とした / と属性","jlpt":"N3","meaning":"誰かが何かをしようと努力している、またはちょうど始めようとしていることを示します。","example":"無理に笑おうとした","tip":"意向形 (volitional form) (例: 行こう (Let's go), 食べよう (Let's eat)) + とする を使います。苦労や試みを暗示することが多いです。"},{"pattern":"～なければならない","jlpt":"N4","meaning":"義務や必要性（～しなければならない (must do)）を示します。","example":"町へ行かなければならない","tip":"これは「しなければならない」を表現する標準的な方法です。会話では、「なきゃ (nakya)」に短縮されることがよくあります。"},{"example":"早いほうがいいだろう","tip":"より強い勧めには過去形（た形）と、一般的な好みには辞書形と組み合わせます。","meaning":"アドバイスをしたり、ある選択肢が別の選択肢よりも好ましいことを示したりするのに使われます。","pattern":"～ほうがいい","jlpt":"N4"},{"meaning":"推測、当て推量、または可能性を表します。","example":"雨も弱まっているだろう","tip":"「でしょう」の普通形です。語尾を上げて同意を求める際にも使えます。","pattern":"～だろう / ～でしょう","jlpt":"N4"}],[{"meaning":"～しなければならない (must do)。何かをする義務があること。","tip":"くだけた会話では、これはしばしば「～なきゃ」に短縮されます。","jlpt":"N5","example":"走らなければならない。","pattern":"～なければならない"},{"pattern":"～ながら","example":"自分を励ましながら走った。","jlpt":"N4","tip":"通常、2つ目の（主要な）動詞に焦点が置かれます。","meaning":"～しながら (while doing)。同じ人物が同時に2つの行動を行っていることを説明するのに使われます。"},{"tip":"「は」の代わりに「も」を使うと、これが不必要なことの多くの一つであることを強調します。","meaning":"～する必要はない (no need to)。何かをする必要がないこと。","example":"そんなに急ぐ必要もない。","jlpt":"N4","pattern":"～（辞書形）必要はない/もない"},{"jlpt":"N3","example":"泳ぎ切るしかない。","pattern":"～切る / ～しかない","tip":"「V-切る」は完全に終えることを意味し、「～しかない」は他の選択肢がないことを表します。","meaning":"最後までやり遂げる / ～するしかない (have no choice but to)。"},{"pattern":"～ように","jlpt":"N3","example":"濁流はメロスの叫びを笑うように...","tip":"動詞の後に続く場合、それがどのように行動が行われるか、または何かが比喩的にどのように見えるかを説明します。","meaning":"～のように (as if); ～に似て (similar to)。外見や様子を説明するのに使われます。"},{"tip":"主節の前に動作が完了した場合は、「た形」を使うようにしてください。","meaning":"～時 (when); ～するとすぐに (as soon as)（特定の時点を示します）。","pattern":"～た時","example":"山道を登りきってほっとした時...","jlpt":"N3"},{"pattern":"～わけではない","jlpt":"N3","example":"私は決して君をだましたわけではない。","tip":"これは誤解を解消したり、言い訳をしたりする丁寧な方法です。","meaning":"～わけではない (it doesn't mean that...); ～ということではない (it's not the case that...)（推論を否定するのに使われます）。"}],[{"pattern":"～て (Conjunctive)","meaning":"動詞の「て形」動詞を接続し、行動や状態の連続を表す。","example":"村を過ぎて","tip":"動詞を連続して繋げる場合、「～て」は「そして」や「それから」のように考えることができます。","jlpt":"N5"},{"pattern":"V-stem + 出す","meaning":"動詞の語幹 + 出すは、ある行動が突然始まったこと、または開始されたことを示します。","example":"走り出した","jlpt":"N4","tip":"行動の外向きの動きや突然の開始に焦点を当てます。"},{"jlpt":"N3","tip":"比例的な変化（一方の事柄が増加または変化すると、他方も同様に変化する）に使用されます。","pattern":"V-Dictionary form + につれて","meaning":"動詞の辞書形 + につれては、Aが起こるとBも起こることを示し、2つの事柄が同時に変化することを示します。","example":"走るにつれて"},{"example":"精神そのものになったような気がした","meaning":"～気がするは、「～という感じがする」または「～のように感じる」という意味です。","pattern":"～気がする","jlpt":"N3","tip":"客観的な事実ではなく、主観的な感情や直感について使用されます。"},{"pattern":"V-Dictionary form + だけ","meaning":"動詞の辞書形 + だけは、「～だけ」「～に過ぎない」という意味です。他の行動は取られなかったことを強調します。","example":"走るだけだった","tip":"この文脈では、メロスが他の選択肢がなく、ただ一つのことに集中していたことを示しています。","jlpt":"N3"},{"pattern":"Volitional Form + としている","meaning":"意志形 + としているは、「～しようとしている」または「～の瀬戸際にある」という意味です。","example":"太陽はまさに沈もうとしていた","tip":"自然に、または誰かの意図によって、まさに起ころうとしている行動に使用されます。","jlpt":"N2"},{"jlpt":"N2","tip":"行動が起こっている特定の「時点」を強調したいときにこれを使用します。","meaning":"動詞の辞書形 / 動詞の～ている + ところだは、何かをしているまさにその瞬間。これから起こる行動に特定のタイミングを加えます。","example":"突き刺そうとしているところだった","pattern":"V-dict / V-ている + ところだ"}],[{"pattern":"～ろ / ～れ (命令形)","example":"私を殺せ！","tip":"フィクションや軍事的な状況、親しい男性同士の友人関係でよく使われますが、丁寧な会話では非常に失礼です。","meaning":"「ろ」または「れ」で終わる命令形は、直接的な命令を与えるために使われます。","jlpt":"N4"},{"meaning":"動詞の語幹 + ながらは、同じ人が2つの行動を同時に行っていることを示します。","tip":"主要な行動は「ながら」の後に来ます。ここでは、叫ぶことは群衆を押し分けることに対して副次的な行動です。","jlpt":"N4","pattern":"V-stem + ながら","example":"叫びながら"},{"meaning":"～てくれなければは、依頼を受ける（くれる）と仮定する条件形（ば形）を組み合わせたものです。","tip":"「もし～してくれないなら」と言うときに使います。話し手にとってその行動が必要であることを強調します。","jlpt":"N4","pattern":"～てくれなければ","example":"殴ってくれなければ"},{"tip":"ここでは、「響き渡る」と音の質や大きさを比較することで、その音を表現するために使われています。","meaning":"～ような + 名詞は、何かを他のものと比較して説明するために使われます（比喩/直喩）。","jlpt":"N3","pattern":"～ような + Noun","example":"響き渡るような音"},{"pattern":"～てしまう / ～てしまった","example":"君を疑ってしまった。","tip":"この文脈では、セリヌンティウスが友人を疑ったことに対する深い罪悪感と後悔を強調しています。","meaning":"～てしまう / ～てしまったは、行動の完了を表し、しばしば後悔や偶発的な出来事のニュアンスを伴います。","jlpt":"N4"},{"pattern":"～てくれないか","example":"仲間に入れてくれないか。","meaning":"～てくれないかは、質問の形をとった気軽な依頼や招待です。","tip":"命令よりも柔らかく、しばしば男性が頼み事や許可を求めるときに使います。","jlpt":"N4"},{"pattern":"～てたまらない","example":"恥ずかしくてたまらない","meaning":"～てたまらないは、感情や感覚が非常に強く、我慢できないほどである、または抗しがたいほどである、ということを示します。","tip":"通常、感情（悲しみ、喜び）や身体的感覚（喉の渇き、かゆみ）とともに使われます。","jlpt":"N3"}]],"original":[[{"jlpt":"N4","example":"羊と遊んで暮して来た。","tip":"現在の時点に向かって「来る」行動と考えてください。","pattern":"～てくる (～てきた)","meaning":"～てくる（～てきた）は、過去から現在まで続いてきた行動や状態を示します。"},{"tip":"個人的な意思ではなく、予定された出来事や社会的な規則に使う。","meaning":"予約、規則、他者が下した決定、あるいは状況を示す。","pattern":"～ことになっている","jlpt":"N4","example":"花婿として迎える事になっていた。"},{"example":"まちは賑やかであった筈だが","jlpt":"N4","pattern":"～はずだ","meaning":"何かがそうであるべきだという強い期待や確信を表す。","tip":"論理や過去の経験に基づいた話し手の期待を反映する。"},{"tip":"この文脈では、歩いている間に時間が経つにつれて自然に変化が起こったことを示唆する。","pattern":"～うちに (～ているうちに)","meaning":"ある状態や行動が続いている間に、変化が起きる。","jlpt":"N3","example":"歩いているうちに"},{"tip":"「～てみる」は、意図に「試しにやってみる」というニュアンスを加える。","pattern":"～てみる + つもりだ","meaning":"結果を見るために何かを試す意図や計画を表す。","jlpt":"N3","example":"訪ねてみるつもりなのだ。"},{"meaning":"「～なければならない」の文語的・古風な表現。「ぬ」は古典的な否定。","pattern":"～なければならぬ (ならない)","tip":"「ならぬ」はより形式的で断固とした表現で、この物語の壮大な調子に合っている。","example":"除かなければならぬ","jlpt":"N2"},{"pattern":"～をはばかる (憚る)","meaning":"社会的圧力や他者の存在のためにためらう、控える。","tip":"「あたりを憚る (あたりをはばかる) 」（周囲を気にする）というフレーズでよく使われる。","example":"あたりをはばかる低声で","jlpt":"N1"}],[{"pattern":"～たまま / ～たままで","example":"買い物を、背負ったままで","meaning":"状態が変わらずにいること。ある状態を保ちながら何かをする。","tip":"「靴を履いたまま家に入る」のように、ある行動が予期せぬ、あるいは不適切な状態につながる場合によく使われる。","jlpt":"N4"},{"tip":"話し手の心の中にある強い意図を表し、単なる願望よりも確固としている。","jlpt":"N4","meaning":"何かをする意図や計画。","pattern":"～つもりだ / ～つもりであった","example":"この短刀で何をするつもりであったか。"},{"tip":"この文脈では、主語を強調している。「私でさえも…」。","jlpt":"N3","meaning":"～でさえ/も（強調）。","pattern":"～だって / ～だって～のだが","example":"わしだって、平和を望んでいるのだが。"},{"example":"自分の地位を守る為か。","pattern":"～ため（に）","tip":"名詞や動詞の辞書形に付く場合、目標や目的を示す。","jlpt":"N3","meaning":"～の目的で、～のために。"},{"example":"信じては、ならぬ。","pattern":"～てはならぬ / ～てはならない","jlpt":"N3","tip":"「ならぬ」は「ならない」の古く、文学的な形である。強い禁止や社会的な規則に用いられる。","meaning":"～してはいけない（禁止）。"},{"pattern":"～にきまっている","example":"どうせ帰って来ないにきまっている。","tip":"話し手による強い主観的確信を表す。「どうせ」が伴うことが多く、皮肉や諦めの態度を示す。","jlpt":"N3","meaning":"～に決まっている；きっと～だ。"},{"example":"人の腹綿の奥底が見え透いてならぬ。","pattern":"～てならぬ / ～てならない","meaning":"～てたまらない；～て仕方がない（抑えられない感情や身体の状態）。","tip":"自然に生じ、抑えるのが難しい感情や身体的感覚に使う。「ならぬ」は文学的な形式である。","jlpt":"N2"},{"tip":"使役（～させる）と「～てやりたい」を組み合わせることで、誰かの利益のために何かを許可したり、させたりしたいという願望を表す。","jlpt":"N4","meaning":"他者に何かをさせる（使役）＋恩恵として何かをする（～てやる）。","example":"亭主を持たせてやりたいのです。","pattern":"～（さ）せてやりたい / ～（さ）せる"}],[{"meaning":"過去に進行中の行動や継続していた状態を示す。","example":"村人たちは野に出て仕事をはじめていた。","jlpt":"N5","pattern":"～ていた","tip":"物語では、主要な出来事の背景を設定する。"},{"jlpt":"N4","pattern":"～なければならぬ","tip":"The ending 「ぬ」 instead of 「ない」 gives the character's speech a determined, slightly old-fashioned tone.","meaning":"Indicates obligation (must do). 「ならぬ」 is a formal/literary version of 「ならない」.","example":"またすぐ市に行かなければならぬ。"},{"meaning":"To try to do or attempt to perform an action. (〜しようとする)","example":"無理に笑おうと努めた。","pattern":"Volitional + と（する/努める）","jlpt":"N3","tip":"Use this when someone is making a conscious effort to do something difficult."},{"example":"結婚式を明日にしてくれ、と頼んだ。","meaning":"A quoted request; 'please do X'. Often used when reporting what someone asked for. (〜てください)","tip":"It is the informal/imperative version of 「〜てください」, commonly used in narratives.","jlpt":"N3","pattern":"～てくれと（頼む/言う）"},{"pattern":"～まま","jlpt":"N3","tip":"In this context, it expresses the desire to stay in the current state/location forever.","meaning":"As it is; leaving a condition unchanged. (〜のまま)","example":"このままここにいたい、と思った。"},{"pattern":"～ていたかった","jlpt":"N2","tip":"This combines the 「〜ている」 (state) with 「〜たい」 (want) in the past tense to show a lingering feeling.","meaning":"Wants to be in the state of doing something; indicates a persistent desire for a continuous action. (〜ていたかった)","example":"少しでも永くこの家に愚図愚図とどまっていたかった。"},{"meaning":"Expresses the speaker's conjecture or strong probability regarding a current or future state (literary). (〜ていよう)","example":"雨も小降りになっていよう。","jlpt":"N1","pattern":"～ていよう","tip":"In modern Japanese conversation, we usually use 「〜ているだろう」, but 「〜ていよう」 is common in classic literature."}],[{"jlpt":"N5","example":"寝過したか、いや、まだまだ大丈夫。","pattern":"～か","meaning":"Indicates a question, doubt, or self-confirmation, often used in internal monologues. (〜か)","tip":"In literature, 「か」 at the end of a sentence often represents a character's internal thought process or sudden realization."},{"example":"約束の刻限までには十分間に合う。","jlpt":"N4","meaning":"Indicates a time limit or deadline by which an action must be completed. (〜までに)","pattern":"～までに","tip":"Don't confuse this with 「まで」 (until). 「までに」 is for a deadline (one-time action), while 「まで」 is for a continuous state."},{"example":"身代りの友を救う為に走るのだ。","jlpt":"N4","tip":"When preceded by a Noun, keep the 「の」 particle. It sounds more formal and determined than 「ように」.","meaning":"Used to express a purpose, objective, or reason for doing something. (〜ために/〜がために)","pattern":"～ために / ～がために"},{"meaning":"Indicates obligation or necessity. 「ならぬ」 is a classical/literary version of 「ならない」.","pattern":"～なければならぬ (ならない)","tip":"In modern speech, you use 「ならない」, but 「ならぬ」 is frequently seen in literature to give a sense of gravity or historical tone.","example":"走らなければならぬ。","jlpt":"N4"},{"example":"陽は既に西に傾きかけている。","jlpt":"N3","tip":"Usually used with verbs that describe a process, like 'dying', 'setting (sun)', or 'eating'.","meaning":"Indicates that an action or state has started but is not yet finished (halfway through). (〜かける/〜かけている)","pattern":"～かける / ～かけている"},{"tip":"This often implies that if you don't act now, the opportunity will pass or the situation will change for the worse.","pattern":"～ないうちに","meaning":"Means 'while' or 'before' something happens. Usually indicates a limited window of time. (〜ないうちに)","jlpt":"N3","example":"あれが沈んでしまわぬうちに、王城に行き着くことが出来なかったら･･･"},{"example":"泳ぎ切るより他に無い。","jlpt":"N3","tip":"This pattern emphasizes a sense of determination or being cornered by circumstances.","meaning":"Expresses that there is no other choice or alternative but to do something. (〜よりほかにない/〜ほか（は）ない)","pattern":"～よりほかにない / ～ほか（は）ない"},{"meaning":"While doing something; at the same time. Similar to 「ながら」 but more formal/literary. (〜つつ/〜つつも)","pattern":"～つつ / ～つつも","tip":"「つつも」 implies a contrast, similar to 'even though I was being...'. It is very common in written narratives.","example":"押し流されつつも、見事、対岸の樹木の幹に、すがりつく事が出来た。","jlpt":"N2"}],[{"pattern":"～れる / ～られる (Passive)","example":"私は信頼されている。","meaning":"The passive voice, used when the subject is the receiver of an action. (〜れる/〜られる)","jlpt":"N5","tip":"In literature, this often emphasizes the mental or emotional state of the subject being acted upon by others."},{"example":"忘れてしまえ。","jlpt":"N4","meaning":"Indicates the completion of an action, often with a sense of regret or a command to finish it completely.","tip":"In the imperative form (~しまえ), it expresses a strong determination or a forceful command to move past something.","pattern":"～てしまう / ～てしまえ (Imperative)"},{"example":"走れるようになったではないか。","meaning":"Indicates a change in ability or habit; becoming able to do something.","jlpt":"N4","tip":"Use this when describing a transition from 'cannot' to 'can'. In this text, it marks Melos's recovery of strength.","pattern":"～ようになる"},{"tip":"Combined with 'ください', it is a humble way to ask for permission ('Please let me...').","jlpt":"N4","meaning":"The causative form, meaning to make or let someone do something.","example":"正直な男のままにして死なせて下さい。","pattern":"～せる / ～させる (Causative)"},{"tip":"This is a more formal or dramatic version of 'しかない', perfect for high-stakes situations.","meaning":"Expresses that there is no other way or choice but to do a specific action.","jlpt":"N3","example":"走るより他は無い。","pattern":"～より他はない (yori hoka wa nai)"},{"pattern":"～ところだ (tokoro da)","example":"あの方が死刑になるところです。","meaning":"Indicates that an action is about to happen or is in the middle of happening.","jlpt":"N3","tip":"The tense of the verb before 'ところ' changes the nuance: Dictionary form means 'just about to start'."},{"tip":"This is a nuanced way of saying 'it might happen' without sounding too certain. Use it for cautious optimism.","meaning":"A double negative used to suggest that something is not impossible, or there is a slight possibility.","jlpt":"N2","example":"ひょっとしたら、間に合わぬものでもない。","pattern":"～ないものでもない"},{"pattern":"(Volitional Verb) + とした時","example":"まさに最後の一片の残光も、消えようとした時...","jlpt":"N2","meaning":"Describes a moment when something was just about to happen (often interrupted by something else).","tip":"This creates a cinematic effect in storytelling, freezing the moment right before a major change occurs."}],[{"jlpt":"N5","pattern":"～てくる (て形 + 来る)","tip":"In this context, it shows physical movement toward the speaker's location, but it can also mean a process starting in the past and continuing to the present.","meaning":"Indicates the completion of an action or a change that results in the current state (to come to be).","example":"メロスが帰って来た。"},{"example":"叫びながら","meaning":"Indicates two actions happening simultaneously by the same person.","tip":"The main action always comes second. Here, 'crying out' is the background action while 'climbing the platform' is the main movement.","pattern":"～ながら (Stem + ながら)","jlpt":"N4"},{"example":"君が若し私を殴ってくれなかったら","meaning":"A conditional 'if' used to express a hypothetical situation or a specific result.","tip":"It is often paired with 'もし' (if) to emphasize the hypothetical nature of the sentence.","pattern":"～たら (Plain past + ら)","jlpt":"N4"},{"example":"抱擁する資格さえ無いのだ。","meaning":"Emphasizes an extreme example to imply that other things are also true (even...; not even...).","tip":"It replaces particles like 'が' or 'を' and carries a nuance of 'something as basic as this'.","pattern":"～さえ (Noun + さえ)","jlpt":"N3"},{"example":"皆に見られるのが","meaning":"Used to indicate the passive voice, where the subject is the recipient of the action.","tip":"In Japanese, the passive is often used to express 'feeling troubled' by someone else's action (Suffering Passive).","pattern":"～られる (Passive Voice)","jlpt":"N4"},{"tip":"'まい' is a negative volitional suffix. This pattern asks 'Won't you do [action] for me?' and sounds very masculine and authoritative yet humble here.","jlpt":"N2","pattern":"～てくれまいか (て形 + くれまいか)","example":"仲間に入れてくれまいか。","meaning":"A formal or slightly archaic way to make a polite request or invitation (won't you?)."},{"meaning":"A strong, formal, or literary prohibition (must not).","example":"殺してはならぬ。","jlpt":"N2","pattern":"～てはならぬ / ～てはならない","tip":"'ならぬ' is the classical/literary form of 'ならない'. It is used for rules or solemn commands."}]]},"lemon":{"simplified":[[{"meaning":"Whenever A happens, B inevitably happens or follows. (Natural/conditional consequence)","example":"お酒を毎日飲んでいると","jlpt":"N4","tip":"Think of this as 'whenever' or 'if/when' for habitual actions or physical results.","pattern":"～と (Condition)"},{"meaning":"継続的な状態や現在進行中の行動を説明する。","example":"ゴミが落ちている場所です。","jlpt":"N4","pattern":"～ている (State)","tip":"落ちるのような動詞の場合、これは落ちた後の「状態」を表します（つまり、「地面に横たわっている」）。"},{"example":"すぐに立ち上がって帰りたくなります。","meaning":"行動や動詞をしたいという願望。","jlpt":"N4","tip":"これを動詞と一緒に使うには、動詞を「ます形」の語幹に変えて「たい」を追加します。動詞をい形容詞に変えます。","pattern":"～たい (Desire)"},{"pattern":"～そう (Appearance)","tip":"これを「ます形」の語幹に付けます。注意してください。否定の「そうではない」の場合、大きく変化します（例：なさそう）。","jlpt":"N3","example":"壊れそうな町です。","meaning":"何かが起こりそうだ、またはそう見える。"},{"jlpt":"N3","meaning":"能力や可能性を表現する（できない / できる）。","example":"部屋の中にいることができないのです。","tip":"これは、可能形（れる/られる）と比較して、能力について話すよりフォーマルまたは明示的な方法です。","pattern":"～ことができる"},{"pattern":"～くらい / ～ぐらい","tip":"特定の状況を感情や行動の強さを説明するための尺度として使用したい場合に使用します。","jlpt":"N3","meaning":"〜の程度まで / とても〜なので","example":"どこを歩いているかわからないくらい、たくさん歩きました。"},{"jlpt":"N3","example":"病気のせいだけではありません。","meaning":"否定的な結果の理由を示す（〜のせいで / 〜の過失で）。","pattern":"～せい (Reason/Fault)","tip":"これは「おかげで」の「悪い」バージョンだと考えてください。結果が望ましくない場合にのみ使用してください。"}],[{"jlpt":"N5","tip":"動詞の辞書形を「こと」の前に常に使用してください。","example":"何も買うことができませんでした。","meaning":"可能性や能力（何かをすることができる/できない）を表現するために使用される。","pattern":"Dictionary form + ことができる"},{"pattern":"何(も) + Negative Verb","example":"何も買うことができませんでした。","meaning":"「何も」「全然〜ない」または「全く〜ない」という意味で、否定動詞の後に続く。","tip":"この文脈では、「も」は「全く」のように機能し、否定を強調します。","jlpt":"N5"},{"jlpt":"N5","tip":"窓を「見ている」ように、直接見たり、聞いたり、感じたりできるものには「の」を使用してください。","meaning":"動詞を名詞句に変え、文の主語または目的語にする。","example":"店の窓を見るのは楽しかったです。","pattern":"Dictionary form + の/こと"},{"jlpt":"N4","tip":"これを「自然の法則」または「ボタン」の「もしも」と考えてください。ボタン（条件）を押すと、ライトが点灯します（結果）。","example":"夜になると、店の電気が明るくて...","meaning":"当然の結果、習慣、または避けられない結果を表現する（Aが起こるたびにBが続く）。","pattern":"Dictionary form + と"},{"tip":"主な行動が2番目に来ます。ここでは、「幸せであること」が状態であり、「歩くこと」が背景の行動です。","example":"私は町を歩きながら、とても幸せでした。","meaning":"同じ人が同時に2つの行動を行っていることを示す。","pattern":"Stem + ながら","jlpt":"N4"},{"tip":"この話では、悪い気持ちが完全に、そしておそらく予期せず消えたことを強調しています。","meaning":"行動の完了を表し、多くの場合、後悔、驚き、または意図しない完了の感覚を伴う。","example":"あんなに暗くて嫌な気持ちが、たった一つのレモンで消えてしまったのです。","pattern":"Verb (Te-form) + しまう/しまった","jlpt":"N4"},{"pattern":"Stem / Adjective Stem + すぎる","example":"重すぎず、軽すぎず、私の心にちょうどよかったです。","meaning":"何かが過剰である、または「〜すぎる」ことを示す。否定の「すぎず」は「〜すぎない」という意味である。","tip":"い形容詞の場合、「い」を取り除きます。例えば、「重い」は「重すぎる」になります。","jlpt":"N3"}],[{"meaning":"AとB（網羅的なリスト）","example":"丸善は、大きい本屋と文房具の店です。","tip":"名詞を接続する場合、英語の「and」と完全に一致します。「など」とは異なり、これらのアイテムだけが言及されていることを暗示しています。","jlpt":"N5","pattern":"A と B"},{"example":"あの丸善に入ってみよう","tip":"経験を試したいときに使われます。意向形「みよう」では、自分自身に向けた「〜しようか」または「〜しよう」を反映しています。","meaning":"何かを試してみる / 何かがどのようなものかを見てみる","pattern":"～てみる (volitional: ～てみよう)","jlpt":"N4"},{"pattern":"～と、～","jlpt":"N4","example":"丸善にいると、息が苦しくなります。","tip":"節の最後に使われる場合、その「と」は避けられない結果や環境への物理的な反応を示します。","meaning":"Aが起きるごとに、Bが自然に続く (条件)."},{"pattern":"～ふりをする","jlpt":"N3","meaning":"～のふりをする; ～のように振る舞う...","tip":"通常、意図的な欺瞞や演技に使われます。動詞の普通形または名詞 + 「の」と一緒に使います。","example":"知らないふりをして店を出たら、どうなるだろう"},{"tip":"これは日本語で最も用途の広い「もし」です。条件が満たされた「後」に何が起こるかに焦点を当てます。","example":"知らないふりをして店を出たら、どうなるだろう","meaning":"もし/～たら (条件).","pattern":"～たら","jlpt":"N3"},{"jlpt":"N3","pattern":"～（の）ようだ/ようです","tip":"何かを別のものと比較して説明するために使用されます。「名詞 + のよう」で直喩を作ります。","example":"全部そのレモンの黄色に吸い込まれるようでした。","meaning":"～のようだ; まるで～; ～のように見える (直喩/外見)."},{"meaning":"～してから (一連の出来事).","tip":"イベントBはイベントAが完了するまで起こりえないことを強調します。単に時間順序を示す「後で」とは異なります。","example":"私が店を出てから数分後に、ドカーンと大きい爆発をします。","jlpt":"N3","pattern":"～てから"}]],"intermediate":[[{"example":"お酒を毎日飲んでいると","pattern":"V-Dictionary form + と","jlpt":"N4","tip":"このパターンは、条件が満たされるたびに発生する習慣的な行動や自然な結果に使用されます。","meaning":"動詞の辞書形 + と."},{"example":"壊れかかった街だ","pattern":"V-stem + かける / かかった","jlpt":"N3","meaning":"動作の途中にいる、または何かを始めようとしている (しばしば完了しなかったことを示唆する).","tip":"これは、変化が始まったがまだ最終的な結果に達していない事柄、例えば「死にかける」や「食べかける（食べかけ）」のようなものに使います。"},{"jlpt":"N3","pattern":"V-stem + 回る (まわる)","example":"京都の街から街へと歩き回っていた","tip":"これは、広い範囲での動き、例えば「走り回る」や「見回る」のように、行動を物理的に表現します。","meaning":"辺りを動き回る、またはあてもなく何かをする。"},{"example":"急に立ち上がって帰りたくなってしまう","pattern":"V-Te-form + しまう / しまった","jlpt":"N4","tip":"この文脈では、語り手の突然の衝動に対する制御の欠如を強調しています。","meaning":"結局～してしまう (しばしば不本意や後悔を伴う)."},{"jlpt":"N4","pattern":"V-causative (せて/させて)","example":"何かが私をそこにじっとさせておかないのだ","meaning":"誰かに何かをさせる、または許す。","tip":"この文章では、「させておかない」は「私をじっとさせておかない」という意味で使われています。「ない」の語尾に注意してください。"},{"jlpt":"N3","pattern":"～のだ / ～んだ","example":"自分の心の中の風景と似ていると感じたのだ","tip":"文学では、これはしばしば出来事の描写から語り手の内面的な考えや理由の描写への移行を示します。","meaning":"強調のため、または状況について説明や背景を提供するために使用されます。"},{"jlpt":"N3","example":"どうしようもない重い気持ち","pattern":"～ようがない / ～ようもない","meaning":"どうしようもない; それをする方法がない。","tip":"「どうしようもない」は「無力な」または「絶望的な」を意味する非常に一般的な定型表現です。"}],[{"jlpt":"N5","pattern":"V(potential)","example":"何も買えなかった","tip":"現代の言葉では、る動詞に対して「ら抜き」（「ら」を省略すること）が一般的です（例：食べられるの代わりに食べれる）。","meaning":"可能形: 何かをすることができる能力を示します。る動詞の場合、「る」を「られる」に置き換えます。う動詞の場合、最後の母音を「え」に変え、「る」を追加します。"},{"jlpt":"N4","pattern":"V(stem) + 続ける","tip":"これは複合動詞です。ある期間にわたって動作が続く場合に使用します。","example":"歩き続けた","meaning":"ある動作をし続ける。（動詞の語幹 + 続ける）"},{"meaning":"～のような気がする; ～という予感がする...","example":"元気が出てくるような気がした","tip":"客観的な事実ではなく、主観的な感情や直感のためにこれを使用します。","jlpt":"N3","pattern":"～気がする"},{"pattern":"V(Dictionary form) + ことで有名だ","jlpt":"N3","tip":"「こと」は動詞を名詞句に変え、助詞「で」で続けることができます。","example":"果物を並べることで有名だった","meaning":"～することで有名だ (Known for / Famous for doing something)."},{"meaning":"V（普通形過去）＋瞬間（に） (The moment that... / As soon as...).","tip":"これは2つの行動がほぼ同時に起こったことを強調します。","example":"レモンを買った瞬間から","jlpt":"N3","pattern":"V(Plain past) + 瞬間（に）"},{"pattern":"V(Te-form) + くる","jlpt":"N3","meaning":"V（て形) + くる (An auxiliary used to describe a process that is beginning, or an action coming toward the speaker (physically or metaphorically)).","tip":"この文脈では、話し手の内面の状態の変化（元気が出てくる）を示しています。","example":"元気が出てくるような気がした"},{"meaning":"～（かの）ような / ように (As if / Like. Used to describe something that appears to be something else or to make a comparison).","tip":"「そう (looks like)」とは異なり、「ような」は比喩や、類似性をより確信している場合に使われます。","example":"健康になったような錯覚に陥った","pattern":"～（かの）ような / ように","jlpt":"N3"},{"jlpt":"N2","pattern":"～なんて / とは","meaning":"～なんて / とは (Expresses surprise, disbelief, or emotional emphasis regarding a fact. Often used when the speaker is moved by something).","tip":"この表現は文末の感嘆符のように機能し、しばしば「～なんて信じられない」という意味合いを含みます。","example":"幸せになれるなんて"}],[{"example":"丸善に入っていった。","pattern":"～ていく (te-iku)","jlpt":"N4","meaning":"～ていく (To go and do something / To continue a movement away from the speaker).","tip":"「行く」は、行動が現在の場所から離れていく、または未来に向かって進むことを示します。"},{"jlpt":"N3","tip":"これは、ある行動の直後に起こる突然の予期せぬ変化に使用します。","meaning":"～た途端 (Just as; the moment that...).","example":"店に入った途端","pattern":"～た途端 (ta totan)"},{"jlpt":"N3","meaning":"～はず (Expected to be; should be (based on logic or general expectation)).","tip":"現実は異なっていても、何かが真実であると強く信じる理由がある場合に「はず」を使用します。","example":"好きなはずの画集","pattern":"～はず (hazu)"},{"meaning":"～ては (Repetition of actions (A, then B, A, then B...)).","tip":"この構造は、行ったり来たりする人のように、行動や出来事の繰り返しのサイクルをしばしば表します。","jlpt":"N2","pattern":"～ては (te wa)","example":"本を引き出しては積み上げ"},{"example":"成し遂げたかのように","pattern":"～かのように (ka no you ni)","jlpt":"N3","tip":"これは比喩のために使われます。話し手はそれが文字通り真実ではないことを知っていますが、そのように感じられます。","meaning":"～かのように (As if; just like...)."},{"meaning":"～のだ / ～んだ (Explanatory emphasis; giving a reason or clarifying a situation).","tip":"文学では、これはしばしば気づきの瞬間や行動に対する決定的な説明を示します。","jlpt":"N4","pattern":"～のだ / ～んだ (no da / n da)","example":"レモンを置いたのだ。"},{"example":"知らん顔をして外へ出たらどうなるだろう","pattern":"～たらどうなる (tara dou naru)","jlpt":"N4","tip":"これは、仮定の質問をしたり、行動の結果について考えたりする標準的な方法です。","meaning":"～たらどうなる (What if...; What would happen if...?)."}]],"original":[[{"meaning":"～と (Indicates a natural consequence, habit, or a certainty that follows an action. (When/If A, then B)).","example":"酒を毎日飲んでいると...時期がやって来る。","pattern":"～と","jlpt":"N4","tip":"この文脈では、定期的な出来事や避けられない結果を表します。事実や物理法則によく使用されます。"},{"pattern":"～てしまう","jlpt":"N4","tip":"文学では、これはしばしば状態の最終性、または話し手の感情的な解決を強調します。","example":"京都から逃げ出して誰一人知らないような市へ行ってしまいたかった。","meaning":"～てしまう (To do something completely, or to do something accidentally/regrettably)."},{"meaning":"～とか～とか (Used to list multiple examples or possibilities (like 'A and B', 'A or B')).","pattern":"～とか～とか","tip":"「や」とは異なり、「とか」はよりカジュアルで、一連の場所や物の例を挙げる際によく使われます。","jlpt":"N4","example":"京都から何百里も離れた仙台とか長崎とか..."},{"meaning":"ある行為の結果として生じた状態が存続していること、または存在していることを示す助動詞。","example":"汚い洗濯物が干してあったりがらくたが転がしてあったり...","pattern":"～てある","jlpt":"N4","tip":"行為を行った人よりも、客体の状態に焦点を当てる。誰かが意図して行ったという含みがある。"},{"meaning":"いくつかある行動や状態の中から、いくつか例を挙げて列挙するものであり、挙げられたものが全てではないことを示唆する。","example":"土塀が崩れていたり家並が傾きかかっていたり...","tip":"最後の「する」は省略したり、「している」のように異なる形に変化させたりすることができる。","jlpt":"N4","pattern":"～たり～たりする"},{"meaning":"ある行為や状態が始まりはしたが、まだ終わっていない、または途中の段階にあることを示す。","pattern":"～（ます形）＋かける / かかっている","tip":"物事が途中の段階にある場合（例：「食べかけ」、「腐りかけ」など）に使う。","jlpt":"N3","example":"家並が傾きかかっていたり..."},{"jlpt":"N2","tip":"過去を「懐かしく振り返る」または「回想する」という強い感情的なニュアンスを持つ。","pattern":"～たものだ","example":"私は幼い時よくそれを口に入れては父母に叱られたものだが...","meaning":"過去の懐かしい習慣や、頻繁に起こっていた出来事を表現するのに使う。"}],[{"jlpt":"N4","pattern":"～てしまう (～てしまった)","tip":"この文脈では、友人が去ってしまったことの完了性を強調し、語り手の空虚感に寄与している。","meaning":"完了を表し、しばしば後悔や偶発的な出来事のニュアンスを伴う。","example":"友達が学校へ出てしまったあと"},{"pattern":"(V-ba form) + (V-Dictionary form) + ほど","jlpt":"N3","example":"奥へゆけばゆくほど堆高く積まれている。","meaning":"（A）すればするほど、（B）となる。比例的な増加を説明するのに使う。","tip":"使われる動詞は、パターンの両方の部分で同じでなければならない。"},{"meaning":"最終的に特定の（しばしば極端な、または形式的な）結果や状態に達する状況を説明する。","example":"あんなにも私を誘惑するには至らなかったと思う。","tip":"結果や結論に「至る」ことを示すフォーマルな言い方である。","pattern":"～に至る (～には至らなかった)","jlpt":"N2"},{"pattern":"(Verb/Adjective) + ほど","jlpt":"N3","meaning":"～の程度まで／～なほど。描写の程度や規模を示す。","example":"思わせるほどなので","tip":"感情や状態の強さを測る尺度として特定の状況を使いたいときに使う。"},{"pattern":"～のような / ～のように","jlpt":"N4","meaning":"何かを他のものと比較して説明する際に使う（直喩・隠喩）。","example":"あの檸檬が好きだ。レモンエロウの絵具をチューブから搾り出して固めたような...","tip":"「名詞＋の＋ような」は名詞を修飾し、「名詞＋の＋ように」は動詞や形容詞を修飾する。"},{"tip":"「ように」とは異なり、「ために」は明確な意図や直接的な利益・理由を意味する。","example":"身体に熱が出た。事実友達の誰彼に私の熱を見せびらかすために...","meaning":"行動の目的、目標、または理由を示す。","jlpt":"N4","pattern":"(Verb-dictionary / Noun + の) + ために"},{"tip":"ここでは、冷たさが徐々に体の奥深くまで広がる身体感覚を表している。","meaning":"話し手の現在の視点から離れていく動き、または未来への連続的な変化を示す。","example":"掌から身内に浸み透ってゆくような...","jlpt":"N4","pattern":"～てゆく (～ていく)"},{"tip":"「思いあぐむ」や「探しあぐむ」などの思考や探索の動詞と共によく使われる文学的な表現である。","meaning":"何かをすることに飽きる、または長い間成功せずに何かをすることに苦労する意味。","example":"探しあぐんでいたもので","jlpt":"N1","pattern":"(V-stem) + あぐむ (あぐんでいた)"}],[{"jlpt":"N4","example":"歩き廻った疲労が出て来たのだと思った。","meaning":"理由を説明したり、背景情報を提供したり、発見や結論を強調したりするのに使う。","tip":"書き言葉では、「のだ」は単純な丁寧形よりも決定的または説明的に響く。","pattern":"～のだ / ～んだ"},{"pattern":"～てみる","tip":"反復的な試みを強調するために、「～てはみる」と組み合わせる。","meaning":"結果がどうなるかを見るために何かを試すことを意味し、この文脈ではしばしば不確実性や無益さの感覚を伴う。","example":"画本を抜き出してはみる、そして開けてはみるのだが","jlpt":"N4"},{"jlpt":"N3","tip":"これは強い心理的強制または自分の感情を満たす必要性を表現する。","meaning":"「～なくては気が済まない」または「～しないと落ち着かない」という意味のフレーズ。","example":"一度バラバラとやってみなくては気が済まないのだ。","pattern":"～なくては気が済まない"},{"jlpt":"N3","example":"あまりに尋常な周囲を見廻すときのあの変にそぐわない気持を、私は以前には好んで味わっていたものであった。","meaning":"過去の習慣や、かつて存在した状態を回想する際に用いられる（しばしば懐かしさを伴う）。","tip":"英語では「used to do」や「would often do」と訳されることが多いです。","pattern":"～たものであった / ～たものだ"},{"pattern":"～たら（どう）","jlpt":"N3","example":"一度この檸檬で試してみたら。","tip":"文が「～たら」で終わる場合、それは提案や「もし～だったら」という状況を表すことが多いです。","meaning":"「～たらどうですか」を短縮したもので、「～したらどうか」あるいは「～してみようか」というような、くだけた表現や内省的な表現。"},{"jlpt":"N2","example":"城壁の頂きに恐る恐る檸檬を据えつけた。","meaning":"動詞のマス形に接続し、何かをしっかりと、あるいは完全に終える、固定する、取り付ける、という意味になる複合動詞の構造です。","tip":"この接尾辞は、しばしば動作に「確実さ」や「強さ」の感覚を加えます。","pattern":"～つける (stem + つける)"},{"tip":"仮定的な感情の度合いを強調するために、「どんなに」を「かな」や「だろう」と組み合わせてください。","meaning":"感嘆詞で、「どんなに～だろう！」という意味で、強い感情や想像を表すのに用いられます。","example":"大爆発をするのだったらどんなにおもしろいだろう。","jlpt":"N2","pattern":"どんなに ～だろう"}]]},"hana":{"simplified":[[{"meaning":"Called; named (used to specify a name)","example":"池の尾という町","pattern":"～という","tip":"Use this to introduce a specific name or title that the listener might not know.","jlpt":"N5"},{"example":"15センチぐらいあります","meaning":"Approximately; about (indicates an approximate amount or degree)","pattern":"～ぐらい/くらい","jlpt":"N5","tip":"Place this directly after a number or duration to soften the measurement."},{"jlpt":"N5","tip":"For い-adjectives, drop the final い and add くて to join descriptions.","example":"細くて長い","meaning":"And (connective form for adjectives/verbs)","pattern":"～て/～くて"},{"pattern":"～のようだ/～のように","example":"ソーセージのようです","meaning":"To be like; similar to; looks like","jlpt":"N4","tip":"Use this to create a simile or compare the appearance of two things."},{"jlpt":"N4","tip":"In this text, it emphasizes the accidental and unfortunate nature of the nose falling into the food.","meaning":"To do something completely, or to do something accidentally/regrettably","example":"鼻がご飯の中に入ってしまいます","pattern":"～てしまう"},{"example":"鼻を持ってもらいます","meaning":"To have someone do something (benefactive)","pattern":"～てもらう","tip":"This indicates the speaker received a favor or service from someone else.","jlpt":"N4"},{"meaning":"Because; since (indicates a reason)","example":"お坊さんだから","pattern":"～から/～だから","tip":"Use だから after nouns or な-adjectives to provide a justification.","jlpt":"N4"},{"jlpt":"N4","tip":"This allows you to treat a whole action as the subject or object of a sentence.","meaning":"Nominalizer (turning a verb into a Noun)","example":"気にするのは恥ずかしい","pattern":"～のは/～のが"},{"tip":"This is a strong way to emphasize that something applies to absolutely everyone.","jlpt":"N4","example":"知らない人はいません","meaning":"Double negative meaning 'everyone' (there is no one who does not...)","pattern":"～ない～はいない"},{"meaning":"State of being; continuous action","example":"50歳を過ぎています","pattern":"～ている","jlpt":"N4","tip":"When used with a verb expressing a change (like 過ぎる), it describes the current resulting state."}],[{"jlpt":"N5","pattern":"～へ (particle)","tip":"Pronounced as 'え' when acting as a particle, though written as 'へ'.","meaning":"Indicates the direction of movement (towards)","example":"京都へ行きました"},{"jlpt":"N5","tip":"For i-adjectives, replace the final い with く. For example, 短い becomes 短く.","pattern":"～く (adverbial form)","meaning":"Grammar used to change an I-adjective into an adverb to modify a verb (to do [adjective]ly)","example":"鼻を短く見せる方法"},{"jlpt":"N4","pattern":"～のまま","tip":"Use it when something stays in a certain state longer than expected or without changing.","meaning":"Indicates that a situation remains unchanged; staying as it is","example":"鼻はずっと15センチのままでした"},{"jlpt":"N4","tip":"Always end the list with the verb する. It implies there might be other actions not mentioned.","pattern":"～たり～たりする","meaning":"Listing multiple actions or states in no particular order (doing A, doing B, etc.)","example":"顔の向きを変えたり、手で顔を触ったりしました"},{"meaning":"A way or method of doing something","example":"鼻を短くする方法","jlpt":"N4","tip":"Attach it to the stem of a verb (Masu-form minus ます). It turns the verb into a Noun.","pattern":"～方 (かた)"},{"tip":"In this text, 見せる is the causative of 見る, meaning 'to make it look like' or 'to show'.","pattern":"～せる (causative)","jlpt":"N4","example":"鼻を短く見せる方法","meaning":"The causative form, indicating making someone do something or letting something happen"},{"example":"やってみることにしました","meaning":"To try doing something to see what it's like or what the result is","pattern":"～てみる","tip":"Literal meaning is 'to do and see'. It is very common in daily conversation when attempting something new.","jlpt":"N4"},{"meaning":"To decide to do something (expresses a personal decision)","example":"やってみることにしました","jlpt":"N4","pattern":"～ことにする","tip":"Use ～ことにした for a decision you just made, and ～ことにしている for a long-term habit or rule."},{"example":"お医者さんに「鼻を短くする方法」を聞いてきました","meaning":"To go do an action and then return to the current location / An action starting and continuing toward the present","tip":"In this context, it means the disciple went to Kyoto, asked the doctor, and brought the information back.","pattern":"～てくる","jlpt":"N4"},{"example":"そんなことはしたくない","meaning":"Used to express the speaker's desire to (or not to) do an action","pattern":"～たい / ～たくない","tip":"Only use this for your own desires. Use ～たがる for the desires of others.","jlpt":"N4"}],[{"jlpt":"N5","pattern":"～です","tip":"Used at the end of a sentence to make it polite. For nouns and adjectives.","meaning":"Polite copula/to be","example":"方法は簡単です。"},{"pattern":"～て / ～で","jlpt":"N5","tip":"Connects multiple verbs in a chronological sequence (doing A, then B).","meaning":"Te-form for connecting actions or giving instructions","example":"鼻を入れて"},{"jlpt":"N5","pattern":"～ました","tip":"This is the polite past tense form of verbs ending in ～ます.","example":"鼻を入れました。","meaning":"Polite past tense verb ending"},{"example":"全然痛くありません。","meaning":"Negative form of I-adjectives or polite negative of verbs","jlpt":"N5","pattern":"～くありません / ～ません","tip":"Used with an adverb like 全然 to express a complete lack of something."},{"example":"赤くなりました。","meaning":"To become / change into a state","pattern":"～くなる / ～になる (なる)","jlpt":"N5","tip":"Use ～くなる for adjectives and ～になる for nouns and Na-adjectives."},{"example":"踏んでください","meaning":"Please do (polite request)","pattern":"～てください (ください)","jlpt":"N5","tip":"Formed by adding ください to the Te-form of the verb."},{"jlpt":"N4","pattern":"～くらい / ～ぐらい","tip":"Used here to compare the length of the nose to that of a normal person.","example":"鼻と同じくらい短く","meaning":"About/approximately the same level or amount"},{"tip":"Indicates that when one action happens, another occurs as a result.","pattern":"～と (conditional)","jlpt":"N4","meaning":"If/When (natural consequence or conditional)","example":"少し踏むと"},{"example":"踏んでもらいます。","meaning":"To have someone do something for you (benefactive)","tip":"Expresses gratitude or the fact that someone performed a service for the speaker.","pattern":"～てもらう","jlpt":"N4"},{"tip":"Often used in \"adversative passive\" where the subject is bothered by someone else's action.","jlpt":"N4","pattern":"～られる (受身)","example":"鼻を踏まれても","meaning":"Passive form (being done to)"},{"meaning":"Because (explaining a reason)","example":"短くなっていたからです。","pattern":"～から (reason)","jlpt":"N4","tip":"When used at the end of a sentence with です, it provides the reason for the previous statement."},{"tip":"In this context, it shows the result of a change that has already occurred.","jlpt":"N4","pattern":"～ている / ～ていた","meaning":"Resultant state or ongoing action in the past","example":"短くなっていた"}],[{"meaning":"Past tense of the copula (it was / there was)","example":"昔の15センチの長い鼻でした。","pattern":"～でした","jlpt":"N5","tip":"Use this to talk about states or identities in the past politely."},{"pattern":"動詞（辞書形）＋名詞","jlpt":"N5","tip":"In Japanese, the modifying Clause always comes before the Noun.","meaning":"Using a verb to modify a Noun (The person who comes to the temple)","example":"お寺に来る人"},{"meaning":"When / At the time of... (used with adjectives and verbs)","example":"鼻が長かった時","jlpt":"N5","pattern":"～時","tip":"When using an い-adjective, just attach it directly in its dictionary or past form."},{"example":"今のほうがみんな遠慮なく笑っているのです。","meaning":"Comparison between two things (A is more... than B)","tip":"Focus on the word before ほうが to identify which side is \"more\" or \"better.\"","pattern":"～ほうが～より","jlpt":"N5"},{"jlpt":"N4","pattern":"～ようになる/ようになります","tip":"This often indicates a transition from a state of 'not doing' to 'doing.'","example":"笑うようになります。","meaning":"To reach a point where one does something; a change in behavior or situation."},{"tip":"When used with time, it signifies that after that period passed, a new situation was noticed.","jlpt":"N4","pattern":"～と","example":"二、三日すると","meaning":"Natural consequence or 'if/when' (as soon as X happens, Y follows)肢"},{"meaning":"Nominalization (turning a verb or Clause into a Noun phrase)","example":"鼻が短くなったこと","pattern":"～こと","jlpt":"N4","tip":"Use this when you want to treat an entire action or event as the object of a sentence."},{"jlpt":"N4","pattern":"～（ら）れる / ～（ら）れません","tip":"For 五段 verbs, change the final 'u' sound to 'e' and add る.","example":"眠れませんでした。","meaning":"Potential form (could not / was not able to)"},{"meaning":"About the same level as... / to the same extent as...","example":"鼻が短くなった時と同じくらい","tip":"Use this to compare the degree or intensity of two different situations.","jlpt":"N3","pattern":"～と同じくらい"},{"tip":"This expresses the speaker's guess. だろう is less formal than でしょう.","pattern":"～だろう / ～でしょう","jlpt":"N3","meaning":"Probably / I suppose (expressing a conjecture or guess)","example":"私を笑う人はいないだろう"}]],"intermediate":[[{"pattern":"～は～ない/いる","jlpt":"N5","tip":"Think of it as setting the stage for the negative or positive existence that follows.","meaning":"The topic marker, indicating what the sentence is about.","example":"知らない人はいない。"},{"meaning":"Approximate amount, time, or length.","example":"十五センチくらいあって","pattern":"～くらい/ぐらい","jlpt":"N5","tip":"Use it for general estimates where precise numbers aren't necessary."},{"example":"十五センチくらいあって","meaning":"The 'Te-form' of a verb used to connect sentences or list actions.","tip":"This is the basic 'and' for connecting ideas in Japanese.","jlpt":"N5","pattern":"～て (て形)"},{"jlpt":"N4","pattern":"～のような / ～のように","tip":"Use this when you want to say something is 'like' or 'similar to' something else.","meaning":"Used to describe something by comparing it to something else (simile).","example":"ソーセージのようなものが"},{"example":"持ち上げさせていた。","meaning":"Causing or allowing someone to do an action.","tip":"In this context, it shows the monk forcing his disciple to help him.","pattern":"～させる (使役形)","jlpt":"N4"},{"meaning":"Indicates a reason or cause.","example":"恥ずかしいと思ったからだ。","jlpt":"N4","pattern":"～からだ / ～から","tip":"When placed at the end of a sentence with a Noun or adjective, it explains 'the reason is...'"},{"pattern":"～べき/べきだ","jlpt":"N3","tip":"It carries a strong sense of moral or social duty.","meaning":"Indicates something that should be done or is expected.","example":"一番に考えるべきお坊さん"},{"jlpt":"N3","pattern":"～をしている","tip":"Commonly used for physical traits or facial expressions (e.g., blue eyes, a sad face).","meaning":"To exhibit a certain appearance, condition, or expression.","example":"気にしていないような顔をしている。"},{"pattern":"～にとって","jlpt":"N3","tip":"Useful for expressing an opinion or effect relative to a specific person or group. provincial.","meaning":"From the standpoint of... or for...","example":"弟子にとっても、内供にとっても"},{"tip":"Always use this when assigning blame or noting a negative cause.","jlpt":"N3","pattern":"～のせいで / ～のせいだ","example":"鼻のせいで傷つく","meaning":"Because of... (used for negative results)."},{"example":"知らない人はいない。","meaning":"Double negative used to emphasize that 'everyone knows'.","tip":"This is a sophisticated way to express a universal truth.","jlpt":"N2","pattern":"～ない人はいない / ～ないものはない"},{"pattern":"～から～にいたるまで (から～まで)","jlpt":"N2","tip":"While 'made' is N5, the usage here spanning a whole life stage is a more advanced structural nuance.","meaning":"From... until... (emphasizing the duration or continuous state).","example":"若いお坊さんだった昔から、偉い立場になった今まで"}],[{"pattern":"～を","jlpt":"N5","tip":"Always follows the Noun that is being acted upon by the verb.","meaning":"Object marker particle indicating the direct object of a verb.","example":"方法を試した。"},{"example":"鏡の前で色々な角度から顔を見て","jlpt":"N5","pattern":"～て (て形)","meaning":"The conjunctive form of a verb used to connect sentences or indicate a sequence of actions.","tip":"Think of it as the 'and' that joins actions together in chronological order."},{"example":"京都へ行った弟子","tip":"Pronounced as 'e', it emphasizes the direction rather than the specific arrival point.","meaning":"Directional particle indicating the destination or direction of movement.","jlpt":"N5","pattern":"～へ"},{"pattern":"～たり～たりする","jlpt":"N4","meaning":"Listing actions or states as examples among others, implying the list is not exhaustive.","tip":"Always ends with a form of the verb 'suru'. Use it to say 'doing things like A and B'.","example":"顔の向きを変えたり、手で頬を押さえたりして"},{"example":"治そうと、色々な方法を試した。","meaning":"The volitional form followed by 'to' to express an intention, attempt, or decision to do something.","tip":"Commonly used for 'trying to' or 'about to' perform an action.","pattern":"～ようとする","jlpt":"N4"},{"pattern":"～かどうか (～か)","jlpt":"N4","tip":"In this text, the 'douka' is omitted, which is common when the verb implies checking a possibility.","meaning":"Used to embed a yes/no question into a sentence, meaning 'whether or not'.","example":"鼻が短く見えないか試した。"},{"example":"煮て飲んでみたり、塗ってみたりした。","meaning":"To try doing something to see what it is like or what the result will be.","tip":"Focuses on the 'attempting' or 'experimenting' aspect of an action.","pattern":"～てみる","jlpt":"N4"},{"example":"十五センチの長さのまま","meaning":"Indicates that a state or condition remains unchanged or continues as it is.","tip":"Used when something stays in a certain condition, often unexpectedly.","jlpt":"N3","pattern":"～まま"},{"pattern":"～なんか","jlpt":"N3","meaning":"A particle used to express belittlement, humility, or to dismiss something as unimportant.","tip":"In this context, it shows the character is pretending that his nose is not worth worrying about.","example":"鼻なんか気にしていないという態度"},{"example":"熱心に勧めるので、とうとうその方法を試すことにした。","jlpt":"N3","pattern":"～ことにする","meaning":"Used to express a decision made by the speaker or subject of the sentence.","tip":"Contrast this with 'koto ni naru', which implies a decision made by external circumstances."}],[{"tip":"Indicates the direct object of a verb. Focus on the action being performed on a Noun.","jlpt":"N5","example":"鼻を熱いお湯の中に入れた。","meaning":"Object marker particle","pattern":"～を"},{"jlpt":"N5","tip":"Used to introduce a topic or contrast the current subject with another potential subject.","example":"鼻は赤く茹で上がっていた。","pattern":"～は","meaning":"Topic marker or contrast particle"},{"meaning":"The Te-form connects verbs to show a sequence of actions.","pattern":"～て/で（接続）","example":"熱いお湯で茹でて","jlpt":"N5","tip":"It functions like 'and' in English to link actions in chronological order."},{"jlpt":"N4","tip":"Focuses on the speaker or subject receiving the benefit of another person's action.","meaning":"To receive a favor or have someone do something for you.","pattern":"～てもらう/でいただく","example":"人に足で踏んでもらう"},{"jlpt":"N5","tip":"Used for making polite requests. Combine the Te-form of a verb with ください.","pattern":"～てください","meaning":"Polite request or command.","example":"これを踏んでください"},{"pattern":"～ながら","meaning":"To do something while simultaneously doing another action.","example":"鼻を踏まれながら","jlpt":"N4","tip":"Attached to the stem of a verb. The action after ながら is the main focus."},{"meaning":"Despite; although; even though.","pattern":"～のに","example":"鼻を踏まれているのに","jlpt":"N4","tip":"Used to express contrast or an unexpected result based on the first part of the sentence."},{"example":"鼻を踏まれているのに","meaning":"Passive voice (being done to).","pattern":"～られる/れる","jlpt":"N4","tip":"The subject is the receiver of the action. Often used when the subject is negatively affected (adversative passive)."},{"jlpt":"N4","tip":"In this context, it indicates that doing the first action led to the discovery of the second event.","example":"しばらく踏んでいると","meaning":"If; when; whenever. Expresses a natural consequence or a discovery.","pattern":"～と（条件）"},{"example":"気持ちがいいくらいだった。","pattern":"～くらい/ぐらい","meaning":"To the extent that; so much so that.","tip":"Used to describe the level or intensity of a state by providing an example.","jlpt":"N3"},{"example":"鳥の毛を抜いた後のような","pattern":"～のような/ように","meaning":"Like; similar to. Used for comparisons or resemblances.","jlpt":"N3","tip":"Use ような before nouns and ように before verbs/adjectives to make figurative comparisons."},{"tip":"Often added to verb stems to emphasize that the movement or action is finished completely.","jlpt":"N3","pattern":"～上がる","meaning":"Completion of an action or reaching a final state.","example":"茹で上がっていた。"},{"jlpt":"N4","tip":"Attached to adjective stems or verb stems to describe an impression or appearance.","meaning":"Looks like; seems like. Based on visual appearance.","pattern":"～そう（外見）","example":"満足そうだった。"},{"example":"笑わないだろう","meaning":"Probably; right?; I think. Expresses conjecture.","pattern":"～だろう/でしょう","jlpt":"N5","tip":"Used when the speaker is making a guess or expressing their opinion with some uncertainty."},{"tip":"A common way to provide an explanation or definition of the preceding Noun.","jlpt":"N3","meaning":"Used to define, identify, or introduce a topic called 'X'.","pattern":"～というのは/というもの","example":"方法というの（は）"}],[{"tip":"Remove ます and attach に. It only works with verbs of movement.","pattern":"V(ます) + に (行く/来る)","jlpt":"N5","example":"お寺の用事でお経を読みに来た","meaning":"Indicates the purpose of movement (going/coming to do something)"},{"tip":"Use くなる for い-adjectives and になる for な-adjectives and nouns.","pattern":"～くなる / ～になる","jlpt":"N5","example":"鼻が短くなったことで","meaning":"To become or to change into a state"},{"meaning":"Indicates a continuing state result or an action currently in progress","example":"あごの下まで垂れ下がっていたのだ","tip":"In this text, it often describes the resulting state of the nose or a continuous attitude.","jlpt":"N4","pattern":"～ている / ～ていた"},{"tip":"Often used with 後悔 (regret) to express that the current situation is undesirable.","pattern":"～ばよかった","jlpt":"N4","example":"あんな短い鼻にしなければよかった","meaning":"Expresses regret; 'I should have (not) done...'"},{"meaning":"To start or begin doing something","example":"後悔し始めた","pattern":"V(ます) + 始める","jlpt":"N4","tip":"Focuses on the initiation of a continuous action or habit."},{"example":"お寺の用事でお経を読みに来たお侍さん","meaning":"Standard relative Clause; a verb modifying a Noun","tip":"Remember that the verb modifying the Noun must be in Dictionary form (dictionary or た form).","pattern":"連体修飾 (Relative Clause)","jlpt":"N4"},{"pattern":"～たびに","jlpt":"N3","tip":"Highlights that 'B' always happens whenever 'A' occurs. Not used for daily routines like brushing teeth.","example":"笑うたびに","meaning":"Every time something happens; whenever..."},{"jlpt":"N3","pattern":"～というような / ～のような","tip":"It adds a layer of indirectness or resemblance rather than a direct statement.","meaning":"Like; such as; used to give an example or describe a feeling/appearance","example":"おかしというような顔をして"},{"pattern":"～すら / ～ですら","jlpt":"N3","tip":"It is similar to さえ but often carries a more formal or literary nuance.","example":"もう一度その人を不幸な状態に戻してみたいとすら思うのだ","meaning":"Even; used to emphasize an extreme or unexpected case"},{"tip":"It connects the sentence to the context or explains the 'reason' behind a situation.","jlpt":"N3","pattern":"～のだ / ～んだ","example":"垂れ下がっていたのだ","meaning":"The explanatory 'no da'; provides background, explanation, or emphasis"},{"meaning":"To show signs of...; to feel/act as if... (external observation of emotion)","example":"遠慮なく面白がっているようだった","jlpt":"N3","pattern":"～がる / ～がっている","tip":"Usually used for the third person's feelings that are visible through their behavior."},{"tip":"In this context, it shows a feeling returning to the heart or a sensory experience.","pattern":"～てくる / ～てきた","jlpt":"N3","meaning":"Indicating a change that comes toward the speaker (physically or metaphorically)","example":"戻ってきた"},{"tip":"It expresses the speaker's subjective opinion about a future or uncertain event.","jlpt":"N3","pattern":"～だろう / ～でしょう","meaning":"Probably; I wonder; expressing a guess or conjecture","example":"私を笑う人はいないだろう"}]],"original":[[{"example":"鼻の長いのが不便だったからである。","meaning":"The subject marker 'ga' used in a subordinate Clause (modifying a Noun).","tip":"In relative clauses, が often changes to の, but here it marks the subject of the descriptive phrase 'long nose'.","pattern":"～が～（名詞）","jlpt":"N5"},{"jlpt":"N5","pattern":"～の（名詞化）","tip":"Use this when you want to treat an entire action or state as a Noun, like 'the act of...' or 'the fact that...'.","meaning":"The nominalizing particle 'no' which turns a verb or sentence into a Noun.","example":"鼻と云う語が出て来るの"},{"pattern":"～のである/～のだ","jlpt":"N4","tip":"This makes the sentence feel like an explanation or a statement of fact rather than just a simple observation.","meaning":"The explanatory 'noda' or 'nodesu' used to provide background, reason, or emphasis.","example":"顔のまん中からぶら下っているのである。"},{"tip":"Often used in Japanese to express something happening to someone, even if it's an 'unpleasant' passive (suffering passive).","pattern":"～られる（受身）","jlpt":"N4","example":"弟子にとっても、持上げられている内供にとっても","meaning":"Passive voice indicating that the subject is receiving the action."},{"meaning":"Potential form of the verb, indicating ability or possibility.","example":"独りでは食えない。","jlpt":"N4","pattern":"～える（可能形）","tip":"For Group 2 verbs like 食べる (to eat), the 'ru' is replaced with 'rareru' or colloquially 'reru'. Here 'ueru' is the potential of 'uu' (classic form) or 'eru' for 'eru'."},{"jlpt":"N3","pattern":"～間中（～あいたじゅう）","tip":"Adding 'juu' emphasizes that the action continues without stopping through the whole period.","meaning":"Throughout the entire duration of a time or state.","example":"飯を食う間中"},{"jlpt":"N3","pattern":"～ような顔をする","tip":"This describes an outward facial expression or attitude regardless of the person's true feelings.","meaning":"Appearing in a certain way; behaving as if a certain state exists.","example":"気にならないような顔をしてすましている。"},{"meaning":"Indicates an action or state that started in the past and has continued up until the present.","example":"鼻を苦に病んで来た。","jlpt":"N3","pattern":"～てくる","tip":"When used with emotions or physical changes, it shows how the state has developed over time."},{"pattern":"～さえ","jlpt":"N3","tip":"It replaces or follows particles like が or を to suggest that if even X is true, then other things must be true as well.","meaning":"Used to emphasize that even something extreme or unexpected is included.","example":"あの鼻だから出家したのだろうと批評する者さえあった。"},{"jlpt":"N3","pattern":"～ばかりではない/～ばかりでなく","tip":"This is slightly more formal than 'dake janai' and is used to expand the scope of a statement.","meaning":"Not only... but also...","example":"鼻の心配をするのが悪いと思ったからばかりではない。"},{"pattern":"～にとって（は）","jlpt":"N3","tip":"This is used to express an opinion or an effect relative to a specific person or group.","meaning":"From the standpoint of...; for...; as far as ... is concerned.","example":"弟子にとっても、持上げられている内供にとっても"},{"example":"左右されるためには、余りにデリケイトに出来ていたのである。","meaning":"Expressions of purpose; 'In order to...' or 'For the purpose of...'.","tip":"When followed by a Noun, use 'no tame ni'. When followed by a verb (Dictionary form), it marks the objective.","jlpt":"N3","pattern":"～（辞書形）ために"},{"meaning":"More than anything; above all else.","example":"鼻と云う語が出て来るのを何よりも惧れていた。","jlpt":"N2","pattern":"何よりも（なによりも）","tip":"A superlative expression used to emphasize that the target is the highest degree of a certain quality or emotion."}],[{"tip":"In relative clauses (like 鼻が短く見える), it marks the subject of the subordinate verb.","meaning":"Indicates a subject, often for stative verbs or potential forms.","jlpt":"N5","pattern":"～が","example":"鼻が短く見えた事は、これまでにただの一度もない。"},{"example":"鏡を箱へしまいながら","tip":"Attach the stem form of the verb. The main action comes second.","meaning":"Indicates two actions happening simultaneously by the same person.","pattern":"～ながら","jlpt":"N4"},{"example":"煎じて飲んで見た事もある。","meaning":"To try doing something to see what happens.","tip":"Uses the て-form. Even if the result is known, it implies an experimental attempt.","jlpt":"N4","pattern":"～てみる (～て見た)"},{"tip":"Use this when you want to treat a whole sentence as a Noun.","meaning":"Refers to the act or fact of doing something, used to nominalize phrases.","jlpt":"N4","pattern":"～こと (～事)","example":"鼻を短くする方法を教わって来た。"},{"example":"鼻が短く見えるような気さえした。","tip":"Often replaces particles like が or を. It emphasizes an extreme example.","meaning":"Used to emphasize something by saying 'even' or 'to the extent of'.","pattern":"～さえ","jlpt":"N3"},{"example":"苦心すればするほど、かえって長く見える。","tip":"Repeat the same verb: first in conditional form (ば), then in Dictionary form before ほど.","meaning":"Indicates that as one thing changes, another thing changes in proportion (the more... the more...).","pattern":"～ば～ほど","jlpt":"N3"},{"example":"内供の策略がわからない筈はない。","tip":"はずはない is a strong negation, meaning 'there is no expectation/possibility that...'.","meaning":"Expectation or conviction that something is definitely true or must be the case.","pattern":"～はずだ (～筈はない)","jlpt":"N3"},{"pattern":"～だけに","jlpt":"N3","tip":"Used when a result happens naturally or to an even greater degree because of a specific reason.","meaning":"Precisely because; because of the special circumstances of...","example":"見慣れているだけに、有れども無きが如くである。"},{"example":"鼻などは気にかけないと云う風をして","pattern":"～ふうをする (～風をして)","jlpt":"N3","meaning":"To act like; to behave in a way that suggests...","tip":"Describes an outward appearance or pretense regardless of internal feelings."},{"tip":"Used for things that are so obvious or simple that the action is a waste of effort.","meaning":"It is not necessary to...; it goes without saying that...","pattern":"～までもない","jlpt":"N2","example":"わざわざここに云うまでもない。"},{"jlpt":"N2","pattern":"～にしたがって (～につき・～に従って)","meaning":"As... then...; in proportion to; along with.","tip":"Indicates a gradual change that happens in step with another change.","example":"度重なるに従って、内供の心は次第にまた不快になった。"},{"pattern":"～がごとく (～が如く)","jlpt":"N1","tip":"This is a literary/archaic version of ように. It is common in older literature like this story.","meaning":"Just like; as if (Classical/Formal style).","example":"有れども無きが如くである。"}],[{"tip":"Think of it as 'by means of' or 'using'. In this case, 'with' hot water.","pattern":"～で (Means)","jlpt":"N5","meaning":"Indicates the means, method, or tool used for an action.","example":"湯で鼻を茹でて"},{"example":"沸かしている","meaning":"Indicates a continuous action or a current state.","tip":"Standard present progressive or resultative state. Used here for the stove currently boiling water.","jlpt":"N5","pattern":"～ている"},{"jlpt":"N4","pattern":"～てくる / ～てきた","tip":"Here it shows the disciple fetched the water and brought it back to the current location.","example":"湯屋から汲んで来た","meaning":"Indicates an action that starts elsewhere and moves toward the speaker, or completing a task then returning."},{"tip":"The person being made to do the action is marked with the particle に.","jlpt":"N4","pattern":"～せる / ～させる (Causative)","meaning":"The causative form, used to indicate making or letting someone do something.","example":"人に踏ませる"},{"example":"熱い湯を入れる事にした","meaning":"Indicates a decision made by the subject or a choice of action.","jlpt":"N4","pattern":"～ことにする","tip":"Focuses on the result of a conscious decision or plan."},{"meaning":"Polite negative form of the copula or verbs, used primarily in historical or formal contexts.","example":"痛うはござらぬかな","tip":"This is the archaic version of ありません/ございません. The う sound in 痛う is a euphonic change (onbin) characteristic of polite speech.","jlpt":"N4","pattern":"～ござらぬ (～ございません)"},{"meaning":"Indicates the start or beginning of an action.","example":"踏みはじめた / 出来はじめた","pattern":"～はじめる (Stem + はじめる)","jlpt":"N4","tip":"Attach this to the pre-Masu-stem of any verb to say 'start doing...'."},{"example":"踏まれているので","meaning":"The passive voice used to describe an action being done to the subject.","tip":"The 'indirect' or 'suffering' passive is common in Japanese literature to show how an event affects someone.","pattern":"～れる / ～られる (Passive)","jlpt":"N4"},{"example":"誰も哂うものはないにちがいない","meaning":"Used to express a strong certainty or a logical deduction (must be; without a doubt).","tip":"Use this when you have specific evidence or a strong reason to believe something is true.","jlpt":"N3","pattern":"～にちがいない"},{"pattern":"～のように / ～のような","jlpt":"N3","tip":"Use のように to modify verbs/adjectives and のような to modify nouns.","meaning":"Used to provide an example or show a likeness/resemblance.","example":"物品のように取扱う"},{"example":"意味を示そうとした","meaning":"Indicates an attempt to do something or an intention to perform an action.","pattern":"～ようとする (Volitional + とする)","jlpt":"N3","tip":"It often implies the action was attempted but perhaps not completed or was interrupted."},{"example":"茹った時分でござろう","meaning":"The volitional form of the copula, expressing a guess, conjecture, or probability.","tip":"でござろう is the highly formal/archaic version of でしょう used by the monk.","jlpt":"N3","pattern":"～だろう / ～でしょう (～でござろう)"},{"meaning":"Used to express a double negative: it's not that..., it doesn't mean that...","example":"親切がわからない訳ではない","pattern":"～わけではない / ～わけでもない","jlpt":"N2","tip":"Often used to partially disagree or clarify a nuance while acknowledging part of the situation."},{"tip":"In this context (するなり), it means leaving things to progress exactly as the other person does it.","jlpt":"N1","pattern":"～なり (～なりに / ～なりの)","meaning":"Doing exactly as...; in accordance with...; following a certain state.","example":"弟子の僧のするなりに任せて置いた"}],[{"tip":"When used in the middle of a sentence followed by words like 不安 (anxiety) or 疑問 (doubt), it marks an embedded question.","jlpt":"N5","meaning":"The question particle used to indicate a question or doubt within a sentence.","example":"鼻がまた長くなりはしないかと云う不安があった。","pattern":"～か"},{"jlpt":"N4","tip":"Replace the particle on the Noun with さえ and use the conditional form of the verb at the end.","meaning":"Used to emphasize a single necessary condition; \"if only\" or \"as long as\".","example":"暇さえあれば手を出して","pattern":"～さえ～ば"},{"jlpt":"N4","tip":"Always written in hiragana when used as a grammar helper. It implies a trial action.","example":"鼻の先にさわって見た。","meaning":"To try doing something to see what it is like or what the result will be.","pattern":"～てみる"},{"pattern":"～と見える","example":"下を向いて可笑しさをこらえていたが、とうとうこらえ兼ねたと見えて","meaning":"It appears that... / It looks like... (based on objective observation).","jlpt":"N4","tip":"Similar to ～ようだ but more formal and based on visual evidence. Often used as ～と見えて to link sentences."},{"example":"内供が後さえ向けば、すぐにくすくす笑い出したのは","meaning":"To start doing something. (The beginning of an action).","pattern":"～出す (～だす)","tip":"Attach to the stem (pre-ます form) of a verb. Usually implies a sudden or outward start.","jlpt":"N4"},{"pattern":"～なぞ (など)","meaning":"Used to show examples or to belittle something; \"things like,\" \"the likes of.\"","example":"中童子なぞは","tip":"なぞ is a slightly more literary or old-fashioned version of など. It carries a nuance of \"low importance.\"","jlpt":"N3"},{"example":"哂う原因は、そこにあるのにちがいない。","meaning":"Must be... / there is no doubt that... (Strong conviction).","pattern":"～にちがいない","tip":"Use it when you are almost 100% certain of your conclusion based on logic or evidence.","jlpt":"N3"},{"jlpt":"N3","tip":"Useful for describing vague feelings or atmospheres. Often pairs with 違う (different) or 寂しい (lonely).","pattern":"どことなく","example":"鼻の長かった昔とは、哂うのにどことなく容子がちがう。","meaning":"Somehow / for some reason (used when the speaker cannot pinpoint the exact cause)."},{"tip":"Indicates that a situation has reached its limit or that there is no other option/alternative.","jlpt":"N3","meaning":"That’s the end of it / nothing more can be done.","example":"それまでである。","pattern":"～までだ / ～までである"},{"jlpt":"N3","tip":"Used for feelings, actions, or questions directed at a specific person or topic.","pattern":"～に対して","meaning":"Towards... / in regard to... (Indicating the object of an action or feeling).","example":"消極的ではあるが、ある敵意をその人に対して抱くような事になる。"},{"pattern":"～にほかならない","example":"この傍観者の利己主義をそれとなく感づいたからにほかならない。","meaning":"Precisely because... / nothing other than... (Strongly identifying the cause).","jlpt":"N2","tip":"A formal/written way to say \"definitely because of X.\" It eliminates all other possibilities."},{"meaning":"Honorific/Passive form used here to show respect (Sonkeigo) or potential. In this context, it is a respectful form.","example":"内供は法慳貪の罪を受けられるぞ","pattern":"～られる (尊敬)","tip":"While often the passive or potential form, in literary texts, ～られる is frequently used as a mid-level respect form for noble/religious figures.","jlpt":"N2"},{"tip":"Attached to the Dictionary form (for Group 1 verbs). In this text, it is used by a character for \"You won't get hit, will you?\" or \"Don't get hit!\"","jlpt":"N2","pattern":"～まい","example":"鼻を打たれまい。","meaning":"Will probably not... / intend not to... (Negative volitional or negative conjecture)."},{"meaning":"On the contrary / instead (unexpectedly).","example":"鼻の短くなったのが、かえって恨めしくなった。","pattern":"かえって","jlpt":"N2","tip":"Used when a result is the opposite of what was intended or expected."},{"pattern":"～ぬ / ～ず","meaning":"Negative form (Classical/Formal version of ～ない).","example":"無理に短うしたで、病が起ったのかも知れぬ。","tip":"知れぬ is a literary version of 知れない. It adds a traditional or intellectual tone to the speech.","jlpt":"N1"}]]},"matsu":{"simplified":[[{"meaning":"To go somewhere for the purpose of doing something.","example":"人を迎えに行きます","tip":"The 'ni' particle indicates the goal or purpose of the movement.","jlpt":"N4","pattern":"Masu-stem + に行く"},{"pattern":"Plain past + 後 (あと)","jlpt":"N4","meaning":"After doing something; indicates a sequential relationship.","tip":"Always use the past tense 'ta' form before 'ato', even if the overall sentence describes a future or habitual action.","example":"買い物をした後"},{"example":"電車が来るのをずっと待ちます","tip":"Use this when you want to treat an action as a thing, common with verbs like 'see', 'hear', or 'wait for'.","meaning":"Turning a verb/Clause into a Noun phrase to make it the object of a sentence.","jlpt":"N4","pattern":"Dictionary form + の"},{"pattern":"Dictionary form + と","jlpt":"N4","meaning":"A natural, inevitable, or habitual consequence. Whenever A happens, B follows.","example":"電車が来ると","tip":"This specific 'to' implies that the second action happens almost automatically or predictably every time."},{"meaning":"Appearing to be; looking like. Used to describe the likeness or appearance of something.","tip":"This is used for metaphors or when providing examples based on visual assessment.","example":"怒っているような顔です","pattern":"Dictionary form + ような + Noun","jlpt":"N3"},{"tip":"Use this to emphasize that a condition or action persists while another action takes place.","example":"座ったまま","meaning":"State of remaining unchanged; doing something while keeping a previous state or condition.","pattern":"Plain past + まま","jlpt":"N3"},{"jlpt":"N3","pattern":"Dictionary form + のでしょうか","meaning":"An explanatory or polite way to ask a question or express a thought/wondering.","tip":"This is softer and more reflective than just asking 'ka'. It adds a sense of 'I wonder' or 'is it that case?'.","example":"誰を待っているのでしょうか"}],[{"tip":"While basic, it highlights a continuous habit or routine when used with time markers like 毎日 (every day).","example":"家で手伝いをしています","meaning":"Indicates an ongoing action or a current state/habit.","pattern":"Te-form + いる","jlpt":"N5"},{"meaning":"Indicates that an action or state has continued since a specific event happened.","example":"戦争が始まってから","tip":"This emphasizes the starting point of a sequence. Don't confuse it with the Noun + から meaning 'from'.","jlpt":"N4","pattern":"Te-form + から"},{"pattern":"Te-form + しまう","jlpt":"N4","tip":"In this context, it suggests a lack of control over the urge to wait or a sense of helplessness.","example":"待ってしまいます","meaning":"Expresses completing an action, or doing something unintentionally/regrettably."},{"meaning":"Expresses a possibility or a guess that something might happen (roughly 50% certainty).","tip":"This is often used for subjective guesses. In polite speech, use かもしれません.","example":"私と話すかもしれない","pattern":"Dictionary form + かもしれない","jlpt":"N4"},{"tip":"The の (or ん) adds an explanatory or inquisitive tone, making the question sound more reflective.","example":"待っているのでしょうか","meaning":"A polite way to ask a question with a nuance of curiosity or wondering.","pattern":"Dictionary form + のでしょうか","jlpt":"N3"},{"pattern":"Clause + Noun","jlpt":"N4","meaning":"The entire Clause before the Noun acts as an adjective to describe that Noun.","tip":"In Japanese, there are no relative pronouns like 'who' or 'which'; simply put the verb phrase directly before the Noun.","example":"苦しい毎日を変える、何か"},{"jlpt":"N3","pattern":"Dictionary form + ことしかできない","meaning":"Indicates that there is no other option or possibility but the one mentioned.","example":"待つことしかできません","tip":"しか must be followed by a negative verb. It emphasizes that the action is the only choice available."},{"pattern":"Te-form + も","jlpt":"N4","meaning":"Expresses 'no matter what' or 'even if'. Highlighting a condition that doesn't change the outcome.","tip":"When paired with question words like 何 (what) or どこ (where), it translates to 'no matter what/where'.","example":"他の人が何と言っても"}]],"intermediate":[[{"example":"人を迎えに行きます","meaning":"Going to a place with the purpose of doing something.","tip":"The に particle marks the purpose of movement, and the verb before it must be in its stem form.","jlpt":"N4","pattern":"Masu-stem + に行く"},{"example":"買い物を済ませた後","meaning":"After doing something or after a specific event.","tip":"Note that when using a verb, it must always be in the past tense even if the overall sentence refers to the future.","pattern":"Plain past + 後 (あと) / Noun + の後 (あと)","jlpt":"N4"},{"meaning":"Without doing something; a more formal/literary version of ～ないで.","example":"家には帰らず","pattern":"Masu-stem (negative) + ず","jlpt":"N3","tip":"This is often used to connect clauses. Remember that the irregular verb する becomes せず."},{"tip":"Unlike こと, の is often used for actions happening right before your eyes, like seeing, hearing, or waiting for something.","jlpt":"N4","pattern":"Dictionary form + の","example":"電車が着くのを待ちます","meaning":"Turning a verb or Clause into a Noun to make it the object of a sentence."},{"jlpt":"N3","pattern":"Dictionary form + たびに / Noun + のたびに","tip":"This emphasizes that every single instance of the action is followed by the same result. It cannot be used for everyday routine occurrences like 'every morning'.","meaning":"Every time something happens; whenever a certain action occurs.","example":"電車が着くたびに"},{"example":"怒っているような顔をして","meaning":"To look like or appear as if; used for comparisons or descriptions based on appearance.","tip":"Use this when something resembles something else or is an example of a certain state.","pattern":"Dictionary form + ような / Noun + のような","jlpt":"N4"},{"meaning":"Leaving something in a certain state; doing something while a previous state remains unchanged.","example":"ぼんやり座ったまま","jlpt":"N3","pattern":"Plain past + まま / Noun + のまま","tip":"It often implies that a state is continuing longer than expected or is being left as is."},{"meaning":"An embedded question within a sentence.","example":"誰を待っているのか","pattern":"Dictionary form + か (どうか)","jlpt":"N4","tip":"If an interrogative word (like who, what, or where) is used, simply use か. Without an interrogative, use かどうか (whether or not)."}],[{"jlpt":"N4","pattern":"Noun + ほど","tip":"Unlike くらい, ほど is often used to emphasize the extent or degree of something.","meaning":"Approximately/about a certain amount or degree","example":"十五分ほどのとろこにあります"},{"meaning":"Ever since a certain action or event took place","example":"戦争が始まってから","pattern":"Te-form + から","jlpt":"N4","tip":"This indicates that a state has continued uninterrupted since the starting point."},{"tip":"In this context, it suggests an habitual action the speaker cannot help but perform.","pattern":"Te-form + しまう","jlpt":"N4","example":"待ってしまいます","meaning":"To do something unintentionally or to end up in a certain state (often with regret)"},{"jlpt":"N4","pattern":"Dictionary form + かもしれない","tip":"It expresses a subjective guess with low certainty (around 50% or less).","meaning":"Perhaps; might; it is possible that...","example":"期待しているのかもしれません"},{"tip":"This focuses on a single action or state, excluding all other possibilities.","pattern":"Dictionary form + だけ","jlpt":"N4","example":"急いで帰っていくだけです","meaning":"Only; just; nothing but"},{"jlpt":"N3","pattern":"Dictionary form + わけではない","tip":"Used to partially deny a logical assumption or provide a nuanced clarification.","meaning":"It doesn't mean that; it's not the case that...","example":"待っているわけではありません"},{"meaning":"To look forward to something","example":"春が来るのを楽しみにしている","pattern":"Noun + を楽しみにする","jlpt":"N3","tip":"Use the particle を when you are the one looking forward to it as an active state."},{"jlpt":"N3","pattern":"Dictionary form + ような+ Noun","tip":"This is used for metaphors or to describe a Noun by giving an example of its qualities.","meaning":"Like; similar to; of the kind that...","example":"変えてくれるような何か"},{"example":"入ってくるたびに","meaning":"Every time; whenever something happens","tip":"Focuses on the repetition: whenever \"A\" happens, \"B\" always follows. Often used for highlight-worthy events.","jlpt":"N3","pattern":"Dictionary form + たびに"},{"meaning":"Can do nothing but; have no choice but to...","example":"待つことしかできないのです","pattern":"Dictionary form + ことしかできない","jlpt":"N3","tip":"The negative ending is required with しか to emphasize the limitation to a single option."},{"example":"待っていることほど、馬鹿げたことはない","meaning":"Nothing is more... than [A] (expressing [A] is the most...)","tip":"This is a superlative structure used to express that nothing reaches the level of the subject.","jlpt":"N3","pattern":"Noun + ほど + (negative adjective/verb) + ことはない"},{"jlpt":"N3","pattern":"Masu-stem + 続ける","tip":"This indicates a continuous or repeated action over a period of time.","meaning":"To continue doing something without stopping","example":"待ち続けています"},{"jlpt":"N2","pattern":"Volitional form + と (particle)","tip":"Often used with question words to mean \"no matter who/what/how.\" It expresses a strong determination.","meaning":"No matter what/who... (regardless of...)","example":"誰が何と言おうと"}]],"original":[[{"pattern":"Noun + の or Dictionary form + 帰り（に）","example":"買い物をして、その帰りには","meaning":"Indicates that an action takes place in the process of returning from somewhere","tip":"Commonly used with particles like 'ni' or 'wa' to set the timeframe of the detour.","jlpt":"N4"},{"meaning":"Expresses that something happens every time another thing occurs or repeats","tip":"Similar to 'tabi ni', but 'goto ni' is often used for regular intervals or occurrences.","jlpt":"N3","pattern":"Dictionary form + ごとに","example":"電車がホームに到着するごとに"},{"jlpt":"N4","tip":"Use this when making a subjective comparison based on visual appearance.","meaning":"Indicates a resemblance or appearance; to look like or act as if","example":"怒っているような顔をして","pattern":"Dictionary form + ような / Noun + のような"},{"jlpt":"N3","meaning":"Emphasizes that just one small action or thought is enough to trigger a strong reaction","tip":"Often used with verbs of feeling, thinking, or seeing to show intensity.","example":"考えただけでも","pattern":"Dictionary form + だけ（で）"},{"jlpt":"N4","meaning":"Functions as an adverb to describe the manner of an action by comparison","tip":"When used mid-sentence to describe a verb or adjective, it functions like the English word 'like'.","example":"冷水をかけられたように","pattern":"Dictionary form + ように / Noun + のように"},{"example":"人間でないかも知れない","pattern":"Dictionary form + かもしれない","jlpt":"N4","tip":"It suggests a 50/50 chance and is less certain than 'deshou'.","meaning":"Expresses a possibility or a guess that something might be true"},{"pattern":"Masu-stem + たくも＋ない/ない形 negative form","example":"言いたくもない挨拶","meaning":"Emphasizes a negative feeling or lack of desire toward an action","tip":"The 'mo' adds emphasis, suggesting 'not even' wanting to do it.","jlpt":"N3"},{"jlpt":"N3","tip":"Usually used with emotive verbs or adjectives to express extreme uncontrollable feelings.","meaning":"Cannot help but feel a certain way; an emotion or physical sensation is unbearable","example":"いやでいやでたまらなくなります","pattern":"Te-form + たまらない"},{"pattern":"Dictionary form + ものだ / もの（なの）だ","example":"一生を送るものなのでしょうか","tip":"It often carries a nuance of social norms, common sense, or a deep realization.","meaning":"Indicates a general truth, an essence of something, or how something should be","jlpt":"N3"},{"tip":"In negative contexts like 'nai kagiri', it translates closely to 'unless'.","meaning":"As long as; unless (sets a condition for the rest of the sentence to be true)","jlpt":"N2","pattern":"Dictionary form + 限り / Noun + である＋限り","example":"よほどの事でもない限り"},{"example":"お役に立ちたい気持なのです","pattern":"お + Masu-stem + に立つ","jlpt":"N3","meaning":"A humble way to express being of use or service to someone higher in status","tip":"This is the humble version of 'yaku ni tatsu'. Propriety and social distance are key here."}],[{"tip":"Often used with negative or pessimistic conclusions, emphasizing a sense of futility.","jlpt":"N1","meaning":"Even if / even though; used to express that even if an action is taken, the result will be useless or unchanged.","example":"外に出てみたところで","pattern":"Te-form + ところで"},{"jlpt":"N4","tip":"When a sentence ends with this, it often implies a hidden wish like 'I wish...' or 'What if...?'","meaning":"Expressing a wish, hope, or hypothetical situation ending abruptly.","example":"ひょいと現われたら！","pattern":"Plain past + ら"},{"meaning":"Something like; used to give an example or describe something in an indirect, illustrative way.","example":"きまってしまうのだというような","pattern":"Dictionary form + というような","jlpt":"N3","tip":"Use this to provide a representative example of a feeling, statement, or category."},{"jlpt":"N3","tip":"It describes a degree so extreme that it reaches the level of the action mentioned.","pattern":"Dictionary form + ほど","meaning":"To the extent that; used to indicate the degree or scale of a state.","example":"窒息するほどくるしくなります"},{"jlpt":"N4","tip":"In casual speech or literature, it functions similarly to 'youni' but feels slightly more colloquial or visual.","pattern":"Plain past + みたいに","meaning":"Like; similar to; used to describe something by comparing it to something else (metaphor).","example":"覗いたみたいに"},{"meaning":"Might; perhaps; used to express a possibility or the speaker's conjecture.","example":"女なのかも知れない","pattern":"Dictionary form + かも知れない","jlpt":"N4","tip":"The 'da' from 'na-adjectives' and nouns is dropped before this pattern."},{"meaning":"The thing called; as for the matter of; used to define or emphasize the topic.","example":"お役に立ちたいというのは嘘で","pattern":"Dictionary form + というのは","tip":"It is often used to define a term or provide an explanation for a specific statement.","jlpt":"N3"},{"jlpt":"N3","tip":"This is a shortened form of 'volitional + to omou' or 'volitional + to suru', focusing on the intent behind an action.","meaning":"Attempting to; in an effort to; expressing an intention to perform an action.","example":"空想を実現しようと","pattern":"Volitional + と"},{"example":"駅へお迎えに行っては","meaning":"Repeatedly doing an action; whenever one does... they always...","pattern":"Te-form + は","tip":"This highlights a repetitive or habitual action that occurs under certain conditions.","jlpt":"N3"},{"tip":"In this context, it implies keeping a memory or state of mind for the future.","jlpt":"N4","example":"覚えて置いて下さいませ","meaning":"Do something in advance or leave something in a certain state (applied here with polite 'mase').","pattern":"Te-form + おく"},{"tip":"This is a very formal humble form, common in refined speech or classical-leaning modern literature.","jlpt":"N3","meaning":"Humble expression (Kenjougo) used to refer to the speaker's own actions toward someone respected.","example":"お教え申しません","pattern":"O + Masu-stem + 申す"}]]},"asa":{"simplified":[[{"example":"遊ぶことが一番好きです。","meaning":"動詞 (verb) を名詞化して (nominalizes) 動作 (an action) を 「物 (thing)」 や 「活動 (activity)」 に変えます (to turn into).","jlpt":"N5","tip":"これは、動詞に 「～すること」 を加えて (adding \"~ing\" to a verb) 主語 (subject) や 目的語 (object) にすると考える (think of this as) と良いでしょう (e.g., 'playing').","pattern":"V-Dictionary form + こと"},{"meaning":"恩恵 (a favor) を受ける (receiving) か、誰かに何かをしてもらう (having someone do something for you) ことを示します (indicates).","example":"家族にお弁当を作ってもらって","pattern":"V-te + もらう","tip":"誰が与える人か (who the giver is) に焦点を当てる (focus on); 彼らは 助詞 (particle) 「に」 で示されます (they are marked with the particle 'に').","jlpt":"N4"},{"tip":"「とおり」と発音され (pronounced 'とおり'); 文字通り (literally) 「～の経路をたどる (following the path of)」 という意味です (it means).","pattern":"Noun + の + 通り(に) / V-form + 通り(に)","jlpt":"N3","meaning":"計画通りに (exactly as planned) または 指示通りに (as instructed) 何かをする (doing something).","example":"予定の通りに進みます。"},{"tip":"これを 「～たびに (whenever)」 または 自然 (nature) や 機械 (machines) の説明 (descriptions) のような 一定の結果 (constant results) に使用します (use this for).","pattern":"V-plain / い-adj + と","jlpt":"N4","meaning":"自然な結果 (a natural consequence) や 予測可能な結果 (a predictable outcome) を示します (indicates) (Aが起きればBが続く (If A happens, B follows)).","example":"午後3時ごろになると、疲れます。"},{"meaning":"「私は [X] と言いますが (although I say [X])、現実は少し異なります (the reality is slightly different) か、より具体的です (or more specific).","example":"仕事部屋と言っても、実はそこは若い女の人の部屋です。","tip":"誤解 (misunderstanding) を招く可能性のある (might lead to) 発言 (a statement) を 明確にする (clarify) または 限定する (qualify) ためにこれを使用します (use this to).","pattern":"～と言っても","jlpt":"N3"},{"jlpt":"N5","tip":"名詞 (nouns) (「の」 が必要 (which need 'の')) とは異なり (unlike)、動詞 (verbs) は、たとえ動作が過去 (past) に起こったとしても (even if)，常に 辞書形 (Dictionary form) を使用します (always use).","pattern":"V-Dictionary form + 前に","example":"女の人が銀行から帰る前に","meaning":"動作 (an action) をする前に (before doing)."},{"meaning":"何かをする (to do something) 計画 (a plan) や 意図 (intention) を表現する (expressing).","example":"結婚する予定です。","pattern":"V-Dictionary form + 予定です","tip":"これは、すでに決定されている (already been decided) 具体的な計画 (concrete plans) や スケジュール (schedules) に使用します (use this for).","jlpt":"N4"}],[{"example":"歩くことができなくなりました","jlpt":"N5","tip":"「ことができる (can do)」 と 「なる (to become)」 を組み合わせたものです (it combines); 能力 (ability) の変化 (a change) を説明します (it describes).","meaning":"何か (something) がもはや不可能になる (no longer possible) 状態になる (to become) / その状態に達する (to reach a state where).","pattern":"Dictionary form + ことができなくなる"},{"tip":"服 (clothes) や 靴 (shoes) を履いたまま寝る (sleeping with on) などの、少し変わった (slightly unusual) 状況 (situations) でよく使用されます (often used for).","pattern":"Verb (Plain past) + まま / Noun + のまま","meaning":"状態をそのままにして (leaving a state as it is) 何かをする (to do something); 「そのまま (left as is)」 または 「まだ (still)」.","jlpt":"N4","example":"コートを着たまま寝ました"},{"example":"電気をつけようとしました","jlpt":"N4","meaning":"何かをしようとする (to try to do something) / 何かをしようとしている (to be about to do something).","pattern":"Volitional Form + とした","tip":"これは、試み (the attempt) がなされたが (was made but) おそらく完了しなかった (perhaps not completed) か、中断された (interrupted) ことを意味します (this implies)."},{"jlpt":"N4","example":"キクちゃんは笑いながら","pattern":"Verb (Stem) + ながら","meaning":"一つの行動をしながら、別の行動をする (simultaneous actions)。","tip":"主となる行動は「ながら」の後に来ます。この文では、「グラスを持ってくる」が主な行動であり、「笑う」という行動を伴っています。"},{"jlpt":"N4","example":"ろうそくをつけてくれたら","tip":"これは最も汎用性の高い「if」の形です。これはしばしば、時間的な順序を表すのに使われます。「Aが起こったら、次にBが起こる」のように。","pattern":"Verb (Plain past) + ら","meaning":"もし～なら / ～の時；結果のための条件や要求を表す。"},{"example":"悪いことをしてしまうかもしれません","jlpt":"N4","meaning":"〜かもしれない；何かが起こる可能性を表す。","pattern":"Short Form + かもしれない","tip":"話し手が不確かであるものの、何かが真実である、または起こると考える可能性がある場合に使用されます。"},{"tip":"この文脈では、現在までの繰り返しの習慣や積み重ねられた経験を示しています。","meaning":"今までずっと〜してきた；過去から続く継続的な行動。","pattern":"Verb (Te-form) + きた","example":"私は今まで... 失敗を何百回もしてきました","jlpt":"N3"},{"pattern":"A か B かしないと","meaning":"AかBかしないと；AかBが起こらない限り（ネガティブな結果が続く）。","tip":"文末の「ないと」は、「さもなければ悪いことが起こるだろう」という意味合いを持つことが多いです。","jlpt":"N3","example":"ろうそくの火が消える前に私が寝るか、お酒の酔いがなくなるかしないと"}]],"intermediate":[[{"jlpt":"N5","tip":"「私の趣味は〜です」や「〜が好きです」のように、行動を物として扱いたい場合に使います。","pattern":"Dictionary form + こと","example":"遊ぶことが何よりも好きです。","meaning":"動詞を名詞句に変える (nominalization)。"},{"pattern":"Dictionary form + と","tip":"この文脈では、出来事の習慣的な順序を説明しています：「戸が開くたびに…」","jlpt":"N4","meaning":"仮説的な結果または自然な結果（Aが起こると、Bが続く）。","example":"戸が開くと、嫌な顔をして文句を言うふりをしますが･･･"},{"tip":"動詞や形容詞の前にふりを使う場合は、Dictionary form を使います。名詞の場合は、「名詞＋の＋ふり」を使います。","pattern":"Verb/Adjective/Noun + ふりをする","jlpt":"N3","meaning":"〜するふりをする；〜のように振る舞う。","example":"嫌な顔をして文句を言うふりをしますが･･･"},{"meaning":"〜ても；〜にもかかわらず。","example":"仕事をしていても、遠くから友達が訪ねて来るのを･･･","tip":"これは対比を生み出します。話し手は仕事をしているにもかかわらず、実際には友人が訪ねてくるのを待っています。","pattern":"～て + も","jlpt":"N4"},{"meaning":"〜している途中；未完成。","example":"書きかけの原稿をすぐに片付けて･･･","pattern":"Stem + かけ","tip":"これは、未完成の本や食べかけの食べ物のように、始まったがまだ完了していない行動に使われます。","jlpt":"N3"},{"example":"仕事部屋と言っても、実はそこは若い女の人の部屋なのです。","meaning":"〜と言っても；〜と呼ばれているが、実際は…","jlpt":"N2","tip":"誤解を招く可能性のある発言を明確にしたり、限定したりするためにこれを使用します。前の言葉に対する「現実確認」を提供します。","pattern":"～と言っても"},{"pattern":"Stem + そうな + Noun","tip":"動詞のstem とともに使用される場合、それはそのタイプの人に関連する可能性または典型的な行動を示します。","jlpt":"N3","meaning":"〜そうな＋名詞；〜のように見える；〜らしい；〜しそうな。","example":"人生経験が豊かな大人が言いそうなことを書いて･･･"},{"jlpt":"N4","pattern":"～よう(だ/です)","tip":"これは、話し手が観察または感知したものに基づいた推測または外見を表します。","example":"彼女は、その青年とあっさりと結婚するつもりのようでした。","meaning":"〜のようだ / 〜のようです；〜のように見える。"}],[{"pattern":"～かもしれない","tip":"カジュアルな会話では、文末に「かも」だけを使うことが多いです。","jlpt":"N5","example":"吐いてしまうかもしれない","meaning":"もしかしたら何かが起こるかもしれないという可能性を表す（50%以下の可能性）。しばしばネガティブな結果に使われます。"},{"jlpt":"N4","pattern":"～てしまう/～ちゃう","tip":"この文では、「やってしまった」は後悔の典型的な表現です。","meaning":"行動を完全に完了したことを表す、または何かをしてしまったことを後悔/偶然したことを表すときに使われます。","example":"寝てしまいました"},{"pattern":"～そうにない / ～そうもない","tip":"これは「〜そう（な/に）」の否定形です。形容詞のい-endingを「そうにない」に、または動詞のます-stemを「そうにない」に変えます。","jlpt":"N4","example":"歩いて帰れそうにない","meaning":"ある事が起こる可能性が低い、または現在の状況から見て不可能であるように思われる事を表します。"},{"example":"足袋を履いたまま寝ている","meaning":"ある状態や条件を維持したままで何かを行う事を表します。","tip":"通常は変更されるような事柄に良く使われます。例えば、下駄を履いたまま (with geta still on) 寝る (to sleep) や、服を着たまま (with clothes still on)。","pattern":"～まま","jlpt":"N4"},{"pattern":"～くらい / ～ぐらい","tip":"特定の行動と比較することで、状況がいかに激しいかを強調したいときにこれを使います。","jlpt":"N3","example":"歩けないくらい酔っ払っていました","meaning":"例を挙げる事によって、状態の程度や範囲を示します。「〜するほど...」"},{"example":"おしっこをしたものなんだよ","meaning":"過去の一般的な習慣、社会規範、または客観的な事実を説明するのに使われます。「よく〜したものだ...」","tip":"過去形の動詞とともに使うと、懐かしさを伝えるか、過去の頻繁な行動を説明します。","pattern":"～（た）ものだ / もんだ","jlpt":"N3"},{"jlpt":"N2","tip":"これは「〜ないで済む」の丁寧で形式的な同等物です。否定的な状況を避けることへの安堵をしばしば暗示します。","pattern":"～ずに済む","meaning":"何かをせずに済ませる、または管理する。「ず」は丁寧な否定形です。","example":"間違いを起こさずに済む"},{"meaning":"現実が予想とは正反対であるか、あるいは予想よりもはるかに極端であることを強調するのに使われます。「〜どころか...」","example":"酔いが覚めるどころか、体が熱くなり...","jlpt":"N2","pattern":"～どころか","tip":"対照に重点を置きます。「AどころかB」は、Aが真実でないだけでなく、さらに極端なBが真実であることを意味します。"}]],"original":[[{"tip":"「〜から」と比較して、「〜ので」はより丁寧で客観的であり、状況を説明する際によく使われます。","jlpt":"N5","example":"私は遊ぶ事が何よりも好きなので","meaning":"理由や原因と結果を結びつけるのに使われます（〜なので）。","pattern":"～ので"},{"tip":"文学では、これはしばしば話者の社会的地位、または行動を行う人物に対する権威を示します。","jlpt":"N4","meaning":"使役形は、誰かに行動をさせる、または許すことを示します。","pattern":"～させる (使役形)","example":"弁当を作らせ、それを持ってその仕事部屋に出勤する。"},{"jlpt":"N3","tip":"「も」を追加すると、文の二つの半分の間の対比が強調されます。","pattern":"～ながら（も）","meaning":"二つの行動や状態が同時に起こることを表すか、矛盾を示します（〜ながらも）。","example":"家で仕事をしていながらも"},{"tip":"対話では、話し手の発言に説明的または説得的な調子を加えることがよくあります。","jlpt":"N3","meaning":"理由を説明したり、背景情報を提供したり、発見を強調したりするのに使われます。","pattern":"～のだ (んだ)","example":"あほらしく見えるんだからね。"},{"example":"結婚する気でいるようであった。","meaning":"意図、心の状態、または何かをしたいという気持ちを表します。","pattern":"～気でいる","tip":"これは一時的な決定ではなく、持続的な心の状態を表します。","jlpt":"N3"},{"example":"私には思われて来た。","pattern":"～（れ）てくる (自発)＋てくる","meaning":"動詞の自発形に「てくる」が続く形です。自然に湧き上がる思考や感情を表します。","jlpt":"N2","tip":"この組み合わせは、「思う（おもう）」（to think）や「感じる（かんじる）」（to feel）のような感覚動詞や精神動詞で非常に一般的で、視点の段階的な変化を示します。"},{"example":"ひとかどの苦労人の言いそうな事","pattern":"～そう（な/に）","meaning":"「〜のように見える」「〜そうである」「〜しそうである」という意味の接尾辞です。","jlpt":"N2","tip":"動詞のstemに名詞修飾語として付く場合（〜そうな＋名詞）、その名詞の性質や行動の可能性を記述します。"}],[{"example":"大酒を飲むのは、毎夜の事であって、なにも珍らしい事ではない。","meaning":"動詞を名詞化するために使われ、その行動についての声明を出すためによく使われます。","tip":"これを使って行動を定義します。例えば、「働くのは楽しいです（はたらくのはたのしいです）」 (Working is fun)。","pattern":"～のは～だ","jlpt":"N5"},{"meaning":"「〜てしまう」のくだけた省略形で、完了や後悔、偶発的な行動を表します。","tip":"くだけた会話では、「〜てしまう」は「〜ちゃう」になり、「〜でしまう」は「〜じゃう」または「〜じまう」になります。","jlpt":"N4","pattern":"～ちまう / ～ちゃう","example":"このままで、寝ちまうからね。"},{"example":"歩けないくらいに酔っていた。","tip":"言及された行動につながるほど強烈な状態を表すことがあります（例：「歩けないくらいに疲れている」）。","meaning":"状態の範囲や程度を示し、「～の程度まで」を意味します。","jlpt":"N3","pattern":"～くらい / ～ぐらい"},{"jlpt":"N3","pattern":"～そうもない","meaning":"あることが起こる可能性が非常に低いことを示します。「おそらく～ないだろう」を強調します。","tip":"これは「～そうだ」のより強い否定形です。何かが不可能だと感じるときによく使われます。","example":"歩いて行けそうもないんだ。"},{"pattern":"～のに","jlpt":"N3","meaning":"～にもかかわらず、～なのに。驚き、後悔、または不満を表します。","tip":"「が」とは異なり、「～のに」は予期せぬことや不満という感情的なニュアンスを含みます。","example":"足袋をはいているままで寝ているのに気附いて..."},{"pattern":"～かける / ～かけの","jlpt":"N3","tip":"「食べかけ」や「飲みかけ」など、まだ終わっていないことを示すためによく使われます。","meaning":"動作や状態が始まったが終わっていないことを示し、「～の途中」を意味します。","example":"酒が苦痛になりかけて来た時に..."},{"pattern":"～ずにすむ","jlpt":"N2","meaning":"何かをせずに過ごすこと。ある行動を避けることができることを意味します。","tip":"これは「～ないで済む」のより丁寧な形です。あるタスクや問題を回避できたことに安堵するときに使います。","example":"何事も仕出かさずにすむと思った。"},{"pattern":"～的 (てき)","jlpt":"N2","meaning":"名詞を「～的な」という意味の形容動詞に変える接尾語です。","tip":"「科学的」や「効率的」のような抽象的な記述子を作成するためによく使われます。","example":"本来は貴族的な事なんだ。"}]]},"gyofukuki":{"simplified":[[{"example":"秋になると、木の葉が赤や黄色になって...","tip":"「自然な結果」の条件と考えてください。季節や方向によく続きます。","pattern":"～と","jlpt":"N5","meaning":"Aが起こると、Bが自然に、または必然的に続くことを示します。自然現象、機械、習慣に使われます。"},{"jlpt":"N3","meaning":"～から～にかけて（時間または空間の範囲を曖昧な境界線で表現します）。","tip":"特定の終点を示す「～から～まで」とは異なり、「～にかけて」は一般的な領域や期間を示唆します。","example":"夏から秋にかけて、たくさんの人が遊びに来ます。","pattern":"～から～にかけて"},{"pattern":"V-stem + やすい","tip":"イ形容詞のように扱われます。反対は「～にくい」（するのが難しい）です。","example":"崖は水で滑りやすかったです。","meaning":"何かをするのが簡単である、または何かをする傾向があること。","jlpt":"N4"},{"pattern":"V-stem + ながら","example":"お酒を飲みながら言いました。","tip":"主な行動が後に来ます。ここでは「話すこと」が主な焦点で、「飲むこと」は付随的な行動です。","jlpt":"N5","meaning":"AをしながらBもする。同じ人物によって2つの行動が同時に行われていることを示します。"},{"meaning":"Xをするときはいつでも（毎回）、Yが常に起こることを意味します。","jlpt":"N3","pattern":"V-Dictionary form + たびに","example":"滝を見るたびに、その蛇を考えました。","tip":"繰り返される偶然の一致や一貫した感情的な反応を強調するためにこれを使います。"},{"tip":"試みや行動が始まる直前の瞬間を表します。行動が失敗したことを示唆することがよくあります。","example":"草を取ろうとしました。/ スワを捕まえようとしました。","pattern":"V-volitional + と（する/している）","jlpt":"N4","meaning":"何かをしようとすること、または何かをしようとしていること。"},{"example":"お父さんが言ったように、私は大きい蛇になった。","tip":"動詞の後に来ると、「～のやり方で」または「～が言った/したように」という意味によく使われます。","pattern":"V-plain + ように","jlpt":"N3","meaning":"～のように（行動や状態が他の何かと似ていることを示すために使われます）。"}]],"intermediate":[[{"jlpt":"N5","meaning":"2つ以上の名詞を網羅せずに列挙するために使われます（「AやBなど」という意味）。","example":"赤や黄色に色づいて","pattern":"～や～(など)","tip":"すべてを列挙する「～と」とは異なり、「～や」は言及されていない他のカテゴリのものが存在する可能性を示唆します。"},{"jlpt":"N4","example":"春が来るのをじっと待っていました。","meaning":"動詞句を名詞節に変え、しばしば文の目的語として使われます。","tip":"行動を物事のように説明したいときにこれを使います（例：「待つという行為」）。","pattern":"V-(辞書形)＋の"},{"jlpt":"N4","example":"滝を見るために集まり","meaning":"目的や理由を示す（「～するために」）","tip":"動詞の後に続く場合は常に辞書形を使用し、意識的な目標を示します。","pattern":"V-(辞書形)＋ために"},{"jlpt":"N4","meaning":"動作の完了を表現し、しばしば後悔、事故、または不本意な気持ちを伴います。","example":"足を滑らせて落ちてしまった","tip":"話し言葉では、これはしばしば「ちゃった」または「じゃった」に縮約されます。","pattern":"～てしまう / ～てしまった"},{"jlpt":"N3","meaning":"(A)が起こるたびに、(B)も常に起こる。","example":"滝壺の水を見るたびに、蛇のことを想像していました。","tip":"行動と感情や結果との反復的なつながりを強調するためにこれを使用してください。","pattern":"V-(辞書形) / Nの＋たびに"},{"tip":"明確な終点がある「～から...まで」とは異なり、「～にかけて」はよりおおよそであるか、地域/時間の全体にわたっています。","pattern":"～から～にかけて","jlpt":"N3","example":"夏の終わりから秋にかけて","meaning":"時間的または空間的な範囲を表現し、「～から～まで」または「～の期間にわたって」を意味します。"},{"tip":"これに「～そうだ」や「～ということだ」のような結果を組み合わせて、聞いたことを報告します。","pattern":"～（が）言うには / ～によると","example":"父親が言うには、その蛇はもともと人間だったそうです。","meaning":"情報の情報源を示すために使用され（「～によると」）、その後に伝聞が続きます。","jlpt":"N3"}]],"original":[[{"tip":"くだけた会話では、これは「～んだ」になります。単に事実を述べるのではなく、状況を説明するときに使用してください。","example":"ぼんじゅ山脈というのである。","meaning":"理由を説明したり、背景情報を提供したり、声明を強調したりするために使用されます。文学では、しばしば物語的、説明的な調子を与えます。","jlpt":"N5","pattern":"～のである / ～のだ"},{"pattern":"～さえ","tip":"「に」や「で」のような助詞と一緒に使用すると、「にさえ」または「でさえ」になります。否定文では、能力や結果の完全な欠如を強調します。","meaning":"極端な例を挙げることで何かを強調するために使用され、「さえ」または「～ですら」を意味します。","example":"客を振りかえさすことさえ出来なかった。","jlpt":"N4"},{"pattern":"～と (conditional)","tip":"この特定の「と」は、道案内をしたり、自然現象を説明したりするためによく使用されます（例：「左に曲がると見えます」）。","meaning":"ある行動や出来事が起こると、別の行動が自動的に、または当然の結果として続くことを示します。","example":"川を二里ばかりさかのぼると","jlpt":"N4"},{"pattern":"～から～にかけて","jlpt":"N3","meaning":"時間または空間のおおよその範囲を示し、おおよそ「～から～」または「～から～まで」を意味します。「～から...まで」ほど正確ではありません。","example":"夏の末から秋にかけて","tip":"時間や場所の境界が固定された点ではなく、あいまいであるか連続的である場合に使用してください。"},{"pattern":"～つつ (continuation)","example":"岩を噛みつつ流れ出ていた。","meaning":"2つの動作が同時に起こっていることを記述します。それは「～ながら」よりも正式で文学的です。","jlpt":"N2","tip":"継続的な状態や進行中の動きを描写するために、書面での記述でよく使用されます。"},{"pattern":"～（の）ではなくて～","meaning":"「Aではなく、Bである」と言うことで誤解を訂正するために使用されます。","example":"飛び込んだのではなくて、まったくの過失からであった。","jlpt":"N2","tip":"これは、点を明確にしたり、状況の本当の理由を提供したりする強力な方法です。"},{"jlpt":"N2","example":"足だまりにしていた頭ほどの石ころが","meaning":"比較によって程度や範囲を示します。この文脈では、石の物理的なサイズ（「頭ほどの大きさ」）を記述しています。","tip":"「ほど」は数字に対して「約」を意味することもありますが、「頭」のような名詞の後に使用すると、尺度の鮮やかな比較が作成されます。","pattern":"～ほど (degree/extent)"}]]},"sakura":{"simplified":[[{"jlpt":"N5","pattern":"～んです / ～のです","example":"桜の木の下には、死体があるのです。","tip":"Use this when you want to make your statement sound like a logical explanation or a discovery.","meaning":"Explaining a reason, providing emphasis, or clarifying a situation."},{"meaning":"The ability or inability to do something.","tip":"This is more formal than the potential form. It turns a verb into a Noun phrase using こと first.","example":"あんなにきれいに咲くことは、信じることができません。","pattern":"辞書形 + ことができる / ことができない","jlpt":"N5"},{"pattern":"可能形 (可能動詞)","jlpt":"N5","tip":"The text uses 信じられない (cannot believe), where the original verb is 信じる (to believe).","example":"信じることができません。","meaning":"Used like \"cannot\" or \"can\" to express ability. Transform verbs into potential form."},{"example":"桜がきれいすぎますから","tip":"For adjectives, drop the い or な before adding this. It indicates that the degree is beyond what is desirable.","meaning":"To do something too much or to be excessive.","jlpt":"N4","pattern":"～すぎる"},{"pattern":"～てみる / ～てみてください","jlpt":"N4","meaning":"Used to suggest or ask someone to try doing something.","tip":"It literally means \"try and see.\" Use the て-form of the verb.","example":"考えてみてください。"},{"meaning":"Describes a continuous state or an ongoing action.","example":"死体が埋まっています！","tip":"In this text, it often describes a state (like being buried or being blooming) rather than a current action.","jlpt":"N4","pattern":"～ている"},{"pattern":"～時 (とき)","jlpt":"N4","meaning":"Specifying the time when an action or state occurs.","tip":"Think of it as \"when.\" Use the Dictionary form of verbs or adjectives before it.","example":"夜、家に帰る時"},{"pattern":"～のような / ～のように","jlpt":"N4","tip":"Use のような before nouns and のように before verbs or adjectives.","example":"ナイフのような物","meaning":"Used to describe something by comparing it to something else (simile)."},{"pattern":"（疑問詞）～か","jlpt":"N4","meaning":"Used to include a question within a larger sentence.","tip":"When using a question word like どうして, the verb before か must be in the Dictionary form.","example":"どうして不安だったか"},{"meaning":"Expressing a conditional \"if... then...\" relationship.","example":"そうすれば、私がどうして不安だったか、あなたも分かるでしょう。","tip":"すれば comes from する. It implies that if the first action happens, the second will naturally follow.","jlpt":"N4","pattern":"～ば (条件形)"},{"tip":"Attach to the Stem (the part before ます) to turn a verb into a Noun meaning \"how to [verb]\".","example":"美しい考え方でしょう。","meaning":"The way or method of doing something.","pattern":"動詞の形 (ます・stem) + 方 (かた)","jlpt":"N4"},{"meaning":"Thanks to; because of (used for positive or desired results).","tip":"It's the opposite of せいで, which is used for negative or blamed results.","example":"この考えのおかげで","pattern":"～おかげで","jlpt":"N3"},{"meaning":"Finally; at last (after some effort or waiting).","example":"やっと静かな気持ちで桜を見ることができます。","tip":"Use this when a desired outcome is finally reached after a struggle or long duration.","jlpt":"N3","pattern":"やっと"}],[{"pattern":"～へ/～に (Direction/Destination)","jlpt":"N5","example":"昨日、私はある谷へ行きました。","meaning":"Indicates direction or destination.","tip":"While both work, へ focuses on the direction, whereas に focuses on the destination itself."},{"tip":"Use this when introducing a word or concept that the listener might not know.","meaning":"Used to define or identify something by name.","example":"かげろうという虫","jlpt":"N5","pattern":"～という (Called/Named)"},{"pattern":"～ていく (Going to/Moving away)","example":"飛んでいきました","jlpt":"N4","meaning":"Describes an action moving away from the speaker’s current perspective.","tip":"It can describe physical movement (going away) or a change moving toward the future."},{"pattern":"～ます (Polite Form)","jlpt":"N4","example":"美しい結婚をします","meaning":"Polite form ending. Used to describe a habit or future action.","tip":"Standard polite Japanese. Verbs change depending on whether they are Group 1, 2, or 3."},{"pattern":"～ように (Just like/As)","jlpt":"N4","example":"知っているように","tip":"When used with verbs, it often means \"in the way that...\" or \"so as to...\".","meaning":"Indicates a likeness, manner, or 'just as' something is."},{"tip":"Commonly used for giving directions or describing what happens when you press a button.","meaning":"Indicates a natural consequence or an unexpected discovery after an action.","example":"少し歩くと","jlpt":"N4","pattern":"～と (Natural Consequence/Condition)"},{"example":"数えることができない","jlpt":"N4","pattern":"～ことができる (Can/Potential)","meaning":"The Dictionary form verb + ことができる indicates potential or ability.","tip":"Adding できない makes it negative (\"cannot\"). This is the formal equivalent of the potential verb form."},{"tip":"Always use the past tense (た-form) before 後 to show the action is finished.","meaning":"Indicates that an action takes place after another action is completed.","pattern":"～た後で/～た後 (After doing)","example":"卵を産んだ後の","jlpt":"N4"},{"pattern":"～（ん）です/～（の）だ (Explanatory Tone)","example":"光っていたのです","jlpt":"N4","meaning":"Used to provide an explanation, emphasize a reason, or add emotional weight.","tip":"In writing, のだ/のです is more common; in speech, んだ/んです is used."},{"pattern":"～時 (When), tip:","example":"見た時","jlpt":"N4","tip":"Connects directly to the Dictionary form or past tense of verbs.","meaning":"Indicates the time or occasion when something happens."},{"meaning":"The causative form indicates making or letting someone do something.","tip":"For Group 1 verbs, change the final vowel to the 'a' sound and add せる. Form Group 2, replace る with させる.","example":"私を喜ばせません","jlpt":"N4","pattern":"～（さ）せる (Causative)"},{"meaning":"Describes a current state resulting from a previous action or a continuous action.","tip":"When used with intransitive verbs like 埋まる, it describes a result or state rather than an ongoing action.","jlpt":"N4","example":"埋まっています","pattern":"～ている (State/Continuous)"},{"jlpt":"N4","example":"満足させる死体があると考えました","pattern":"～と思う/～と考える (Think that)","tip":"Use と to mark the entire Clause being thought. 考える implies more logical deliberation than 思う.","meaning":"Used to express a thought, opinion, or belief."},{"jlpt":"N4","example":"考えてみてください","pattern":"～てみる (Try doing)","tip":"Combined with ください, it becomes a polite request for the listener to \"try\" considering something.","meaning":"Indicates doing something to see what it is like, or to try an action."},{"tip":"When combined with the potential form, it expresses the feeling that an action is now possible.","meaning":"Indicates that something appears likely to happen or seems to be a certain way.","pattern":"～そうです (Looks like/Seems like), tip: <a>,tip:","jlpt":"N4","example":"飲むことができそうです"},{"example":"数えることができないくらい","jlpt":"N3","pattern":"～くらい/～ぐらい (Degree/Extent)","tip":"Use this to stress that the level of something is so high it can be compared to the following statement.","meaning":"Indicates the extent or degree of something."},{"pattern":"～になる (To become)","jlpt":"N3","example":"桜の木と一つになって","tip":"With nouns, add に before なる. It shows a transformation or the result of a process.","meaning":"Indicates a change in state or becoming something."}]],"intermediate":[[{"tip":"When used with intransitive verbs like 埋まる (to be buried), it describes a persistent state.","jlpt":"N5","pattern":"～ている","example":"死体が埋まっている","meaning":"Describes a state resulting from a previous action or an ongoing state."},{"tip":"Combine the て-form of a verb with もいい to ask for or give permission.","pattern":"～てもいい","jlpt":"N5","example":"信じてもいいことなんだよ","meaning":"Expresses permission or that something is acceptable."},{"example":"桜の花があんなにも見事に咲くなんて","meaning":"Emphasizes surprise, disbelief, or strong emotion regarding a fact.","jlpt":"N4","pattern":"～なんて","tip":"It functions similarly to など but carries a stronger nuance of shock or disdain."},{"jlpt":"N4","pattern":"～られる (可能形)","tip":"For 一段 verbs like 信じる, replace the final る with られる.","meaning":"Potential form of a verb used to show ability or possibility (in this case, inability).","example":"信じられないことじゃないか"},{"example":"信じられないことじゃないか","meaning":"A rhetorical question used to seek confirmation or emphasize an opinion.","pattern":"～じゃないか","jlpt":"N4","tip":"In masculine or casual speech, it sounds like \"isn't it?\" or \"can't you see?\"."},{"example":"綺麗すぎるせいで","meaning":"Indicates a negative cause or reason; \"because of / due to\".","pattern":"～せいで","jlpt":"N4","tip":"Unlike から or ので, this is almost always used for undesirable outcomes."},{"example":"心が空っぽになったような気持ちになったのだ。","meaning":"Expresses resemblance or a likeness; \"it felt as if...\".","tip":"Use ような to modify nouns and ように to modify verbs or adjectives.","pattern":"～ような / ～ように","jlpt":"N4"},{"jlpt":"N4","pattern":"～てみてくれ","tip":"This is a casual request (くれ) asking someone to try doing something for the speaker's sake.","meaning":"Combining the \"try and see\" (～てみる) and \"do for me\" (～てくれる) structures.","example":"想像してみてくれ"},{"tip":"When used with emotion verbs like 不安になる, it means to \"make (someone) feel\" that emotion.","pattern":"～させる (使役形)","jlpt":"N4","example":"不安にさせていたか","meaning":"Causative form; to make someone do something or to let someone do something."},{"tip":"Usually preceded by the Dictionary form to show a new habit or the potential form to show a new ability.","jlpt":"N4","pattern":"～ようになる","example":"見ることができるようになったのだ。","meaning":"Indicates a change in ability or habit; \"to reach the point where...\""},{"jlpt":"N3","pattern":"～ようだ","tip":"Often occurs with まるで to create a strong simile.","example":"上っていくのが見えるようだ。","meaning":"Used to express a subjective appearance or feeling based on the speaker's intuition."},{"example":"死体が埋まっている！","meaning":"The passive form of a verb, often used to describe events from the perspective of the object.","tip":"In this text, 埋まっている uses the intransitive state, but the concept of being buried is central.","jlpt":"N3","pattern":"～れる / ～られる (受身形)"},{"pattern":"～だろう / ～でしょう","jlpt":"N3","tip":"It can be used to soften a statement or to ask for the listener's agreement.","meaning":"A conjecture or a polite way to state an opinion; \"I suppose\" or \"probably\".","example":"お前にも納得できるだろう。"}],[{"jlpt":"N3","meaning":"Just as; in the same way as; according to","tip":"When following a Noun, it often becomes ～どおり. When following a verb, it describes doing something just as it is shown or known.","example":"お前も知っている通り","pattern":"～通り"},{"pattern":"～ていく","example":"谷の空に向かって舞い上がっていくのが見えた。","jlpt":"N3","meaning":"Changing state or action moving away from the speaker; or continuing into the future","tip":"Used here to describe the physical movement of insects flying away into the distance."},{"pattern":"～と（発見）","tip":"Often used in narratives for dramatic effect when a character notices something new after an action.","meaning":"When X happens, Y follows (often an unexpected discovery)","jlpt":"N4","example":"しばらく歩いていると、俺は変なものを見た。"},{"jlpt":"N3","tip":"Attaching the potential negative of 切る (to cut) to a Stem indicates an impossible volume or extent.","meaning":"Cannot do entirely; unable to finish doing","example":"何万匹とも数えきれない","pattern":"～きれない"},{"pattern":"～ような","example":"死体を好む変質者のような","jlpt":"N4","meaning":"Like; similar to; appearing as","tip":"Used to make a simile. Remember that it functions like a な-adjective when modifying a Noun."},{"example":"風景に過ぎない。","jlpt":"N2","tip":"Derived from 過ぎる (to pass/exceed), it literally means it doesn't cross the line beyond the mentioned state.","meaning":"Nothing more than; merely; just","pattern":"～に過ぎない"},{"example":"そのバランスがあってはじめて","jlpt":"N2","tip":"Emphasizes that a new state or realization was impossible before the initial condition was met.","meaning":"Only after X happened; not until X","pattern":"～てはじめて"},{"pattern":"～てごらん","tip":"A softer way to tell someone to try something, often used by elders or in a slightly superior tone.","meaning":"Try doing (polite command/suggestion)","jlpt":"N3","example":"命の液でできていると想像してごらん。"},{"jlpt":"N2","tip":"Uses the volitional form. When used with inanimate objects, it suggests a stubborn persistence of a situation.","meaning":"Showing no intention of; stubbornly refusing to (non-human or abstract subjects)","example":"俺の頭から離れていこうとはしない。","pattern":"～（よ）うと（は）しない"},{"pattern":"～と同じ（だ）","example":"お酒を飲んで騒いでいる村人たちと同じ権利で","jlpt":"N4","meaning":"The same... as...","tip":"Used to compare two things as identical in nature or category."},{"pattern":"～気がする","tip":"Useful for expressing subjective feelings or intuitions rather than objective facts.","meaning":"To have a feeling that; to have a hunch that","jlpt":"N3","example":"花見の酒が飲めそうな気がするよ。"}]],"original":[[{"meaning":"State of being (resultant state or ongoing action)","pattern":"～ている","example":"屍体が埋まっている","tip":"For verbs of change like 埋まる (to be buried), this describes the current state resulting from that action.","jlpt":"N5"},{"meaning":"Explanatory particle expressing emphasis or providing a reason","pattern":"～んだ / ～のだ","example":"信じていいことなんだよ","tip":"Think of it as 'the fact is...' or 'it is that...'. It adds an emotional or explanatory tone to the statement.","jlpt":"N5"},{"meaning":"Permission or acceptability (it is okay to.../can...)","pattern":"～ていい / ～てもいい","example":"信じていいことだ","jlpt":"N4","tip":"In this context, it isn't just permission but expresses that it is 'fine' or 'justifiable' to believe it."},{"pattern":"～なんて","meaning":"Particle used to express surprise, contempt, or emphasis toward the preceding element","example":"見事に咲くなんて","jlpt":"N4","tip":"It often precedes an evaluation or emotion, effectively functioning like 'the likes of' or 'to think that...'."},{"example":"信じられないことじゃないか","pattern":"～じゃないか / ～ではないか","meaning":"Tag question or rhetorical confirmation (isn't it?)","tip":"In literature, this often signals a strong assertion or an attempt to convince the listener.","jlpt":"N4"},{"example":"想像してみるがいい","meaning":"Try doing something (to see how it is)","pattern":"～てみる","tip":"Used here to invite the listener to imagine a scenario as an experiment or test.","jlpt":"N4"},{"tip":"Use this for internal feelings, smells, or sounds that occur naturally rather than being consciously thought out.","jlpt":"N4","pattern":"～がする (気がする)","meaning":"To have a feeling/hunch that...","example":"信じられないもののような気がした"},{"example":"不安にしていたかが","meaning":"Causative structure (to make/let someone do/be)","pattern":"～せる / ～させる (不安にさせる)","tip":"In the text, 'fuan ni saseta' refers to the mystery making the narrator feel anxious.","jlpt":"N4"},{"jlpt":"N4","tip":"This indicates a high degree of probability in the speaker's mind.","example":"納得がいくだろう","pattern":"～だろう / ～でしょう","meaning":"Probably / right? (Expression of conjecture)"},{"jlpt":"N4","tip":"Used for comparisons. Here, the blooming flower is compared to a spinning top or a musical performance.","meaning":"In the same way as; like (Similarity/Metaphor)","pattern":"～ように","example":"静止に澄むように"},{"example":"撲たずにはおかない","meaning":"Will not fail to; cannot help but (Double negative emphasis)","pattern":"～ずにはおかない","tip":"This is a strong literary expression meaning something inevitably happens or a certain effect is unavoidable.","jlpt":"N3"},{"tip":"Used at the start of a sentence or phrase to answer a self-imposed 'why'.","jlpt":"N3","pattern":"～って (何故って)","meaning":"Because (Colloquial way to introduce a reason)","example":"何故って"},{"example":"同じようなことにちがいない","meaning":"Must be; no doubt that...","pattern":"～にちがいない","tip":"Expresses strong conviction based on some evidence or intuition.","jlpt":"N3"},{"example":"吸いあげる水晶のような液が","pattern":"～あげる (吸いあげる)","meaning":"Compound verb structure (Upward action)","tip":"Adding 'ageru' to the stem of a verb often indicates a vigorous upward motion.","jlpt":"N3"},{"example":"夢のようにあがってゆくのが見えるようだ","meaning":"Appears to be; seems as if (Based on appearance/imagination)","pattern":"～ようだ / ～ように","tip":"This expresses a subjective judgment or a metaphorical likeness.","jlpt":"N3"}],[{"jlpt":"N5","pattern":"～ている (～ていた)","tip":"In literature, the い in ている is often kept, whereas in casual speech it is frequently dropped.","example":"石の上を伝い歩きしていた。","meaning":"Past continuous action (was doing) or state."},{"tip":"Use の to describe actions you can perceive with your senses, like seeing or hearing.","pattern":"～の (名詞化)","jlpt":"N5","meaning":"Nominalizes a verb, turning a sentence or action into a Noun phrase.","example":"舞い上がってゆくのが見えた。"},{"jlpt":"N5","pattern":"～から","tip":"When combined with も, it emphasizes 'even from' or 'from both... and...'.","example":"あちらからもこちらからも","meaning":"Indicates a point of origin or source (from)."},{"jlpt":"N4","pattern":"～とおり","tip":"When attached directly to a Noun, it becomes どおり, but stays とおり after a verb in Dictionary form.","example":"おまえも知っているとおり","meaning":"In the same way as; just as..."},{"example":"舞い上がってゆく","meaning":"Indicates an action moving away from the speaker or a progression into the future.","jlpt":"N4","pattern":"～てゆく (～ていく)","tip":"In literary texts, ゆく is often used instead of いく for a more poetic or formal tone."},{"jlpt":"N4","pattern":"～と (条件)","tip":"This specific usage often introduces a scene or a discovery in narrative writing.","example":"しばらく歩いていると","meaning":"When A happens, B follows (often an unexpected discovery)."},{"meaning":"To have a certain feeling or intuition; it feels like...","example":"胸が衝かれるような気がした。","tip":"Use this for smells, sounds, tastes, or intuitive feelings (hunches).","pattern":"～がする / ～気がする","jlpt":"N4"},{"jlpt":"N4","tip":"Use ような to modify nouns and ように to modify verbs or adjectives.","pattern":"～ような / ～ように","example":"石油を流したような光彩","meaning":"Similar to; like; appearing as..."},{"pattern":"～（さ）せる / ～す (使役)","tip":"The ～す ending (like よろこばす) is a slightly older or more literary alternative to ～せる.","jlpt":"N4","meaning":"Causative form; to make or let someone do something.","example":"俺をよろこばすものはない。"},{"example":"屍体だったのだ。","meaning":"Used for explanation, emphasis, or providing a reason.","jlpt":"N4","pattern":"～のだ (～んだ)","tip":"In writing, のだ adds a tone of assertive explanation or discovery."},{"meaning":"Conveys that something looks or seems likely; \"looks like\".","example":"酒が呑めそうな気がする。","tip":"When used with a verb, attach it to the stem form (呑めそう). When used with an adjective, drop the final い.","pattern":"～そうだ (様態)","jlpt":"N4"},{"jlpt":"N3","pattern":"～（よ）うとしない","tip":"This uses the volitional form + としない. It often describes the behavior of others or even inanimate objects.","example":"離れてゆこうとはしない。","meaning":"To show no intention of doing something; to refuse to..."},{"meaning":"Unknown; cannot be measured (often used with 数の to mean countless).","example":"何万匹とも数の知れない","pattern":"～（は）知れない","tip":"Often used in the phrase かもしれない, but here it literally means the number is unknown/countless.","jlpt":"N3"},{"pattern":"～たち","tip":"While N5 level for basic use, understanding its nuance of 'and company' or 'group' is important in literature.","jlpt":"N3","meaning":"Pluralizing suffix for people.","example":"酒宴をひらいている村人たちと同じ権利で"},{"example":"さっぱり見当のつかない","meaning":"(Not) at all; (not) in the least (used with negative).","jlpt":"N2","pattern":"さっぱり～ない","tip":"Commonly used when someone is completely lost or has no clue about a situation."},{"jlpt":"N2","pattern":"～ばかり","tip":"While ばかり generally means 'only', when combined with に it emphasizes a specific recurring occasion.","example":"完成するときにばかり","meaning":"Only; nothing but; mostly (emphasizing a specific timing or condition)."}]]},"urashima":{"simplified":[[{"example":"浦島太郎という若い漁師がいました。","meaning":"Called; named (used to introduce a name or title)","tip":"Use this when introducing someone or something to a listener who might not know its name.","pattern":"～という","jlpt":"N5"},{"jlpt":"N5","pattern":"～ていました","tip":"This is the past tense of ～ている. It describes an action that was ongoing at a certain point in time.","meaning":"Continuous action or state in the past (was doing)","example":"子供たちが小さい亀をいじめていました。"},{"example":"弱い動物をいじめてはいけません。","meaning":"Must not; should not (strong prohibition)","pattern":"～てはいけません","tip":"Often used by adults to children or to state rules. Keep the は pronounced as \"wa\".","jlpt":"N4"},{"example":"海へ帰りなさい。","meaning":"Command form (do this)","tip":"This is a polite but firm command often used by parents or teachers. Remove the ます before adding なさい.","pattern":"～なさい","jlpt":"N4"},{"example":"亀を海へ帰してやりました。","meaning":"Doing something for someone (often of lower status or animals)","tip":"The verb やる implies giving downwards. It is less polite than ～てあげる and usually used for pets, plants, or younger siblings.","pattern":"～てやる","jlpt":"N4"},{"meaning":"When; if (indicating a natural consequence or an unexpected discovery)","example":"海のそばを歩いていると、子供たちが小さい亀をいじめていました。","jlpt":"N4","pattern":"～と（条件）","tip":"When used for discovery, the sentence following ～と is often something that surprised the speaker."},{"meaning":"To receive the favor of someone doing something for you","example":"あなたに助けてもらった亀です。","jlpt":"N4","pattern":"～てもらう","tip":"Focus on the receiver's gratitude. The person who performed the action is marked with the particle に."},{"jlpt":"N3","pattern":"～そう（様態）","tip":"For い-adjectives, drop the last い before adding そう. If the adjective is 良い, it becomes 良さそう.","meaning":"Seems; looks like (based on appearance)","example":"亀はとても苦しそうでした。"}],[{"example":"おいしいご飯を食べて、魚たちのきれいなダンスを見ました。","meaning":"Connects sentences or actions in a chronological sequence.","pattern":"～て（テ形）","jlpt":"N5","tip":"Think of this as the Japanese word for 'and' when connecting verbs or listing actions."},{"tip":"This follows the て-form of a verb. It is much softer and more polite than a command.","jlpt":"N5","pattern":"～てください","meaning":"Used to make a polite request.","example":"心配しないで、ゆっくり休んでください。"},{"meaning":"To do something for the benefit of the speaker; shows gratitude.","example":"亀を助けてくれて、ありがとうございました。","pattern":"～てくれる","jlpt":"N4","tip":"Use this when someone else performs a kind action for you. It emphasizes the favor received."},{"tip":"In this context, it often highlights a surprise or a scene that opens up upon performing the first action.","pattern":"～と（辞書形＋と）","jlpt":"N4","meaning":"When [Action A] happens, [Action B] (an inevitable or surprising discovery) follows.","example":"中へ入ると、とてもきれいな乙姫様と、･･･"},{"tip":"Unlike 見られる (can look), 見える suggests an object naturally enters your field of vision.","jlpt":"N4","pattern":"～見える（見える）","meaning":"The potential form indicating that something is visible or can be seen.","example":"冬の雪がいつでも見えました。"},{"tip":"Use のような before a Noun, and のように before an adjective or verb to create a simile.","pattern":"～のように / ～のような","jlpt":"N3","example":"竜宮城は夢のように素晴らしい所でした。","meaning":"Used to describe something by comparing it to another thing (like; as if)."}],[{"meaning":"Expresses the speaker's desire to do something (want to)","tip":"Replace the ます (masu) ending of a verb with たい (tai). It is used for the speaker's own desires.","pattern":"～たい","jlpt":"N5","example":"村へ帰りたいです"},{"jlpt":"N5","example":"絶対にこの箱を開けてはいけません","pattern":"～てはいけません","meaning":"Expresses a prohibition (must not/may not)","tip":"Formed using the て (te) form plus は (wa) and いけません (ikemasen). Use it for rules or strong warnings."},{"pattern":"～なければなりません","example":"早く帰らなければなりません","jlpt":"N5","tip":"This literally means \"if you do not, it won't do.\" Even though it is long, it should be practiced as one single melodic phrase.","meaning":"Expresses obligation (must/have to)"},{"pattern":"辞書形 + ことができる","jlpt":"N4","example":"開けなければ、また会うことができます","tip":"Combine the Dictionary form of a verb with ことができる (koto ga dekiru). It treats the whole action like a Noun that 'exists.'","meaning":"Expresses potential or the ability to do something"},{"jlpt":"N3","example":"乙姫様はとても悲しそうでした","pattern":"～そう（だ／です）","meaning":"Indicates that something looks or appears a certain way based on observation","tip":"With い-adjectives, remove the final い (i) before adding そう (sou). For な-adjectives, just add it to the stem."},{"jlpt":"N4","example":"玉手箱という宝物です","pattern":"～という","meaning":"Used to provide the name or definition of something (called...)","tip":"Use this when introducing a specific name or title that the listener might not know. A (name) という B (category)."},{"tip":"This is the negative conditional form. Change the final い (i) of the negative ない (nai) form to ければ (kereba).","meaning":"Expresses a conditional (if...)","example":"開けなければ、また会うことができます","jlpt":"N4","pattern":"～なければ"}],[{"pattern":"～も～も","jlpt":"N5","tip":"This structure is used to group items together to emphasize a shared state. In negative sentences, it means \"neither... nor...\".","meaning":"Both A and B / neither A nor B (in negative sentences)","example":"お父さんもお母さんもいません。"},{"meaning":"Using a verb in the Dictionary form to describe a Noun (Relative Clause)","example":"海へ行った人です。","pattern":"動詞（辞書形・た形）＋名詞","jlpt":"N5","tip":"Japanese doesn't use \"who\" or \"which.\" Simply put the verb phrase directly before the Noun it modifies."},{"pattern":"～たことがある","jlpt":"N5","tip":"Use the past tense (た形) before ことがある. This is for general life experiences, not things you did very recently like \"I ate breakfast.\"","meaning":"To have the experience of doing something","example":"聞いたことがあります。"},{"example":"開けてはいけない箱です。","meaning":"Must not / forbidden to do something","tip":"Based on the て-form. It expresses a prohibition. If you want to say \"it's okay to do,\" change it to ～てもいい.","pattern":"～てはいけない","jlpt":"N4"},{"pattern":"～てしまう","jlpt":"N4","tip":"In this story, it emphasizes that Urashima Taro opened the box even though he shouldn't have, leading to a regrettable result.","example":"開けてしまいました。","meaning":"To do something completely or to do something accidentally/regrettably"},{"meaning":"Might; perhaps; may (expresses possibility)","example":"戻ることができるかもしれない。","tip":"This follows the Dictionary form of verbs or nouns/adjectives. It suggests a possibility that may or may not be true.","pattern":"～かもしれない","jlpt":"N4"},{"tip":"Attach this to the stem of the verb (the part before ます). The main action is always the second verb.","pattern":"～ながら","jlpt":"N4","example":"泣きながら、ずっと青い海を見ていました。","meaning":"Doing something while doing something else (simultaneous actions)"},{"pattern":"～だらけ","jlpt":"N3","tip":"Use this with nouns that represent unpleasant things like \"mud,\" \"dust,\" \"blood,\" or in this case, \"wrinkles.\"","example":"顔もしわだらけになりました。","meaning":"Full of / covered in (usually for something negative or messy)"}]],"intermediate":[[{"example":"亀は逃げることもできず","meaning":"The negative connective form of a verb ('without doing' or 'and did not')","tip":"This is more formal than ～ないで. It is very common in written stories or formal speeches.","pattern":"～ず / ～ずに","jlpt":"N3"},{"example":"そんなひどいことをしてはいけないよ","meaning":"Expresses a prohibition or something that must not be done","pattern":"～てはいけない / ～てはならない","tip":"The ending ～てはいけない is the standard way to say 'must not', while ～てはならない sounds more like a strict rule or law.","jlpt":"N5"},{"pattern":"～かのように / ～かのようだ","tip":"Use this when describing a situation that seems like something else even though it might not literally be true.","jlpt":"N3","example":"お礼を言っているかのように","meaning":"As if; in a way that seems like..."},{"pattern":"～てやる / ～てあげる","tip":"In modern Japanese, ～てあげる is polite, but ～てやる is often used in stories for children, animals, or when someone older does something for someone younger.","jlpt":"N4","example":"助けてやりました","meaning":"Doing something for someone of lower status (or animals/plants)"},{"tip":"This is an advanced expression used with strong emotions like curiosity (好奇心), anxiety (不安), or impulse (衝動).","pattern":"～に駆られる","jlpt":"N1","example":"好奇心に駆られました","meaning":"To be driven by or overcome by a specific emotion or impulse"},{"meaning":"Similar to; like; looks like... (used for comparison)","example":"見たこともないような色鮮やかな魚たち","jlpt":"N4","pattern":"～のような / ～のように","tip":"Use ～のような before a Noun and ～のように before a verb or adjective to describe appearance or manner."},{"tip":"Combining a movement verb with ～まわる creates a nuance of moving 'around' or 'everywhere' (e.g., 走り回る - to run around).","pattern":"～回る (Stem + まわる)","jlpt":"N4","example":"歓迎するように彼の周りをぐるぐると泳ぎ回っていました","meaning":"To do something all over or around (indicates repetitive or extensive action)"}],[{"example":"一つの部屋にいながら同時に楽しむことができたのです。","meaning":"Potential form: to be able to do something.","jlpt":"N4","tip":"Use the Dictionary form of a verb before this pattern to express ability or possibility.","pattern":"～ことができる"},{"jlpt":"N4","pattern":"～てくれる","tip":"This emphasizes that the speaker (or someone they care about) is the grateful recipient of the action.","example":"太郎が門をくぐると、そこには・・・乙姫様と・・・家来たちが、彼を出迎えてくれました。","meaning":"To do something for someone as a favor or kindness."},{"tip":"This is a polite version of ～てもらう. Use it when expressesing gratitude to a superior or in formal situations.","pattern":"～ていただく","jlpt":"N4","meaning":"Humble way to say someone did something for you (receiving a favor).","example":"亀の命を救っていただき、本当にありがとうございました。"},{"example":"太郎が門をくぐると、そこには・・・","meaning":"When/if (natural consequence or discovery).","jlpt":"N4","tip":"Often used when one action immediately leads to another or to describe a discovery upon doing an action.","pattern":"～と"},{"jlpt":"N3","tip":"Attach this to the stem of a verb (the ます-form without ます) to show two actions happening simultaneously.","pattern":"～ながら","example":"一つの部屋にいながら同時に楽しむことができたのです。","meaning":"While; at the same time as."},{"jlpt":"N3","pattern":"～ほど","tip":"Used to emphasize the degree of an adjective or verb by providing a comparison or extreme example.","example":"この世の者とは思えないほど美しい乙姫様","meaning":"To the extent that; so much so that."},{"jlpt":"N2","tip":"The positive form ～きる means to finish completely. Adding ～ない emphasizes that the action is too vast or intense to finish.","pattern":"～きれない","example":"竜宮城の中は、人間の言葉ではとても表現しきれないほど・・・","meaning":"Cannot finish; unable to do something to completion."}],[{"jlpt":"N4","pattern":"～だろう（か）","tip":"It is the Dictionary form of ～でしょう. When followed by か, it expresses a internal question or doubt.","example":"両親は元気にしているだろうか。","meaning":"Indicates conjecture, thinking 'I wonder' or 'probably'."},{"meaning":"Indicates a strong conviction or certainty; 'must be' or 'no doubt'.","example":"泣いているに違いない","tip":"Use this when you have a logical reason or intuition to be 100% sure about something.","pattern":"～に違いない","jlpt":"N3"},{"pattern":"～なければならない","tip":"This sounds formal. In casual speech, people often use ～なきゃ or ～ないと.","jlpt":"N4","meaning":"Expresses obligation or necessity; 'must' or 'have to'.","example":"村へ帰らなければならない"},{"tip":"Adding 思う makes your desire sound less direct and more like a considered thought.","pattern":"～（たい）と思う","jlpt":"N4","meaning":"Used to express intentions or desires in a polite, slightly softer way.","example":"村へ帰りたいと思います"},{"tip":"The form changes depending on the word type: verbs use て-form, nouns and な-adjectives use でも.","pattern":"～ても / ～でも","jlpt":"N4","meaning":"Expresses 'even if' or 'no matter what'.","example":"何があっても"},{"meaning":"Used to express a strong prohibition; 'must not'.","example":"絶対にこの箱の蓋を開けてはいけません。","pattern":"～てはいけない","tip":"This is very direct. Often used by authority figures, in rules, or by parents to children.","jlpt":"N5"},{"pattern":"お～になる","tip":"This is highly polite (Sonkeigo). Put the Stem between お and になる. Amaze Japanese people by using it correctly!","jlpt":"N3","meaning":"The honorific form of a verb to show respect to the subject.","example":"どうしてもお帰りになるというのなら"}],[{"tip":"Think of it as a link between two nouns to clarify ownership or category. It is the most fundamental building block in Japanese.","jlpt":"N5","meaning":"Indicates possession, relationship, or location. (A no B = B of A)","pattern":"～の～","example":"浦島太郎の家はどこですか？"},{"tip":"Used for rules, warnings, or strong advice. If the verb ends in む, ぶ, or ぬ, the pattern changes slightly to ～ではいけない.","jlpt":"N4","meaning":"Must not (strong prohibition).","pattern":"～てはいけない","example":"乙姫様は絶対に開けてはいけないと言っていた。"},{"tip":"Usually implies that the expected outcome (returning, calling, etc.) never happened after the initial action. Often used with a negative result.","jlpt":"N3","meaning":"Ever since (doing something); denotes a state that continues after an action.","pattern":"～たきり","example":"三百年も昔に、若い漁師が海へ行ったきり、神隠しに遭って二度と帰ってこなかった"},{"tip":"When used after a Dictionary form verb, it describes a situation where one action happens repeatedly or exclusively.","jlpt":"N3","example":"首をかしげるばかりです。","meaning":"Does nothing but...; keeps on doing...","pattern":"～ばかり（です）"},{"example":"両親の姿はおろか、自分の小さな家は影も形もありませんでした。","meaning":"Let alone; not to mention (emphasizing that if the small thing is missing, the big/obvious thing is definitely missing).","pattern":"～はおろか","tip":"Often follows the structure \"A is a given/obvious, let alone B\". It is almost always used in sentences with a negative outcome.","jlpt":"N2"},{"tip":"In storytelling, this passive form is used to show the subject being victimized by an emotion or a situation beyond their control.","jlpt":"N2","example":"見知らぬ世界に取り残された孤独感に襲われ、海辺で途方に暮れました。","meaning":"Passive form of causative, but here used as a formal passive (to be attacked/overwhelmed).","pattern":"～に襲われる"},{"example":"いつまでも寂しく見つめ続けることしかできませんでした。","pattern":"～ことしかできない","meaning":"Have no choice but to...; can do nothing but...","jlpt":"N3","tip":"Combine the Noun-making こと with しか and a negative verb to show that all other options are gone. It expresses a sense of resignation."}]],"original":[[{"example":"浦島太郎というりょうしがありました。","tip":"Use this when introducing a specific name or title that the listener might not know.","meaning":"Called; named (used to introduce a name)","jlpt":"N5","pattern":"～という"},{"example":"棒でつついたり、石でたたいたり、さんざんにいじめているのです。","jlpt":"N5","pattern":"～たり～たりする","tip":"Always end the sequence with a form of する. It implies there are other similar actions not mentioned.","meaning":"Doing things like A and B (representative actions)"},{"example":"かめを海ばたまで持って行ってはなしてやりました。","jlpt":"N4","pattern":"～てやる","tip":"Be careful: it can sound condescending if used for people. In this story, it shows the character's kindness toward the turtle.","meaning":"To do something for someone (favor for an inferior or animal)"},{"tip":"When used with a past tense verb, it often implies a narrow escape from a negative situation.","meaning":"Was on the verge of; was just about to (a certain state)","jlpt":"N3","pattern":"（た形）＋ところだ","example":"あぶないところだった。"},{"tip":"This expression is often used to humbly decline a favor or suggest that such a great effort is not required.","meaning":"No need to; unnecessary to (polite or formal)","pattern":"～にはおよばない","jlpt":"N2","example":"わざわざ礼なんぞいいにくるにはおよばないのに。"},{"pattern":"（意向形）＋ともしない","jlpt":"N1","tip":"This uses the volitional form (おう/よう) to emphasize a complete lack of effort or willingness.","meaning":"Without even trying to; showing no intent to do something","example":"子どもたちはきき入れようともしないで。"}],[{"example":"歌をうたったり踊りをおどったりしました。","meaning":"Listing actions or states as examples among others.","tip":"Always conclude the sequence with a form of する. It implies that these are just a few examples of many possible activities.","pattern":"～たり ～たりする","jlpt":"N4"},{"example":"御殿のなかをのこらず見せてもらいました。","pattern":"～てもらう","jlpt":"N4","meaning":"To receive the favor of someone doing something.","tip":"This focuses on the gratitude or the fact that the subject requested/benefited from the action. Use it when someone does you a favor."},{"pattern":"～ようだ / ～ように","jlpt":"N3","tip":"Use this for subjective comparisons. When used at the end of a sentence, it becomes ようです. When modifying a verb, use ように.","meaning":"To be like; looking like (expressing similarity or appearance).","example":"夢を見ているようでした。"},{"example":"四季のけしきをお目にかけましょう","jlpt":"N3","pattern":"お目にかける","tip":"This is a set phrase in Keigo (honorific speech). Use it when you are showing something to someone of higher status to show respect.","meaning":"The humble version of 見せる (to show)."},{"pattern":"～てしまう","jlpt":"N4","tip":"In this context, it emphasizes completion. In casual speech, this often contracts to ちゃう.","meaning":"To finish doing something completely, or to do something accidentally/regrettably.","example":"ひととおり見てしまうと"},{"meaning":"To the extent that... / so much so that...","tip":"Use this to describe the magnitude of a situation by providing a comparison or an extreme example.","jlpt":"N3","pattern":"～くらい / ～ぐらい","example":"口やことばではいえないくらいでした。"},{"example":"お酒に酔った人のようになって","pattern":"～（に）なる / ～くなって","jlpt":"N4","meaning":"To become; to turn into. Used to describe a change in state.","tip":"Use に with nouns and Na-adjectives, and change the final い to く for I-adjectives. It indicates a process of change."}],[{"meaning":"Listing multiple actions amongst others (A and B for example)","example":"網をひいたり舟をこいだりしているところを","tip":"The final verb is always する, but it can be conjugated into any tense like した or している.","jlpt":"N4","pattern":"～たり～たりする"},{"tip":"Attach this to the ます-stem of the verb. The main action comes in the second half of the sentence.","jlpt":"N4","pattern":"～ながら","meaning":"Doing two actions simultaneously (while doing A, B)","example":"舟うたをうたいながら"},{"tip":"Use the Dictionary form of a verb to show a new habit has started, or the potential form to show a new ability.","jlpt":"N4","pattern":"～ようになる","meaning":"To reach a point where something happens; a change in habit or state","example":"夢を見るようになりました"},{"example":"ふさぎこんでばかりいました","meaning":"To do nothing but... / Always doing...","tip":"This often carries a negative nuance, suggesting that someone is doing something too much or neglecting other things.","pattern":"～てばかりいる","jlpt":"N4"},{"pattern":"いても立ってもいられない","jlpt":"N3","tip":"This is a common set phrase (idiom). The negative potential form shows that the person literally cannot stay in one place.","example":"いても立ってもいられなくなるような気がしました","meaning":"Feeling unable to remain still; implies high anxiety or restlessness"},{"jlpt":"N3","pattern":"お／ご～申し上げる","tip":"This is a very formal version of the standard humble form お～する. Focus on the prefix お for native Japanese verbs.","example":"おひきとめ申しても","meaning":"Humble language (Kenjougo) used to lower oneself and show respect to the listener"},{"pattern":"～てごらんになる","jlpt":"N3","tip":"This is the honorific (Sonkeigo) version of ～てみる. Teachers/elders use it when kindly suggesting someone do something.","example":"あけてごらんになってはいけません","meaning":"Honorific way to say \"to try to do\" or simply \"to do\" (looking/seeing nuance)"},{"example":"帰ってきたいとおぼしめすなら","meaning":"Honorific verb meaning 'to think' or 'to feel' (very formal)","tip":"This is one of the highest forms of honorifics for 思う. You will mainly encounter this in literature, historical dramas, or very formal settings.","pattern":"おぼしめす (思し召す)","jlpt":"N1"}],[{"jlpt":"N4","pattern":"～出す (～だす)","tip":"Use this for actions that start suddenly or move outward from the inside.","meaning":"Describes the beginning of an action. Combined with the Masu-stem of a verb.","example":"じぶんの家の方角へあるき出しました。"},{"tip":"In this context, it shows Urashima's subjective belief which contradicts the reality of 300 years passing.","pattern":"～つもり","jlpt":"N4","example":"たった三年りゅう宮にいたつもりなのに","meaning":"Used to express an intention or a conviction/belief that something was a certain way."},{"example":"みんなどこかへ行ってしまうはずはない。","meaning":"Expresses a strong confidence that something is impossible or cannot be the case.","tip":"Think of this as \"there is no expectation that...\" used for logical impossibility.","pattern":"～はずはない","jlpt":"N4"},{"meaning":"The conditional 'if' form. Often used for hypothetical results or suggestions.","example":"この箱をあけてみたらば、わかるかもしれない。","pattern":"～たらば (～たら)","jlpt":"N4","tip":"Adding 'ba' to 'tara' is a slightly older or more formal stylistic choice, but it functions just like the standard 'tara' conditional."},{"jlpt":"N3","pattern":"～てたまらない","tip":"Pair this with verbs or adjectives of feeling (e.g. hungry, lonely, wanting to do something).","meaning":"Used to express an emotion or physical sensation that is so strong it is \"unbearable\" or \"cannot be helped.\"","example":"りゅう宮がこいしくてたまらなくなりました。"},{"tip":"When you discover the reason for something or reach a conclusion (a \"lightbulb\" moment), use this pattern.","pattern":"～のだ / ～んだ","jlpt":"N3","example":"人間の寿命だったのだな。","meaning":"An explanatory particle used at the end of a sentence to show realization, emphasis, or to seek confirmation."}]]}};
